mapper.select:
/*isry.itgcm.fdrmrptstats.mapper.FdrmRptStatsMapper 발굴등록 통계 - selectUneartRegStats LEE.SEOUNG.JAE*/ SELECT * FROM( SELECT NVL(A.RCPT_RQST_COURS_LCLAS_SE_CD,'0') AS RCPT_RQST_COURS_LCLAS_SE_CD , NVL(A.RCPT_RQST_COURS_MLSFC_SE_CD, '0') AS RCPT_RQST_COURS_MLSFC_SE_CD , NVL(A.RCPT_RQST_COURS_SCLAS_SE_CD, '0') AS RCPT_RQST_COURS_SCLAS_SE_CD , NVL(A.RCPT_RQST_COURS_LCLAS_SE_NM, '합계') AS RCPT_RQST_COURS_LCLAS_SE_CD_NM , NVL(A.RCPT_RQST_COURS_MLSFC_SE_NM, '합계') AS RCPT_RQST_COURS_MLSFC_SE_CD_NM , NVL(A.RCPT_RQST_COURS_SCLAS_SE_NM, '합계') AS RCPT_RQST_COURS_SCLAS_SE_CD_NM , COUNT(CASE WHEN B.SXDC_SE_CD = 'M' OR B.SXDC_SE_CD = 'F' OR B.SXDC_SE_CD = 'X' THEN B.TRPR_INFO_NO END) AS UNEART_NOPE_T , COUNT(CASE WHEN B.SXDC_SE_CD = 'M' THEN B.TRPR_INFO_NO END) AS UNEART_NOPE_M , COUNT(CASE WHEN B.SXDC_SE_CD = 'F' THEN B.TRPR_INFO_NO END) AS UNEART_NOPE_F , COUNT(CASE WHEN B.SXDC_SE_CD = 'X' THEN B.TRPR_INFO_NO END) AS UNEART_NOPE_X , COUNT(DISTINCT CASE WHEN B.SXDC_SE_CD = 'M' OR B.SXDC_SE_CD = 'F' OR B.SXDC_SE_CD = 'X' THEN NVL(B.INDV_IDNTFC_NO, B.TRPR_INFO_NO) END) AS UNEART_REAL_NOPE_T , COUNT(DISTINCT CASE WHEN B.SXDC_SE_CD = 'M' THEN NVL(B.INDV_IDNTFC_NO, B.TRPR_INFO_NO) END) AS UNEART_REAL_NOPE_M , COUNT(DISTINCT CASE WHEN B.SXDC_SE_CD = 'F' THEN NVL(B.INDV_IDNTFC_NO, B.TRPR_INFO_NO) END) AS UNEART_REAL_NOPE_F , COUNT(DISTINCT CASE WHEN B.SXDC_SE_CD = 'X' THEN NVL(B.INDV_IDNTFC_NO, B.TRPR_INFO_NO) END) AS UNEART_REAL_NOPE_X FROM (SELECT A.CMMNS_CD_VALUE_NM AS RCPT_RQST_COURS_LCLAS_SE_NM , B.CMMNS_CD_VALUE_NM AS RCPT_RQST_COURS_MLSFC_SE_NM , C.CMMNS_CD_VALUE_NM AS RCPT_RQST_COURS_SCLAS_SE_NM , A.CMMNS_CD_VALUE AS RCPT_RQST_COURS_LCLAS_SE_CD , B.CMMNS_CD_VALUE AS RCPT_RQST_COURS_MLSFC_SE_CD , C.CMMNS_CD_VALUE AS RCPT_RQST_COURS_SCLAS_SE_CD FROM SAC100 A LEFT JOIN SAC100 B ON A.CMMNS_CD_VALUE = B.UP_CMMNS_CD_VALUE AND B.CMMNS_CD_ID = 'RCPT_RQST_COURS_MLSFC_SE_CD' LEFT JOIN SAC100 C ON B.CMMNS_CD_VALUE = C.UP_CMMNS_CD_VALUE AND C.CMMNS_CD_ID = 'RCPT_RQST_COURS_SCLAS_SE_CD' WHERE A.CMMNS_CD_ID = 'RCPT_RQST_COURS_LCLAS_SE_CD' ) A LEFT JOIN ( SELECT SUBSTR(A.RCPT_RQST_COURS_SE_CD,0,6) AS RCPT_RQST_COURS_SE_CD , C.INDV_IDNTFC_NO AS INDV_IDNTFC_NO , A.SXDC_SE_CD AS SXDC_SE_CD , A.TRPR_INFO_NO AS TRPR_INFO_NO FROM SEA200 A JOIN SAA000 B ON A.RCPT_INST_NO = B.INST_NO LEFT JOIN SCA300 C ON A.INDV_IDNTFC_NO = C.INDV_IDNTFC_NO WHERE A.UNT_TASKWK_SE_CD = #{UNT_TASKWK_SE_CD} AND A.DEL_YN = 'N'
-- 기간구분 AND A.FRST_REG_DT BETWEEN TO_DATE(#{SRT_DT}||'000000','YYYYMMDDHH24MISS') AND TO_DATE(#{END_DT}||'235959','YYYYMMDDHH24MISS')
-- 시도코드 AND B.CTPV_CD = #{CTPV_CD}
-- 시군구코드 AND B.SGG_CD = #{SGG_CD}
-- 기관번호 AND B.INST_NO = #{INST_NO}
#{instNo}
)B ON A.RCPT_RQST_COURS_SCLAS_SE_CD = B.RCPT_RQST_COURS_SE_CD GROUP BY ROLLUP ((A.RCPT_RQST_COURS_LCLAS_SE_CD , A.RCPT_RQST_COURS_MLSFC_SE_CD , A.RCPT_RQST_COURS_SCLAS_SE_CD , A.RCPT_RQST_COURS_LCLAS_SE_NM , A.RCPT_RQST_COURS_MLSFC_SE_NM , A.RCPT_RQST_COURS_SCLAS_SE_NM)) ) ORDER BY RCPT_RQST_COURS_LCLAS_SE_CD, RCPT_RQST_COURS_SCLAS_SE_CD

/*isry.itgcm.fdrmrptstats.mapper.FdrmRptStatsMapper 사례관리 통계- selectCaseMngStats*/ WITH X AS ( SELECT A.CASE_PRGRS_STTS_SE_CD --사례진행상태구분코드 , B.TRPR_INFO_NO --대상자정보번호 , A.CASE_MNG_NO --사례관리번호 , A.CASE_MNG_ODRNO --사례관리차수 , B.INDV_IDNTFC_NO --개인식별번호 , A.AFTFCT_MNG_YN --사후관리여부 , A.CASE_BGNG_YMD --사례시작일자 , A.CASE_TRMN_YMD --사례종결일자 , B.SXDC_SE_CD --성별구분 , C.AFTFCT_TRMN_YMD --사후종결일자 , A.AFTFCT_MNG_YN AS AFTFCT_YN --사후관리여부 , TO_DATE(#{SRT_DT} || '000000', 'YYYYMMDDHH24MISS') AS SRT_DT --검색조건시작 , TO_DATE(#{END_DT} || '235959', 'YYYYMMDDHH24MISS') AS END_DT --검색조건종료 FROM SEB100 A JOIN SEA200 B ON A.TRPR_INFO_NO = B.TRPR_INFO_NO AND B.DEL_YN = 'N' LEFT JOIN SEC320 C ON A.CASE_MNG_NO = C.CASE_MNG_NO AND A.CASE_MNG_ODRNO = C.CASE_MNG_ODRNO LEFT JOIN SEB150 Y /*사례담당자*/ ON Y.PCHPRS_YN = 'Y' AND Y.CASE_MNG_NO = A.CASE_MNG_NO AND Y.CASE_MNG_ODRNO = A.CASE_MNG_ODRNO JOIN SAA000 Z /*통합기관*/ ON Z.INST_NO = Y.PIC_INST_NO
JOIN ACA120 F /*위기스크리닝결과*/ ON F.CASE_MNG_NO = A.CASE_MNG_NO AND F.CASE_MNG_ODRNO = A.CASE_MNG_ODRNO AND F.GNRLZ_CRISIS_DGREE_SE_CD = '3'
JOIN SEB120 AD1 /*서비스사업대상자*/ ON AD1.CASE_MNG_NO = A.CASE_MNG_NO AND AD1.CASE_MNG_ODRNO = A.CASE_MNG_ODRNO AND AD1.SRVC_EXCN_BIZ_NO = 'BX2023051100001' -- 청소년동반자 서비스실행사업 AND AD1.DEL_YN = 'N'
JOIN SEB120 AD1 /*서비스사업대상자*/ ON AD1.CASE_MNG_NO = A.CASE_MNG_NO AND AD1.CASE_MNG_ODRNO = A.CASE_MNG_ODRNO AND AD1.SRVC_EXCN_BIZ_NO = 'BX2023051100003' -- 고위기청소년 맞춤형 프로그램(안전망팀사업) 서비스실행사업 AND AD1.DEL_YN = 'N'
WHERE 1=1 AND A.UNT_TASKWK_SE_CD = #{UNT_TASKWK_SE_CD} AND A.CASE_BGNG_YMD <= #{END_DT} AND NVL(A.CASE_TRMN_YMD, A.CASE_BGNG_YMD) >= #{SRT_DT}
/*시도코드*/ AND Z.CTPV_CD = #{CTPV_CD}
/*시군구코드*/ AND Z.SGG_CD = #{SGG_CD}
/*기관번호*/ AND Z.INST_NO = #{INST_NO}
AND #{SRVC_BIZ_CL} IN (SELECT AD3.BIZ_CL_SE_CD FROM SEB120 AD1 JOIN SDA420 AD2 ON AD2.SRVC_EXCN_BIZ_NO = AD1.SRVC_EXCN_BIZ_NO JOIN SDA400 AD3 ON AD3.SRVC_BIZ_NO = AD2.SRVC_BIZ_NO WHERE AD1.CASE_MNG_NO = A.CASE_MNG_NO AND AD1.CASE_MNG_ODRNO= A.CASE_MNG_ODRNO AND AD1.DEL_YN = 'N')
AND #{EXCN_SRVC_BIZ_CL} IN (SELECT AD2.BIZ_CL_SE_CD FROM SEB540 AD1 JOIN SDA430 AD2 ON AD2.EXCN_SRVC_BIZ_CL_NO = AD1.EXCN_SRVC_BIZ_CL_NO WHERE AD1.CASE_MNG_NO = A.CASE_MNG_NO AND AD1.CASE_MNG_ODRNO = A.CASE_MNG_ODRNO AND AD1.DEL_YN = 'N')
#{instNo}
) SELECT A.SCN_CD AS SXDC_SE_CD , A.SCN_NM AS SXDC_SE_CD_NM , NVL(B.CASE_MNG_NOPE_CASE, 0) + NVL(B.CASE_MNG_NOPE_AFTFCT, 0) + NVL(B.CASE_MNG_NOPE_TRMN, 0) AS CASE_MNG_NOPE_T , NVL(B.CASE_MNG_NOPE_CASE, 0) AS CASE_MNG_NOPE_CASE , NVL(B.CASE_MNG_NOPE_AFTFCT, 0) AS CASE_MNG_NOPE_AFTFCT , NVL(B.CASE_MNG_NOPE_TRMN, 0) AS CASE_MNG_NOPE_TRMN , NVL(B.CASE_MNG_REAL_NOPE_T, 0) AS CASE_MNG_REAL_NOPE_T , NVL(B.CASE_MNG_REAL_NOPE_CASE, 0) AS CASE_MNG_REAL_NOPE_CASE , NVL(B.CASE_MNG_REAL_NOPE_AFTCT, 0) AS CASE_MNG_REAL_NOPE_AFTCT , NVL(B.CASE_MNG_REAL_NOPE_TRMN, 0) AS CASE_MNG_REAL_NOPE_TRMN FROM ( SELECT '00' AS SCN_CD , '합계' AS SCN_NM FROM DUAL UNION ALL SELECT CMMNS_CD_VALUE AS SCN_CD , CMMNS_CD_VALUE_NM AS SCN_NM FROM SAC100 WHERE CMMNS_CD_ID = 'SXDC_SE_CD' ORDER BY CASE WHEN SCN_CD = '00' THEN 1 WHEN SCN_CD = 'M' THEN 2 END ) A LEFT JOIN ( /*합계*/ SELECT '00' AS SXDC_SE_CD /*전체*/ , COUNT(CASE WHEN CASE_BGNG_YMD <= END_DT AND (CASE_TRMN_YMD > END_DT OR CASE_TRMN_YMD IS NULL) THEN TRPR_INFO_NO END) AS CASE_MNG_NOPE_CASE , COUNT(CASE WHEN CASE_TRMN_YMD <= END_DT AND (AFTFCT_TRMN_YMD > END_DT OR AFTFCT_TRMN_YMD IS NULL) THEN TRPR_INFO_NO END) AS CASE_MNG_NOPE_AFTFCT , COUNT(CASE WHEN (CASE_TRMN_YMD BETWEEN SRT_DT AND END_DT AND AFTFCT_YN = 'N') OR (AFTFCT_TRMN_YMD BETWEEN SRT_DT AND END_DT AND AFTFCT_YN = 'Y') THEN TRPR_INFO_NO END) AS CASE_MNG_NOPE_TRMN /*실*/ , COUNT(DISTINCT NVL(INDV_IDNTFC_NO, TRPR_INFO_NO)) AS CASE_MNG_REAL_NOPE_T , COUNT(DISTINCT CASE WHEN CASE_BGNG_YMD <= END_DT AND (CASE_TRMN_YMD > END_DT OR CASE_TRMN_YMD IS NULL) THEN NVL(INDV_IDNTFC_NO, TRPR_INFO_NO) END) AS CASE_MNG_REAL_NOPE_CASE , COUNT(DISTINCT CASE WHEN CASE_TRMN_YMD <= END_DT AND (AFTFCT_TRMN_YMD > END_DT OR AFTFCT_TRMN_YMD IS NULL) THEN NVL(INDV_IDNTFC_NO, TRPR_INFO_NO) END) AS CASE_MNG_REAL_NOPE_AFTCT , COUNT(DISTINCT CASE WHEN (CASE_TRMN_YMD BETWEEN SRT_DT AND END_DT AND AFTFCT_YN = 'N') OR (AFTFCT_TRMN_YMD BETWEEN SRT_DT AND END_DT AND AFTFCT_YN = 'Y') THEN NVL(INDV_IDNTFC_NO, TRPR_INFO_NO) END) AS CASE_MNG_REAL_NOPE_TRMN FROM X UNION ALL /*통계*/ SELECT SXDC_SE_CD /*전체*/ , COUNT(CASE WHEN CASE_BGNG_YMD <= END_DT AND (CASE_TRMN_YMD > END_DT OR CASE_TRMN_YMD IS NULL) THEN TRPR_INFO_NO END) AS CASE_MNG_NOPE_CASE , COUNT(CASE WHEN CASE_TRMN_YMD <= END_DT AND (AFTFCT_TRMN_YMD > END_DT OR AFTFCT_TRMN_YMD IS NULL) THEN TRPR_INFO_NO END) AS CASE_MNG_NOPE_AFTFCT , COUNT(CASE WHEN (CASE_TRMN_YMD BETWEEN SRT_DT AND END_DT AND AFTFCT_YN = 'N') OR (AFTFCT_TRMN_YMD BETWEEN SRT_DT AND END_DT AND AFTFCT_YN = 'Y') THEN TRPR_INFO_NO END) AS CASE_MNG_NOPE_TRMN /*실*/ , COUNT(DISTINCT NVL(INDV_IDNTFC_NO, TRPR_INFO_NO)) AS CASE_MNG_REAL_NOPE_T , COUNT(DISTINCT CASE WHEN CASE_BGNG_YMD <= END_DT AND (CASE_TRMN_YMD > END_DT OR CASE_TRMN_YMD IS NULL) THEN NVL(INDV_IDNTFC_NO, TRPR_INFO_NO) END) AS CASE_MNG_REAL_NOPE_CASE , COUNT(DISTINCT CASE WHEN CASE_TRMN_YMD <= END_DT AND (AFTFCT_TRMN_YMD > END_DT OR AFTFCT_TRMN_YMD IS NULL) THEN NVL(INDV_IDNTFC_NO, TRPR_INFO_NO) END) AS CASE_MNG_REAL_NOPE_AFTCT , COUNT(DISTINCT CASE WHEN (CASE_TRMN_YMD BETWEEN SRT_DT AND END_DT AND AFTFCT_YN = 'N') OR (AFTFCT_TRMN_YMD BETWEEN SRT_DT AND END_DT AND AFTFCT_YN = 'Y') THEN NVL(INDV_IDNTFC_NO, TRPR_INFO_NO) END) AS CASE_MNG_REAL_NOPE_TRMN FROM X GROUP BY SXDC_SE_CD ) B ON A.SCN_CD = B.SXDC_SE_CD

/*isry.itgcm.fdrmrptstats.mapper.FdrmRptStatsMapper - selectSprtSrvcStatsCaseReg[지원서비스(기본)] : Lee SangHoon*/
SELECT NVL(T1.SPRT_SE_CD, '00') AS SPRT_SE_CD --지원구분코드 , NVL(T1.SPRT_SE,'합계') AS SPRT_SE --지원구분 , T2.SRVC_RESRCE_LCLAS_SE_CD --서비스자원대분류구분코드 , NVL(SUM(T.NOPE),0) AS NOPE --인원수 FROM (SELECT '01' AS SPRT_SE_CD --지원구분코드 , '사례등록' AS SPRT_SE --지원구분 FROM DUAL UNION ALL SELECT '02' AS SPRT_SE_CD --지원구분코드 , '사례미등록' AS SPRT_SE --지원구분 FROM DUAL ) T1 CROSS JOIN (SELECT A.CMMNS_CD_VALUE AS SRVC_RESRCE_LCLAS_SE_CD --서비스자원대분류구분코드 FROM SAC100 A /*공통코드 값*/ LEFT JOIN SAC110 B /*공통코드값 사용시스템*/ ON B.CMMNS_CD_ID = A.CMMNS_CD_ID AND B.CMMNS_CD_VALUE = A.CMMNS_CD_VALUE WHERE A.CMMNS_CD_ID = 'SRVC_RESRCE_LCLAS_SE_CD' AND (B.UNT_TASKWK_SE_CD = #{UNT_TASKWK_SE_CD} OR B.UNT_TASKWK_SE_CD IS NULL) ) T2 LEFT JOIN (SELECT '01' AS SPRT_SE_CD --지원구분코드 , C.SRVC_RESRCE_LCLAS_SE_CD --서비스자원대분룬류구분코드 , COUNT(A.CASE_MNG_NO) AS NOPE --인원수 FROM SEB100 A /*자원기본*/ JOIN SEB510 B /*서비스제공대상자*/ ON B.CASE_MNG_NO = A.CASE_MNG_NO AND B.CASE_MNG_ODRNO = A.CASE_MNG_ODRNO AND B.DEL_YN = 'N' JOIN SDA100 C /*자원기본*/ ON C.RESRCE_NO = B.RESRCE_NO JOIN SEB500 D /*서비스제공*/ ON D.SRVC_PVSN_NO = B.SRVC_PVSN_NO AND D.RESRCE_NO = B.RESRCE_NO AND D.DEL_YN = 'N' JOIN SAA000 E /*통합기관*/ ON E.INST_NO = D.TKCG_INST_NO AND E.DEL_YN = 'N'
JOIN SEB120 AD1 /*서비스사업대상자*/ ON AD1.CASE_MNG_NO = A.CASE_MNG_NO AND AD1.CASE_MNG_ODRNO = A.CASE_MNG_ODRNO AND AD1.SRVC_EXCN_BIZ_NO = 'BX2023051100001' -- 청소년동반자 서비스실행사업 AND AD1.DEL_YN = 'N'
JOIN SEB120 AD1 /*서비스사업대상자*/ ON AD1.CASE_MNG_NO = A.CASE_MNG_NO AND AD1.CASE_MNG_ODRNO = A.CASE_MNG_ODRNO AND AD1.SRVC_EXCN_BIZ_NO = 'BX2023051100003' -- 고위기청소년 맞춤형 프로그램(안전망팀사업) 서비스실행사업 AND AD1.DEL_YN = 'N'
LEFT JOIN AKA410 AD1 /*서비스집단실행*/ ON AD1.SRVC_PVSN_NO = D.SRVC_PVSN_NO AND AD1.RESRCE_NO = D.RESRCE_NO AND AD1.CASE_MNG_NO = A.CASE_MNG_NO AND AD1.CASE_MNG_ODRNO = A.CASE_MNG_ODRNO AND AD1.USE_YN = 'Y' AND AD1.USE_YMD BETWEEN #{SRT_DT} AND #{END_DT}
LEFT JOIN ( SELECT B.* ,ROW_NUMBER() OVER(PARTITION BY B.CASE_MNG_NO, B.CASE_MNG_ODRNO ORDER BY B.CASE_TRMN_NO DESC) AS RN FROM SEC100 A LEFT JOIN SEC100 B ON B.CASE_MNG_NO = A.CASE_MNG_NO AND B.CASE_MNG_ODRNO = A.CASE_MNG_ODRNO AND B.TRMN_SRNG_RESULT_SE_CD = '01' WHERE A.TRMN_SRNG_RESULT_SE_CD = '02' )T11 /* 사례종결 */ ON T11.CASE_MNG_NO = A.CASE_MNG_NO AND T11.CASE_MNG_ODRNO = A.CASE_MNG_ODRNO AND T11.RN=1
WHERE D.SRVC_PVSN_BGNG_YMD <= #{END_DT} AND D.SRVC_PVSN_END_YMD >= #{SRT_DT} AND A.UNT_TASKWK_SE_CD = #{UNT_TASKWK_SE_CD} AND (T11.TRMN_SE_CD NOT IN ('12') OR T11.TRMN_SE_CD IS NULL)
AND E.INST_NO = #{INST_NO}
AND E.CTPV_CD = #{CTPV_CD}
AND E.SGG_CD = #{SGG_CD}
AND #{SRVC_BIZ_CL} IN (SELECT AD3.BIZ_CL_SE_CD FROM SEB120 AD1 JOIN SDA420 AD2 ON AD2.SRVC_EXCN_BIZ_NO = AD1.SRVC_EXCN_BIZ_NO JOIN SDA400 AD3 ON AD3.SRVC_BIZ_NO = AD2.SRVC_BIZ_NO WHERE AD1.CASE_MNG_NO = A.CASE_MNG_NO AND AD1.CASE_MNG_ODRNO = A.CASE_MNG_ODRNO AND AD1.DEL_YN = 'N')
AND #{EXCN_SRVC_BIZ_CL} IN (SELECT AD2.BIZ_CL_SE_CD FROM SEB540 AD1 JOIN SDA430 AD2 ON AD2.EXCN_SRVC_BIZ_CL_NO = AD1.EXCN_SRVC_BIZ_CL_NO WHERE AD1.SRVC_PVSN_NO = B.SRVC_PVSN_NO AND AD1.CASE_MNG_NO = B.CASE_MNG_NO AND AD1.CASE_MNG_ODRNO = B.CASE_MNG_ODRNO AND AD1.RESRCE_NO = B.RESRCE_NO AND AD1.DEL_YN = 'N')
#{instNo}
GROUP BY C.SRVC_RESRCE_LCLAS_SE_CD
UNION ALL SELECT '01' AS SPRT_SE_CD --지원구분코드 , '05' AS SRVC_RESRCE_LCLAS_SE_CD --서비스자원대분류구분코드 , CASE WHEN SYSDATE < GREATEST(TO_DATE(#{SRT_DT},'YYYYMMDD'),TO_DATE(A.CASE_BGNG_YMD,'YYYYMMDD')) THEN 0 ELSE TRUNC( LEAST ( TO_DATE(#{END_DT},'YYYYMMDD') , NVL(TO_DATE(A.CASE_TRMN_YMD,'YYYYMMDD'),SYSDATE) , SYSDATE) - GREATEST ( TO_DATE(#{SRT_DT},'YYYYMMDD') , TO_DATE(A.CASE_BGNG_YMD,'YYYYMMDD')) ) + 1 END * 5 + NVL(C.MEAL_SPRT_NOCS,0) + NVL(C.CLTHA_SPRT_NOCS,0) + NVL(C.SNITAT_SPRT_NOCS,0) AS NOPE --인원수 FROM SEB100 A /*자원기본*/ LEFT JOIN AEB120 B /*서비스사업대상자*/ ON B.CASE_MNG_NO = A.CASE_MNG_NO AND B.CASE_MNG_ODRNO = A.CASE_MNG_ODRNO LEFT JOIN AEA160 C /*기본지원실적*/ ON C.CASE_MNG_NO = A.CASE_MNG_NO AND C.CASE_MNG_ODRNO = A.CASE_MNG_ODRNO AND A.CASE_TRMN_YMD BETWEEN #{SRT_DT} AND #{END_DT} JOIN SEB150 D /*사례담당자*/ ON D.CASE_MNG_NO = A.CASE_MNG_NO AND D.CASE_MNG_ODRNO = A.CASE_MNG_ODRNO AND D.PCHPRS_YN = 'Y' JOIN SAA000 E /*통합기관*/ ON E.INST_NO = D.PIC_INST_NO AND E.DEL_YN = 'N' WHERE A.CASE_BGNG_YMD <= #{END_DT} AND (A.CASE_TRMN_YMD >= #{SRT_DT} OR A.CASE_TRMN_YMD IS NULL) AND A.UNT_TASKWK_SE_CD = #{UNT_TASKWK_SE_CD} AND NVL(B.SLFRL_SPRT_TRPR_SE_CD,'1') = '1'
AND E.INST_NO = #{INST_NO}
AND E.CTPV_CD = #{CTPV_CD}
AND E.SGG_CD = #{SGG_CD}
AND #{SRVC_BIZ_CL} IN (SELECT AD3.BIZ_CL_SE_CD FROM SEB120 AD1 JOIN SDA420 AD2 ON AD2.SRVC_EXCN_BIZ_NO = AD1.SRVC_EXCN_BIZ_NO JOIN SDA400 AD3 ON AD3.SRVC_BIZ_NO = AD2.SRVC_BIZ_NO WHERE AD1.CASE_MNG_NO = A.CASE_MNG_NO AND AD1.CASE_MNG_ODRNO = A.CASE_MNG_ODRNO AND AD1.DEL_YN = 'N')
#{instNo}
UNION ALL SELECT '02' AS SPRT_SE_CD --지원구분코드 , A.SRVC_RESRCE_LCLAS_SE_CD --서비스자원대분류구분코드 , SUM(A.ELESCH_STDENT_MALE_NOPE + A.ELESCH_STDENT_FEMALE_NOPE + A.MSKUL_STDENT_MALE_NOPE + A.MSKUL_STDENT_FEMALE_NOPE + A.HGSCHL_STDENT_MALE_NOPE + A.HGSCHL_STDENT_FEMALE_NOPE + A.UNIVA_STDENT_MALE_NOPE + A.UNIVA_STDENT_FEMALE_NOPE + A.ELESCH_OSCHL_MALE_NOPE + A.ELESCH_OSCHL_FEMALE_NOPE + A.MSKUL_OSCHL_MALE_NOPE + A.MSKUL_OSCHL_FEMALE_NOPE + A.HGSCHL_OSCHL_MALE_NOPE + A.HGSCHL_OSCHL_FEMALE_NOPE + A.UNIVA_OSCHL_MALE_NOPE + A.UNIVA_OSCHL_FEMALE_NOPE + A.AGRDHS_IOCPTN_MALE_NOPE + A.AGRDHS_EMPYMN_MALE_NOPE + A.AGRDHS_IOCPTN_FEMALE_NOPE + A.AGRDHS_EMPYMN_FEMALE_NOPE + A.PARNTS_PRTCR_MALE_NOPE + A.LEADER_MALE_NOPE + A.PEPL_MALE_NOPE + A.PARNTS_PRTCR_FEMALE_NOPE + A.LEADER_FEMALE_NOPE + A.PEPL_FEMALE_NOPE) AS NOPE --인원수 FROM SED100 A /*미등록사례*/ JOIN SAA000 B /*통합기관*/ ON B.INST_NO = A.PIC_INST_NO AND B.DEL_YN = 'N'
JOIN SED110 AD1 /*미등록사례별서비스사업*/ ON AD1.UNREGI_CASE_NO = A.UNREGI_CASE_NO AND AD1.SRVC_EXCN_BIZ_NO = 'BX2023051100001' -- 청소년동반자 서비스실행사업 AND AD1.DEL_YN = 'N'
JOIN SED110 AD1 /*미등록사례별서비스사업*/ ON AD1.UNREGI_CASE_NO = A.UNREGI_CASE_NO AND AD1.SRVC_EXCN_BIZ_NO = 'BX2023051100003' -- 고위기청소년 맞춤형 프로그램(안전망팀사업) 서비스실행사업 AND AD1.DEL_YN = 'N'
WHERE A.SPRT_BGNG_YMD <= #{END_DT} AND A.SPRT_END_YMD >= #{SRT_DT} AND A.UNT_TASKWK_SE_CD = #{UNT_TASKWK_SE_CD}
AND B.INST_NO = #{INST_NO}
AND B.CTPV_CD = #{CTPV_CD}
AND B.SGG_CD = #{SGG_CD}
AND #{SRVC_BIZ_CL} IN (SELECT AD3.BIZ_CL_SE_CD FROM SED110 AD1 JOIN SDA420 AD2 ON AD2.SRVC_EXCN_BIZ_NO = AD1.SRVC_EXCN_BIZ_NO JOIN SDA400 AD3 ON AD3.SRVC_BIZ_NO = AD2.SRVC_BIZ_NO WHERE AD1.UNREGI_CASE_NO = A.UNREGI_CASE_NO AND AD1.DEL_YN = 'N')
AND #{EXCN_SRVC_BIZ_CL} IN (SELECT AD2.BIZ_CL_SE_CD FROM SED111 AD1 JOIN SDA430 AD2 ON AD2.EXCN_SRVC_BIZ_CL_NO = AD1.EXCN_SRVC_BIZ_CL_NO WHERE AD1.UNREGI_CASE_NO = A.UNREGI_CASE_NO AND AD1.DEL_YN = 'N')
#{instNo}
GROUP BY A.SRVC_RESRCE_LCLAS_SE_CD ) T ON T.SPRT_SE_CD = T1.SPRT_SE_CD AND T.SRVC_RESRCE_LCLAS_SE_CD = T2.SRVC_RESRCE_LCLAS_SE_CD GROUP BY ROLLUP(T1.SPRT_SE_CD, T1.SPRT_SE), T2.SRVC_RESRCE_LCLAS_SE_CD HAVING GROUPING(T1.SPRT_SE_CD) = GROUPING(T1.SPRT_SE) ORDER BY SPRT_SE_CD, SRVC_RESRCE_LCLAS_SE_CD

/*isry.itgcm.fdrmrptstats.mapper.FdrmRptStatsMapper - selectSprtSrvcStatsHlisk[지원서비스(고위기청소년지원)] : Lee SangHoon*/
SELECT T1.SPRT_SE_CD --지원구분코드 , T1.SPRT_SE --지원구분 , T2.SRVC_RESRCE_LCLAS_SE_CD --서비스자원대분류구분코드 , NVL(T.NOPE,0) AS NOPE --인원수 FROM (SELECT '01' AS SPRT_SE_CD --지원구분코드 , '사례등록' AS SPRT_SE --지원구분 FROM DUAL ) T1 CROSS JOIN (SELECT A.CMMNS_CD_VALUE AS SRVC_RESRCE_LCLAS_SE_CD --서비스자원대분류구분코드 FROM SAC100 A /*공통코드 값*/ JOIN SAC110 B /*공통코드값 사용시스템*/ ON B.CMMNS_CD_ID = A.CMMNS_CD_ID AND B.CMMNS_CD_VALUE = A.CMMNS_CD_VALUE AND UNT_TASKWK_SE_CD = #{UNT_TASKWK_SE_CD} WHERE A.CMMNS_CD_ID = 'SRVC_RESRCE_LCLAS_SE_CD' ) T2 LEFT JOIN (SELECT '01' AS SPRT_SE_CD --지원구분코드 , C.SRVC_RESRCE_LCLAS_SE_CD --서비스자원대분류구분코드 , COUNT(A.CASE_MNG_NO) AS NOPE --인원수 FROM SEB100 A /*사례기본*/ JOIN SEB510 B /*서비스제공대상자*/ ON B.CASE_MNG_NO = A.CASE_MNG_NO AND B.CASE_MNG_ODRNO = A.CASE_MNG_ODRNO AND B.DEL_YN = 'N' JOIN SDA100 C /*자원기본*/ ON C.RESRCE_NO = B.RESRCE_NO JOIN SEB500 D /*서비스제공*/ ON D.SRVC_PVSN_NO = B.SRVC_PVSN_NO AND D.RESRCE_NO = B.RESRCE_NO AND D.DEL_YN = 'N' JOIN SAA000 E /*통합기관*/ ON E.INST_NO = D.TKCG_INST_NO AND E.DEL_YN = 'N' JOIN ACA120 F /*위기스크리닝결과*/ ON F.CASE_MNG_NO = A.CASE_MNG_NO AND F.CASE_MNG_ODRNO = A.CASE_MNG_ODRNO AND F.GNRLZ_CRISIS_DGREE_SE_CD = '3' WHERE D.SRVC_PVSN_BGNG_YMD <= #{END_DT} AND D.SRVC_PVSN_END_YMD >= #{SRT_DT} AND A.UNT_TASKWK_SE_CD = #{UNT_TASKWK_SE_CD}
AND E.INST_NO = #{INST_NO}
AND E.CTPV_CD = #{CTPV_CD}
AND E.SGG_CD = #{SGG_CD}
AND #{SRVC_BIZ_CL} IN (SELECT AD3.BIZ_CL_SE_CD FROM SEB120 AD1 JOIN SDA420 AD2 ON AD2.SRVC_EXCN_BIZ_NO = AD1.SRVC_EXCN_BIZ_NO JOIN SDA400 AD3 ON AD3.SRVC_BIZ_NO = AD2.SRVC_BIZ_NO WHERE AD1.CASE_MNG_NO = A.CASE_MNG_NO AND AD1.CASE_MNG_ODRNO = A.CASE_MNG_ODRNO AND AD1.DEL_YN = 'N')
AND #{EXCN_SRVC_BIZ_CL} IN (SELECT AD2.BIZ_CL_SE_CD FROM SEB540 AD1 JOIN SDA430 AD2 ON AD2.EXCN_SRVC_BIZ_CL_NO = AD1.EXCN_SRVC_BIZ_CL_NO WHERE AD1.SRVC_PVSN_NO = B.SRVC_PVSN_NO AND AD1.CASE_MNG_NO = B.CASE_MNG_NO AND AD1.CASE_MNG_ODRNO = B.CASE_MNG_ODRNO AND AD1.RESRCE_NO = B.RESRCE_NO AND AD1.DEL_YN = 'N')
#{instNo}
GROUP BY C.SRVC_RESRCE_LCLAS_SE_CD ) T ON T.SPRT_SE_CD = T1.SPRT_SE_CD AND T.SRVC_RESRCE_LCLAS_SE_CD = T2.SRVC_RESRCE_LCLAS_SE_CD ORDER BY SPRT_SE_CD, SRVC_RESRCE_LCLAS_SE_CD

/*isry.itgcm.fdrmrptstats.mapper.FdrmRptStatsMapper - selectSprtSrvcStatsSheltrType[지원서비스(쉼터유형별)] : Lee SangHoon*/
SELECT NVL(T1.FCLTY_TYPE_SE_CD,'00') AS FCLTY_TYPE_SE_CD --시설유형구분코드 , NVL(T1.FCLTY_TYPE_SE_CD_NM,'합계') AS FCLTY_TYPE_SE_CD_NM --시설유형구분코드명 , NVL(T2.SXDC_SE_CD_NM,'합계') AS SXDC_SE_CD_NM --성별구분코드명 , NVL(T3.SRVC_RESRCE_LCLAS_SE_CD,'00') AS SRVC_RESRCE_LCLAS_SE_CD --서비스자원대분류구분코드 , NVL(SUM(T.NOPE),0) AS NOPE --인원수 , NVL(T2.SXDC_SRTNG_SQNCE,0) AS SXDC_SRTNG_SQNCE --성별코드순번 FROM (SELECT A.CMMNS_CD_VALUE AS FCLTY_TYPE_SE_CD , A.CMMNS_CD_VALUE_NM AS FCLTY_TYPE_SE_CD_NM FROM SAC100 A /*공통코드 값*/ LEFT JOIN SAC110 B /*공통코드값 사용시스템*/ ON B.CMMNS_CD_ID = A.CMMNS_CD_ID AND B.CMMNS_CD_VALUE = A.CMMNS_CD_VALUE WHERE A.CMMNS_CD_ID = 'FCLTY_TYPE_SE_CD' AND (B.UNT_TASKWK_SE_CD = #{UNT_TASKWK_SE_CD} OR B.UNT_TASKWK_SE_CD IS NULL) ) T1 CROSS JOIN (SELECT A.CMMNS_CD_VALUE AS SXDC_SE_CD --성별구분코드 , A.CMMNS_CD_VALUE_NM AS SXDC_SE_CD_NM --성별구분코드명 , A.SRTNG_SQNCE AS SXDC_SRTNG_SQNCE --성별코드순번 FROM SAC100 A /*공통코드 값*/ LEFT JOIN SAC110 B /*공통코드값 사용시스템*/ ON B.CMMNS_CD_ID = A.CMMNS_CD_ID AND B.CMMNS_CD_VALUE = A.CMMNS_CD_VALUE WHERE A.CMMNS_CD_ID = 'SXDC_SE_CD' AND (B.UNT_TASKWK_SE_CD = #{UNT_TASKWK_SE_CD} OR B.UNT_TASKWK_SE_CD IS NULL) ) T2 CROSS JOIN (SELECT A.CMMNS_CD_VALUE AS SRVC_RESRCE_LCLAS_SE_CD --서비스자원대분류구분코드 FROM SAC100 A /*공통코드 값*/ LEFT JOIN SAC110 B /*공통코드값 사용시스템*/ ON B.CMMNS_CD_ID = A.CMMNS_CD_ID AND B.CMMNS_CD_VALUE = A.CMMNS_CD_VALUE WHERE A.CMMNS_CD_ID = 'SRVC_RESRCE_LCLAS_SE_CD' AND (B.UNT_TASKWK_SE_CD = #{UNT_TASKWK_SE_CD} OR B.UNT_TASKWK_SE_CD IS NULL) ) T3 LEFT JOIN (SELECT E2.FCLTY_TYPE_SE_CD --시설유형구분코드 , F.SXDC_SE_CD --성별구분코드 , C.SRVC_RESRCE_LCLAS_SE_CD --서비스자원대분류구분코드 , COUNT(A.CASE_MNG_NO) AS NOPE --인원수 FROM SEB100 A /*사례기본*/ JOIN SEB510 B /*서비스제공대상자*/ ON B.CASE_MNG_NO = A.CASE_MNG_NO AND B.CASE_MNG_ODRNO = A.CASE_MNG_ODRNO AND B.DEL_YN = 'N' JOIN SDA100 C /*자원기본*/ ON C.RESRCE_NO = B.RESRCE_NO JOIN SEB500 D /*서비스제공*/ ON D.SRVC_PVSN_NO = B.SRVC_PVSN_NO AND D.RESRCE_NO = B.RESRCE_NO AND D.DEL_YN = 'N' JOIN SAA000 E /*통합기관*/ ON E.INST_NO = D.TKCG_INST_NO AND E.DEL_YN = 'N' JOIN AKA500 E2 /*센터현황*/ ON E2.INST_NO = E.INST_NO JOIN SEA200 F /*대상자정보*/ ON F.TRPR_INFO_NO = A.TRPR_INFO_NO AND F.DEL_YN = 'N' WHERE D.SRVC_PVSN_BGNG_YMD <= #{END_DT} AND D.SRVC_PVSN_END_YMD >= #{SRT_DT} AND A.UNT_TASKWK_SE_CD = #{UNT_TASKWK_SE_CD}
AND E.INST_NO = #{INST_NO}
AND E.CTPV_CD = #{CTPV_CD}
AND E.SGG_CD = #{SGG_CD}
AND #{SRVC_BIZ_CL} IN (SELECT AD3.BIZ_CL_SE_CD FROM SEB120 AD1 JOIN SDA420 AD2 ON AD2.SRVC_EXCN_BIZ_NO = AD1.SRVC_EXCN_BIZ_NO JOIN SDA400 AD3 ON AD3.SRVC_BIZ_NO = AD2.SRVC_BIZ_NO WHERE AD1.CASE_MNG_NO = A.CASE_MNG_NO AND AD1.CASE_MNG_ODRNO = A.CASE_MNG_ODRNO AND AD1.DEL_YN = 'N')
AND #{EXCN_SRVC_BIZ_CL} IN (SELECT AD2.BIZ_CL_SE_CD FROM SEB540 AD1 JOIN SDA430 AD2 ON AD2.EXCN_SRVC_BIZ_CL_NO = AD1.EXCN_SRVC_BIZ_CL_NO WHERE AD1.SRVC_PVSN_NO = B.SRVC_PVSN_NO AND AD1.CASE_MNG_NO = B.CASE_MNG_NO AND AD1.CASE_MNG_ODRNO = B.CASE_MNG_ODRNO AND AD1.RESRCE_NO = B.RESRCE_NO AND AD1.DEL_YN = 'N')
#{instNo}
GROUP BY E2.FCLTY_TYPE_SE_CD, F.SXDC_SE_CD, C.SRVC_RESRCE_LCLAS_SE_CD UNION ALL SELECT E2.FCLTY_TYPE_SE_CD --시설유형구분코드 , D.SXDC_SE_CD --성별구분코드 , '05' AS SRVC_RESRCE_LCLAS_SE_CD --서비스자원대분류구분코드 , CASE WHEN SYSDATE < GREATEST(TO_DATE(#{SRT_DT},'YYYYMMDD'),TO_DATE(A.CASE_BGNG_YMD,'YYYYMMDD')) THEN 0 ELSE TRUNC( LEAST ( TO_DATE(#{END_DT},'YYYYMMDD') , NVL(TO_DATE(A.CASE_TRMN_YMD,'YYYYMMDD'),SYSDATE) , SYSDATE) - GREATEST ( TO_DATE(#{SRT_DT},'YYYYMMDD') , TO_DATE(A.CASE_BGNG_YMD,'YYYYMMDD')) ) + 1 END * 5 + NVL(C.MEAL_SPRT_NOCS,0) + NVL(C.CLTHA_SPRT_NOCS,0) + NVL(C.SNITAT_SPRT_NOCS,0) AS NOPE --인원수 FROM SEB100 A /*사례기본*/ LEFT JOIN AEA100 B /*쉼터사례기본*/ ON B.CASE_MNG_NO = A.CASE_MNG_NO AND B.CASE_MNG_ODRNO = A.CASE_MNG_ODRNO LEFT JOIN AEA160 C /*기본지원실적*/ ON C.CASE_MNG_NO = A.CASE_MNG_NO AND C.CASE_MNG_ODRNO = A.CASE_MNG_ODRNO AND A.CASE_TRMN_YMD BETWEEN #{SRT_DT} AND #{END_DT} JOIN SEA200 D /*대상자정보*/ ON D.TRPR_INFO_NO = A.TRPR_INFO_NO AND D.DEL_YN = 'N' JOIN SEB150 E /*사례담당자*/ ON E.CASE_MNG_NO = A.CASE_MNG_NO AND E.CASE_MNG_ODRNO = A.CASE_MNG_ODRNO AND E.PCHPRS_YN = 'Y' JOIN SAA000 E1 /*통합기관*/ ON E1.INST_NO = E.PIC_INST_NO AND E1.DEL_YN = 'N' JOIN AKA500 E2 /*센터현황*/ ON E2.INST_NO = E1.INST_NO WHERE A.CASE_BGNG_YMD <= #{END_DT} AND (A.CASE_TRMN_YMD >= #{SRT_DT} OR A.CASE_TRMN_YMD IS NULL) AND A.UNT_TASKWK_SE_CD = #{UNT_TASKWK_SE_CD} AND B.SHELTR_TRPR_SE_CD = '1'
AND E1.INST_NO = #{INST_NO}
AND E1.CTPV_CD = #{CTPV_CD}
AND E1.SGG_CD = #{SGG_CD}
AND #{SRVC_BIZ_CL} IN (SELECT AD3.BIZ_CL_SE_CD FROM SEB120 AD1 JOIN SDA420 AD2 ON AD2.SRVC_EXCN_BIZ_NO = AD1.SRVC_EXCN_BIZ_NO JOIN SDA400 AD3 ON AD3.SRVC_BIZ_NO = AD2.SRVC_BIZ_NO WHERE AD1.CASE_MNG_NO = A.CASE_MNG_NO AND AD1.CASE_MNG_ODRNO = A.CASE_MNG_ODRNO AND AD1.DEL_YN = 'N')
#{instNo}
) T ON T.FCLTY_TYPE_SE_CD = T1.FCLTY_TYPE_SE_CD AND T.SXDC_SE_CD = T2.SXDC_SE_CD AND T.SRVC_RESRCE_LCLAS_SE_CD = T3.SRVC_RESRCE_LCLAS_SE_CD GROUP BY CUBE(T1.FCLTY_TYPE_SE_CD, T1.FCLTY_TYPE_SE_CD_NM, T2.SXDC_SE_CD_NM, T2.SXDC_SRTNG_SQNCE, T3.SRVC_RESRCE_LCLAS_SE_CD) HAVING GROUPING(T1.FCLTY_TYPE_SE_CD) = GROUPING(T1.FCLTY_TYPE_SE_CD_NM) AND GROUPING(T2.SXDC_SE_CD_NM) = GROUPING(T2.SXDC_SRTNG_SQNCE) ORDER BY CASE WHEN FCLTY_TYPE_SE_CD = '00' THEN 0 WHEN FCLTY_TYPE_SE_CD = '01' THEN 2 WHEN FCLTY_TYPE_SE_CD = '02' THEN 1 WHEN FCLTY_TYPE_SE_CD = '03' THEN 3 WHEN FCLTY_TYPE_SE_CD = '04' THEN 4 END, SXDC_SRTNG_SQNCE, SRVC_RESRCE_LCLAS_SE_CD

/*isry.itgcm.fdrmrptstats.mapper.FdrmRptStatsMapper - selectSprtSrvcStatsCaseUnregi[지원서비스(미등록사례별도)] : Lee SangHoon*/
SELECT T1.FCLTY_TYPE_SE_CD AS FCLTY_TYPE_SE_CD --시설유형구분코드 , T1.FCLTY_TYPE_SE_CD_NM AS FCLTY_TYPE_SE_CD_NM --시설유형구분코드명 , NVL(T2.SXDC_SE_CD_NM,'합계') AS SXDC_SE_CD_NM --성별구분코드명 , NVL(T3.SRVC_RESRCE_LCLAS_SE_CD,'00') AS SRVC_RESRCE_LCLAS_SE_CD --서비스자원대분류구분코드 , NVL(SUM(T.NOPE),0) AS NOPE --인원수 , NVL(T2.SXDC_SRTNG_SQNCE,0) AS SXDC_SRTNG_SQNCE --성별코드순번 FROM (SELECT '02' AS FCLTY_TYPE_SE_CD --시설유형구분코드 , '사례미등록' AS FCLTY_TYPE_SE_CD_NM --시설유형구분코드명 FROM DUAL ) T1 CROSS JOIN (SELECT A.CMMNS_CD_VALUE AS SXDC_SE_CD --성별구분코드 , A.CMMNS_CD_VALUE_NM AS SXDC_SE_CD_NM --성별구분코드명 , A.SRTNG_SQNCE AS SXDC_SRTNG_SQNCE --성별코드순번 FROM SAC100 A /*공통코드 값*/ LEFT JOIN SAC110 B /*공통코드값 사용시스템*/ ON B.CMMNS_CD_ID = A.CMMNS_CD_ID AND B.CMMNS_CD_VALUE = A.CMMNS_CD_VALUE WHERE A.CMMNS_CD_ID = 'SXDC_SE_CD' AND (B.UNT_TASKWK_SE_CD = #{UNT_TASKWK_SE_CD} OR B.UNT_TASKWK_SE_CD IS NULL) ) T2 CROSS JOIN (SELECT A.CMMNS_CD_VALUE AS SRVC_RESRCE_LCLAS_SE_CD --서비스자원대분류구분코드 FROM SAC100 A /*공통코드 값*/ LEFT JOIN SAC110 B /*공통코드값 사용시스템*/ ON B.CMMNS_CD_ID = A.CMMNS_CD_ID AND B.CMMNS_CD_VALUE = A.CMMNS_CD_VALUE WHERE A.CMMNS_CD_ID = 'SRVC_RESRCE_LCLAS_SE_CD' AND (B.UNT_TASKWK_SE_CD = #{UNT_TASKWK_SE_CD} OR B.UNT_TASKWK_SE_CD IS NULL) ) T3 LEFT JOIN (SELECT * FROM (SELECT '02' AS FCLTY_TYPE_SE_CD --시설유형구분코드 , A.SRVC_RESRCE_LCLAS_SE_CD --서비스자원대분류구분코드 , SUM(A.ELESCH_STDENT_MALE_NOPE + A.MSKUL_STDENT_MALE_NOPE + A.HGSCHL_STDENT_MALE_NOPE + A.UNIVA_STDENT_MALE_NOPE + A.ELESCH_OSCHL_MALE_NOPE + A.MSKUL_OSCHL_MALE_NOPE + A.HGSCHL_OSCHL_MALE_NOPE + A.UNIVA_OSCHL_MALE_NOPE + A.AGRDHS_IOCPTN_MALE_NOPE + A.AGRDHS_EMPYMN_MALE_NOPE + A.PARNTS_PRTCR_MALE_NOPE + A.LEADER_MALE_NOPE + A.PEPL_MALE_NOPE) AS M --남자 , SUM(A.ELESCH_STDENT_FEMALE_NOPE + A.MSKUL_STDENT_FEMALE_NOPE + A.HGSCHL_STDENT_FEMALE_NOPE + A.UNIVA_STDENT_FEMALE_NOPE + A.ELESCH_OSCHL_FEMALE_NOPE + A.MSKUL_OSCHL_FEMALE_NOPE + A.HGSCHL_OSCHL_FEMALE_NOPE + A.UNIVA_OSCHL_FEMALE_NOPE + A.AGRDHS_IOCPTN_FEMALE_NOPE + A.AGRDHS_EMPYMN_FEMALE_NOPE + A.PARNTS_PRTCR_FEMALE_NOPE + A.LEADER_FEMALE_NOPE + A.PEPL_FEMALE_NOPE) AS F --여자 FROM SED100 A /*미등록사례*/ JOIN SAA000 B /*통합기관*/ ON B.INST_NO = A.PIC_INST_NO AND B.DEL_YN = 'N' WHERE A.SPRT_BGNG_YMD <= #{END_DT} AND A.SPRT_END_YMD >= #{SRT_DT} AND A.UNT_TASKWK_SE_CD = #{UNT_TASKWK_SE_CD}
AND B.INST_NO = #{INST_NO}
AND B.CTPV_CD = #{CTPV_CD}
AND B.SGG_CD = #{SGG_CD}
AND #{SRVC_BIZ_CL} IN (SELECT AD3.BIZ_CL_SE_CD FROM SED110 AD1 JOIN SDA420 AD2 ON AD2.SRVC_EXCN_BIZ_NO = AD1.SRVC_EXCN_BIZ_NO JOIN SDA400 AD3 ON AD3.SRVC_BIZ_NO = AD2.SRVC_BIZ_NO WHERE AD1.UNREGI_CASE_NO = A.UNREGI_CASE_NO AND AD1.DEL_YN = 'N')
AND #{EXCN_SRVC_BIZ_CL} IN (SELECT AD2.BIZ_CL_SE_CD FROM SED111 AD1 JOIN SDA430 AD2 ON AD2.EXCN_SRVC_BIZ_CL_NO = AD1.EXCN_SRVC_BIZ_CL_NO WHERE AD1.UNREGI_CASE_NO = A.UNREGI_CASE_NO AND AD1.DEL_YN = 'N')
#{instNo}
GROUP BY A.SRVC_RESRCE_LCLAS_SE_CD) UNPIVOT (NOPE FOR SXDC_SE_CD IN (M, F)) ) T ON T.FCLTY_TYPE_SE_CD = T1.FCLTY_TYPE_SE_CD AND T.SXDC_SE_CD = T2.SXDC_SE_CD AND T.SRVC_RESRCE_LCLAS_SE_CD = T3.SRVC_RESRCE_LCLAS_SE_CD GROUP BY CUBE(T2.SXDC_SE_CD_NM, T2.SXDC_SRTNG_SQNCE, T3.SRVC_RESRCE_LCLAS_SE_CD), T1.FCLTY_TYPE_SE_CD, T1.FCLTY_TYPE_SE_CD_NM HAVING GROUPING(T2.SXDC_SE_CD_NM) = GROUPING(T2.SXDC_SRTNG_SQNCE) ORDER BY FCLTY_TYPE_SE_CD, SXDC_SRTNG_SQNCE, SRVC_RESRCE_LCLAS_SE_CD

/*isry.itgcm.fdrmrptstats.mapper.FdrmRptStatsMapper 위기수준에 따른 지원현황 통계- selectCrisisLevelPrecon LEE.SEOUNG.JAE */ SELECT A.CMMNS_CD_VALUE AS CD_VAL , A.CMMNS_CD_VALUE_NM AS CRISIS_SCRENN_RESULT_SE_CD_NM , NVL(B.WHOLE_CASE , 0) AS CASE_MNG_NOPE_T , NVL(CASE_ING , 0) AS CASE_MNG_NOPE_CASE , NVL(TRMN_ING , 0) AS CASE_MNG_NOPE_AFTFCT , NVL(TRMN , 0) AS CASE_MNG_NOPE_TRMN , NVL(WHOLE_CASE2 , 0) AS CASE_MNG_REAL_NOPE_T , NVL(CASE_ING_CASE2, 0) AS CASE_MNG_REAL_NOPE_CASE , NVL(TRMN_ING_CASE2, 0) AS CASE_MNG_REAL_NOPE_AFTCT , NVL(TRMN_CASE2 , 0) AS CASE_MNG_REAL_NOPE_TRMN FROM ( SELECT CMMNS_CD_VALUE , CMMNS_CD_VALUE_NM FROM SAC100 WHERE CMMNS_CD_ID = 'CRISIS_SCRENN_RESULT_SE_CD'
UNION
SELECT '0' , '합계' FROM DUAL
UNION
SELECT '99' , '미실시' FROM DUAL ) A LEFT JOIN ( SELECT NVL(CRISIS_SCRENN_RESULT_SE_CD,'0') AS CRISIS_SCRENN_RESULT_SE_CD , COUNT(TRPR_INFO_NO) AS WHOLE_CASE , COUNT(CASE WHEN CASE_BGNG_YMD <= #{END_DT} AND (CASE_TRMN_YMD > #{END_DT} OR CASE_TRMN_YMD IS NULL) THEN TRPR_INFO_NO END) AS CASE_ING , COUNT(CASE WHEN CASE_TRMN_YMD <= #{END_DT} AND (AFTFCT_TRMN_YMD > #{END_DT} OR AFTFCT_TRMN_YMD IS NULL) AND AFTFCT_MNG_YN = 'Y' THEN TRPR_INFO_NO END) AS TRMN_ING , COUNT(CASE WHEN (CASE_TRMN_YMD BETWEEN #{SRT_DT} AND #{END_DT} AND AFTFCT_MNG_YN = 'N') OR (AFTFCT_TRMN_YMD BETWEEN #{SRT_DT} AND #{END_DT} AND AFTFCT_MNG_YN = 'Y') THEN TRPR_INFO_NO END) AS TRMN , COUNT(DISTINCT NVL(INDV_IDNTFC_NO, TRPR_INFO_NO)) AS WHOLE_CASE2 , COUNT(DISTINCT CASE WHEN CASE_BGNG_YMD <= #{END_DT} AND (CASE_TRMN_YMD > #{END_DT} OR CASE_TRMN_YMD IS NULL) THEN NVL(INDV_IDNTFC_NO, TRPR_INFO_NO) END) AS CASE_ING_CASE2 , COUNT(DISTINCT CASE WHEN CASE_TRMN_YMD <= #{END_DT} AND (AFTFCT_TRMN_YMD > #{END_DT} OR AFTFCT_TRMN_YMD IS NULL) AND AFTFCT_MNG_YN = 'Y' THEN NVL(INDV_IDNTFC_NO, TRPR_INFO_NO) END) AS TRMN_ING_CASE2 , COUNT(DISTINCT CASE WHEN (CASE_TRMN_YMD BETWEEN #{SRT_DT} AND #{END_DT} AND AFTFCT_MNG_YN = 'N') OR (AFTFCT_TRMN_YMD BETWEEN #{SRT_DT} AND #{END_DT} AND AFTFCT_MNG_YN = 'Y') THEN NVL(INDV_IDNTFC_NO, TRPR_INFO_NO) END) AS TRMN_CASE2
FROM ( SELECT A.TRPR_INFO_NO , A.CASE_MNG_NO , A.CASE_MNG_ODRNO , C.INDV_IDNTFC_NO , NVL(D.CRISIS_SCRENN_RESULT_SE_CD,'99') AS CRISIS_SCRENN_RESULT_SE_CD , A.CASE_BGNG_YMD , A.CASE_TRMN_YMD , E.AFTFCT_TRMN_YMD , A.AFTFCT_MNG_YN , COUNT(*) OVER(PARTITION BY C.INDV_IDNTFC_NO) AS COL2 FROM SEB100 A JOIN SEA200 B ON A.TRPR_INFO_NO = B.TRPR_INFO_NO JOIN SEB150 F0 /*사례담당자*/ ON F0.PCHPRS_YN = 'Y' AND F0.CASE_MNG_NO = A.CASE_MNG_NO AND F0.CASE_MNG_ODRNO = A.CASE_MNG_ODRNO JOIN SAA000 F ON F0.PIC_INST_NO = F.INST_NO LEFT JOIN SCA300 C ON B.INDV_IDNTFC_NO = C.INDV_IDNTFC_NO AND C.DEL_YN = 'N' LEFT JOIN ACA150 D ON A.CASE_MNG_NO = D.CASE_MNG_NO AND A.CASE_MNG_ODRNO = D.CASE_MNG_ODRNO AND D.CRISIS_SCRENN_RESULT_SE_CD IS NOT NULL LEFT JOIN SEC320 E ON A.CASE_MNG_NO = E.CASE_MNG_NO AND A.CASE_MNG_ODRNO = E.CASE_MNG_ODRNO
WHERE A.UNT_TASKWK_SE_CD = #{UNT_TASKWK_SE_CD}
-- 시도코드 AND F.CTPV_CD = #{CTPV_CD}
-- 시군구코드 AND F.SGG_CD = #{SGG_CD}
-- 기관번호 AND F.INST_NO = #{INST_NO}
-- 사업분류구분코드 AND #{SRVC_BIZ_CL} IN ( SELECT SRVC_BIZ_CL_SE_CD FROM SEB120 AA JOIN SDA420 BB ON BB.SRVC_EXCN_BIZ_NO = AA.SRVC_EXCN_BIZ_NO JOIN SDA400 CC ON CC.SRVC_BIZ_NO = BB.SRVC_BIZ_NO WHERE AA.DEL_YN = 'N' AND AA.CASE_MNG_NO = A.CASE_MNG_NO AND AA.CASE_MNG_ODRNO = A.CASE_MNG_ODRNO )
-- 사업분류구분코드 AND #{EXCN_SRVC_BIZ_CL} IN ( SELECT SRVC_BIZ_CL_SE_CD FROM SEB120 AA JOIN SDA420 BB ON BB.SRVC_EXCN_BIZ_NO = AA.SRVC_EXCN_BIZ_NO JOIN SDA400 CC ON CC.SRVC_BIZ_NO = BB.SRVC_BIZ_NO WHERE AA.DEL_YN = 'N' AND AA.CASE_MNG_NO = A.CASE_MNG_NO AND AA.CASE_MNG_ODRNO = A.CASE_MNG_ODRNO )
#{instNo}
AND A.CASE_BGNG_YMD <= #{END_DT} AND ( A.CASE_TRMN_YMD >= #{SRT_DT} OR A.CASE_TRMN_YMD IS NULL OR E.AFTFCT_TRMN_YMD >= #{SRT_DT} OR (A.AFTFCT_MNG_YN = 'Y' AND E.AFTFCT_TRMN_YMD IS NULL)) AND B.DEL_YN = 'N' ) GROUP BY ROLLUP(CRISIS_SCRENN_RESULT_SE_CD) ) B ON B.CRISIS_SCRENN_RESULT_SE_CD = A.CMMNS_CD_VALUE ORDER BY A.CMMNS_CD_VALUE

/*isry.itgcm.fdrmrptstats.mapper.FdrmRptStatsMapper 1388전화상담 통계 - select1388TlphonDscsn LEE.SEOUNG.JAE */ SELECT SXDC_SE_CD , PROBM_STTS_LCLAS_SE_CD , NOPE , NVL(B.CMMNS_CD_VALUE_NM, '합계') AS SXDC_SE_CD_NM FROM ( SELECT NVL(A.SXDC_SE_CD,'A') AS SXDC_SE_CD , NVL(A.PROBM_STTS_LCLAS_SE_CD,'00') AS PROBM_STTS_LCLAS_SE_CD , COUNT(CO13_MNG_NO) AS NOPE FROM ( SELECT A.CMMNS_CD_VALUE_NM AS SXDC_SE_NM , A.CMMNS_CD_VALUE AS SXDC_SE_CD , B.CMMNS_CD_VALUE AS PROBM_STTS_LCLAS_SE_CD FROM SAC100 A CROSS JOIN SAC100 B JOIN SAC110 C ON C.UNT_TASKWK_SE_CD = #{UNT_TASKWK_SE_CD} AND C.CMMNS_CD_VALUE = B.CMMNS_CD_VALUE AND C.CMMNS_CD_ID = B.CMMNS_CD_ID WHERE A.CMMNS_CD_ID = 'SXDC_SE_CD' AND B.CMMNS_CD_ID = 'PROBM_STTS_LCLAS_SE_CD' ) A LEFT JOIN ( SELECT A.TRPR_INFO_NO , NVL(A.SXDC_SE_CD,'X') AS SXDC_SE_CD , E.PROBM_STTS_LCLAS_SE_CD , B.CO13_MNG_NO FROM ACA140 B LEFT JOIN SEA200 A ON A.TRPR_INFO_NO = B.TRPR_INFO_NO AND A.DEL_YN = 'N' LEFT JOIN SAA000 C ON C.INST_NO = B.INST_NO LEFT JOIN ACA141 E ON B.CO13_MNG_NO = E.CO13_MNG_NO AND CO13_SN = '1' WHERE B.UNT_TASKWK_SE_CD = #{UNT_TASKWK_SE_CD} -- 기간구분 AND B.DSCSN_YMD BETWEEN #{SRT_DT} AND #{END_DT}
-- 시도코드 AND C.CTPV_CD = #{CTPV_CD}
-- 시군구코드 AND C.SGG_CD = #{SGG_CD}
-- 기관번호 AND B.INST_NO = #{INST_NO}
#{instNo}
) B ON A.SXDC_SE_CD = B.SXDC_SE_CD AND A.PROBM_STTS_LCLAS_SE_CD = B.PROBM_STTS_LCLAS_SE_CD GROUP BY A.PROBM_STTS_LCLAS_SE_CD, ROLLUP(A.SXDC_SE_CD) ) A LEFT JOIN SAC100 B ON B.CMMNS_CD_ID= 'SXDC_SE_CD' AND B.CMMNS_CD_VALUE = A.SXDC_SE_CD ORDER BY CASE WHEN A.SXDC_SE_CD = 'A' THEN 1 WHEN A.SXDC_SE_CD = 'M' THEN 2 WHEN A.SXDC_SE_CD = 'F' THEN 3 ELSE 4 END

/*isry.itgcm.fdrmrptstats.mapper.FdrmRptStatsMapper - selectEfectnEvlSrvcDgstfn[효과성 평가 및 서비스 만족도] : Lee SangHoon*/
SELECT NVL(T1.SXDC_SE_CD_NM,'합계') AS SXDC_SE_CD_NM --성별구분코드명 , NVL(T1.SXDC_SRTNG_SQNCE,0) AS SXDC_SRTNG_SQNCE --성별코드순번 , COUNT(T.EFECTN_EVL_CASE_CNT) AS EFECTN_EVL_CASE_CNT --효과성평가사례수 , COUNT(T.INCRS_NOCS) AS INCRS_NOCS --증가건수 , CASE COUNT(T.EFECTN_EVL_CASE_CNT) WHEN 0 THEN 0 ELSE ROUND(COUNT(T.INCRS_NOCS)/COUNT(T.EFECTN_EVL_CASE_CNT)*10000)/100 END AS INCRS_RATE --증가비율 , COUNT(T.SAMENS_NOCS) AS SAMENS_NOCS --동일건수 , CASE COUNT(T.EFECTN_EVL_CASE_CNT) WHEN 0 THEN 0 ELSE ROUND(COUNT(T.SAMENS_NOCS)/COUNT(T.EFECTN_EVL_CASE_CNT)*10000)/100 END AS SAMENS_RATE --동일비율 , COUNT(T.DCRS_NOCS) AS DCRS_NOCS --감소건수 , CASE COUNT(T.EFECTN_EVL_CASE_CNT) WHEN 0 THEN 0 ELSE ROUND(COUNT(T.DCRS_NOCS)/COUNT(T.EFECTN_EVL_CASE_CNT)*10000)/100 END AS DCRS_RATE --감소비율 , ROUND(NVL(AVG(T.BEFFAT_AVRG),0)*100)/100 AS BEFFAT_AVRG --사전평균 , ROUND(NVL(AVG(T.AFTFCT_AVRG),0)*100)/100 AS AFTFCT_AVRG --사후평균 , ROUND((NVL(AVG(T.AFTFCT_AVRG),0) - NVL(AVG(T.BEFFAT_AVRG),0))*100)/100 AS INCRS_DCRS_SCORE --증감점수 , CASE NVL(AVG(T.BEFFAT_AVRG),0) WHEN 0 THEN 0 ELSE ROUND((NVL(AVG(T.AFTFCT_AVRG),0) - NVL(AVG(T.BEFFAT_AVRG),0))/NVL(AVG(T.BEFFAT_AVRG),0)*10000)/100 END AS INCRS_DCRS_RATE --증감율 , COUNT(T.SRVC_DGSTFN_CASE_CNT) AS SRVC_DGSTFN_CASE_CNT --서비스만족도평가사례수 , ROUND(NVL(AVG(T.SRVC_DGSTFN_AVRG_SCORE),0)*100)/100 AS SRVC_DGSTFN_AVRG_SCORE --서비스만족도평균점수 FROM (SELECT A.CMMNS_CD_VALUE AS SXDC_SE_CD --성별구분코드 , A.CMMNS_CD_VALUE_NM AS SXDC_SE_CD_NM --성별구분코드명 , A.SRTNG_SQNCE AS SXDC_SRTNG_SQNCE --성별순번 FROM SAC100 A /*공통코드 값*/ LEFT JOIN SAC110 B /*공통코드값 사용시스템*/ ON B.CMMNS_CD_ID = A.CMMNS_CD_ID AND B.CMMNS_CD_VALUE = A.CMMNS_CD_VALUE WHERE A.CMMNS_CD_ID = 'SXDC_SE_CD' AND (B.UNT_TASKWK_SE_CD = #{UNT_TASKWK_SE_CD} OR B.UNT_TASKWK_SE_CD IS NULL) ) T1 LEFT JOIN (SELECT B.SXDC_SE_CD --성별구분코드 , D.CASE_MNG_NO AS EFECTN_EVL_CASE_CNT --효과성평가사례수 , CASE WHEN C.SCORE > D.SCORE THEN A.CASE_MNG_NO END AS INCRS_NOCS --증가건수 , CASE WHEN C.SCORE = D.SCORE THEN A.CASE_MNG_NO END AS SAMENS_NOCS --동일건수 , CASE WHEN C.SCORE < D.SCORE THEN A.CASE_MNG_NO END AS DCRS_NOCS --감소건수 , D.SCORE AS BEFFAT_AVRG --사전평균 , CASE WHEN D.CASE_MNG_NO IS NOT NULL THEN C.SCORE END AS AFTFCT_AVRG --사후평균 , E.CASE_MNG_NO AS SRVC_DGSTFN_CASE_CNT --서비스만족도평가사례수 , E.SCORE AS SRVC_DGSTFN_AVRG_SCORE --서비스만족도평균점수 FROM SEB100 A /*사례기본*/ JOIN SEA200 B /*대상자정보*/ ON B.TRPR_INFO_NO = A.TRPR_INFO_NO AND B.DEL_YN = 'N' LEFT JOIN (SELECT C1.CASE_MNG_NO --사례관리번호 , C1.CASE_MNG_ODRNO --사례관리차수 , NVL(SUM(C3.QESITM_SINGL_RSPNS_VALUE),0) AS SCORE --점수 , ROW_NUMBER() OVER(PARTITION BY C1.CASE_MNG_NO, C1.CASE_MNG_ODRNO ORDER BY C1.QUSTNB_MNG_NO DESC, C2.SRVY_RSPNS_MNG_NO DESC) AS RN FROM SBB110 C1 /*설문대상자*/ JOIN SBB500 C2 /*설문응답*/ ON C2.QUSTNB_MNG_NO = C1.QUSTNB_MNG_NO JOIN SBB220 C3 /*항목별응답내용*/ ON C3.SRVY_RSPNS_MNG_NO = C2.SRVY_RSPNS_MNG_NO WHERE C1.QUSTNB_SHAPE_SE_CD = '04' AND C2.RSPNS_DT BETWEEN #{SRT_DT} AND #{END_DT} GROUP BY C1.QUSTNB_MNG_NO, C1.CASE_MNG_NO, C1.CASE_MNG_ODRNO, C2.SRVY_RSPNS_MNG_NO ) C ON C.CASE_MNG_NO = A.CASE_MNG_NO AND C.CASE_MNG_ODRNO = A.CASE_MNG_ODRNO AND C.RN = 1 LEFT JOIN (SELECT D1.CASE_MNG_NO --사례관리번호 , D1.CASE_MNG_ODRNO --사례관리차수 , NVL(SUM(D3.QESITM_SINGL_RSPNS_VALUE),0) AS SCORE --점수 , ROW_NUMBER() OVER(PARTITION BY D1.CASE_MNG_NO, D1.CASE_MNG_ODRNO ORDER BY D1.QUSTNB_MNG_NO DESC, D2.SRVY_RSPNS_MNG_NO DESC) AS RN FROM SBB110 D1 /*설문대상자*/ JOIN SBB500 D2 /*설문응답*/ ON D2.QUSTNB_MNG_NO = D1.QUSTNB_MNG_NO JOIN SBB220 D3 /*항목별응답내용*/ ON D3.SRVY_RSPNS_MNG_NO = D2.SRVY_RSPNS_MNG_NO WHERE D1.QUSTNB_SHAPE_SE_CD = '03' GROUP BY D1.QUSTNB_MNG_NO, D1.CASE_MNG_NO, D1.CASE_MNG_ODRNO, D2.SRVY_RSPNS_MNG_NO ) D ON D.CASE_MNG_NO = C.CASE_MNG_NO AND D.CASE_MNG_ODRNO = C.CASE_MNG_ODRNO AND D.RN = 1 LEFT JOIN (SELECT E1.CASE_MNG_NO --사례관리번호 , E1.CASE_MNG_ODRNO --사례관리차수 , NVL(SUM(E3.QESITM_SINGL_RSPNS_VALUE),0) AS SCORE --점수 , ROW_NUMBER() OVER(PARTITION BY E1.CASE_MNG_NO, E1.CASE_MNG_ODRNO ORDER BY E1.QUSTNB_MNG_NO DESC, E2.SRVY_RSPNS_MNG_NO DESC) AS RN FROM SBB110 E1 /*설문대상자*/ JOIN SBB500 E2 /*설문응답*/ ON E2.QUSTNB_MNG_NO = E1.QUSTNB_MNG_NO JOIN SBB220 E3 /*항목별응답내용*/ ON E3.SRVY_RSPNS_MNG_NO = E2.SRVY_RSPNS_MNG_NO WHERE E1.QUSTNB_SHAPE_SE_CD = '05' AND E2.RSPNS_DT BETWEEN #{SRT_DT} AND #{END_DT} GROUP BY E1.QUSTNB_MNG_NO, E1.CASE_MNG_NO, E1.CASE_MNG_ODRNO, E2.SRVY_RSPNS_MNG_NO ) E ON E.CASE_MNG_NO = A.CASE_MNG_NO AND E.CASE_MNG_ODRNO = A.CASE_MNG_ODRNO AND E.RN = 1 JOIN SEB150 F /*사례담당자*/ ON F.CASE_MNG_NO = A.CASE_MNG_NO AND F.CASE_MNG_ODRNO = A.CASE_MNG_ODRNO AND F.PCHPRS_YN = 'Y' JOIN SAA000 G /*통합기관*/ ON G.INST_NO = F.PIC_INST_NO AND G.DEL_YN = 'N' WHERE A.UNT_TASKWK_SE_CD = #{UNT_TASKWK_SE_CD}
AND G.INST_NO = #{INST_NO}
AND G.CTPV_CD = #{CTPV_CD}
AND G.SGG_CD = #{SGG_CD}
AND #{SRVC_BIZ_CL} IN (SELECT AD3.BIZ_CL_SE_CD FROM SEB120 AD1 JOIN SDA420 AD2 ON AD2.SRVC_EXCN_BIZ_NO = AD1.SRVC_EXCN_BIZ_NO JOIN SDA400 AD3 ON AD3.SRVC_BIZ_NO = AD2.SRVC_BIZ_NO WHERE AD1.CASE_MNG_NO = A.CASE_MNG_NO AND AD1.CASE_MNG_ODRNO = A.CASE_MNG_ODRNO AND AD1.DEL_YN = 'N')
#{instNo}
) T ON T.SXDC_SE_CD = T1.SXDC_SE_CD GROUP BY ROLLUP(SXDC_SE_CD_NM, SXDC_SRTNG_SQNCE) HAVING GROUPING(SXDC_SE_CD_NM) = GROUPING(SXDC_SRTNG_SQNCE) ORDER BY SXDC_SRTNG_SQNCE

/*isry.itgcm.fdrmrptstats.mapper.FdrmRptStatsMapper - selectOutcStats[성과] : Lee SangHoon*/
SELECT NVL(T1.OUTC_CN_LCLAS_SE_CD_NM,'합계(실인원) *사례관리번호 기준') AS OUTC_CN_LCLAS_SE_CD_NM --성과내용대분류구분코드명 , NVL(T1.OUTC_CN_LCLAS_SE_CD,'00') AS OUTC_CN_LCLAS_SE_CD --성과내용대분류구분코드 , NVL(T1.OUTC_CN_MLSFC_SE_CD_NM, CASE WHEN T1.OUTC_CN_LCLAS_SE_CD IS NULL THEN NULL ELSE '소계(실인원) *사례관리번호 기준' END) AS OUTC_CN_MLSFC_SE_CD_NM --성과내용중분류구분코드명 , NVL(T1.OUTC_CN_MLSFC_SE_CD,T1.OUTC_CN_LCLAS_SE_CD || '00') AS OUTC_CN_MLSFC_SE_CD --성과내용중분류구분코드 , CASE WHEN T1.OUTC_CN_MLSFC_SE_CD IS NULL THEN COUNT(DISTINCT T.CASE_MNG_NO) ELSE COUNT(T.CASE_MNG_NO) END AS SUM --합계 , CASE WHEN T1.OUTC_CN_MLSFC_SE_CD IS NULL THEN COUNT(DISTINCT T.MALE) ELSE COUNT(T.MALE) END AS MALE --남성 , CASE WHEN T1.OUTC_CN_MLSFC_SE_CD IS NULL THEN COUNT(DISTINCT T.FEMALE) ELSE COUNT(T.FEMALE) END AS FEMALE --여성 , CASE WHEN T1.OUTC_CN_MLSFC_SE_CD IS NULL THEN COUNT(DISTINCT T.UNCNFR) ELSE COUNT(T.UNCNFR) END AS UNCNFR --미확인 FROM (SELECT A.CMMNS_CD_VALUE AS OUTC_CN_LCLAS_SE_CD --성과내용대분류구분코드 , A.CMMNS_CD_VALUE_NM AS OUTC_CN_LCLAS_SE_CD_NM --성과내용대분류구분코드명 , A2.CMMNS_CD_VALUE AS OUTC_CN_MLSFC_SE_CD --성과내용중분류구분코드 , A2.CMMNS_CD_VALUE_NM AS OUTC_CN_MLSFC_SE_CD_NM --성과내용중분류구분코드명 FROM SAC100 A /*공통코드 값(대분류)*/ LEFT JOIN SAC110 B /*공통코드값 사용시스템(대분류)*/ ON B.CMMNS_CD_ID = A.CMMNS_CD_ID AND B.CMMNS_CD_VALUE = A.CMMNS_CD_VALUE LEFT JOIN SAC100 A2 /*공통코드 값(중분류)*/ ON A2.CMMNS_CD_ID = 'OUTC_CN_MLSFC_SE_CD' AND A2.UP_CMMNS_CD_VALUE = A.CMMNS_CD_VALUE LEFT JOIN SAC110 B2 /*공통코드값 사용시스템(중분류)*/ ON B2.CMMNS_CD_ID = A2.CMMNS_CD_ID AND B2.CMMNS_CD_VALUE = A2.CMMNS_CD_VALUE WHERE A.CMMNS_CD_ID = 'OUTC_CN_LCLAS_SE_CD' AND (B.UNT_TASKWK_SE_CD = #{UNT_TASKWK_SE_CD} OR B.UNT_TASKWK_SE_CD IS NULL) AND (B2.UNT_TASKWK_SE_CD = #{UNT_TASKWK_SE_CD} OR B2.UNT_TASKWK_SE_CD IS NULL) ) T1 LEFT JOIN (SELECT A.CASE_MNG_NO --사례관리번호 , B.OUTC_CN_LCLAS_SE_CD --성과내용대분류구분코드 , B.OUTC_CN_MLSFC_SE_CD --성과내용중분류구분코드 , CASE C.SXDC_SE_CD WHEN 'M' THEN A.CASE_MNG_NO END AS MALE --남성 , CASE C.SXDC_SE_CD WHEN 'F' THEN A.CASE_MNG_NO END AS FEMALE --여성 , CASE C.SXDC_SE_CD WHEN 'X' THEN A.CASE_MNG_NO END AS UNCNFR --미확인 FROM SEB100 A /*사례기본*/ JOIN AKA130 B /*성과관리-성과내용*/ ON B.CASE_MNG_NO = A.CASE_MNG_NO AND B.CASE_MNG_ODRNO = A.CASE_MNG_ODRNO JOIN SEA200 C /*대상자정보*/ ON C.TRPR_INFO_NO = A.TRPR_INFO_NO AND C.DEL_YN = 'N' JOIN SEB150 D /*사례담당자*/ ON D.CASE_MNG_NO = A.CASE_MNG_NO AND D.CASE_MNG_ODRNO = A.CASE_MNG_ODRNO AND D.PCHPRS_YN = 'Y' JOIN SAA000 E /*통합기관*/ ON E.INST_NO = D.PIC_INST_NO AND E.DEL_YN = 'N' WHERE B.OUTC_YMD BETWEEN #{SRT_DT} AND #{END_DT} AND B.UNT_TASKWK_SE_CD = #{UNT_TASKWK_SE_CD}
AND E.INST_NO = #{INST_NO}
AND E.CTPV_CD = #{CTPV_CD}
AND E.SGG_CD = #{SGG_CD}
AND #{SRVC_BIZ_CL} IN (SELECT AD3.BIZ_CL_SE_CD FROM SEB120 AD1 JOIN SDA420 AD2 ON AD2.SRVC_EXCN_BIZ_NO = AD1.SRVC_EXCN_BIZ_NO JOIN SDA400 AD3 ON AD3.SRVC_BIZ_NO = AD2.SRVC_BIZ_NO WHERE AD1.CASE_MNG_NO = A.CASE_MNG_NO AND AD1.CASE_MNG_ODRNO = A.CASE_MNG_ODRNO AND AD1.DEL_YN = 'N')
#{instNo}
) T ON T.OUTC_CN_LCLAS_SE_CD = T1.OUTC_CN_LCLAS_SE_CD AND T.OUTC_CN_MLSFC_SE_CD = T1.OUTC_CN_MLSFC_SE_CD GROUP BY CUBE(T1.OUTC_CN_LCLAS_SE_CD_NM, T1.OUTC_CN_LCLAS_SE_CD, T1.OUTC_CN_MLSFC_SE_CD_NM, T1.OUTC_CN_MLSFC_SE_CD) HAVING GROUPING(T1.OUTC_CN_LCLAS_SE_CD_NM) = GROUPING(T1.OUTC_CN_LCLAS_SE_CD) AND GROUPING(T1.OUTC_CN_MLSFC_SE_CD_NM) = GROUPING(T1.OUTC_CN_MLSFC_SE_CD) AND (GROUPING(T1.OUTC_CN_LCLAS_SE_CD) = 0 OR GROUPING(T1.OUTC_CN_MLSFC_SE_CD) = 1) ORDER BY OUTC_CN_LCLAS_SE_CD, CASE WHEN OUTC_CN_MLSFC_SE_CD = '0200' THEN 1 WHEN OUTC_CN_MLSFC_SE_CD = '0201' THEN 2 WHEN OUTC_CN_MLSFC_SE_CD = '0202' THEN 5 WHEN OUTC_CN_MLSFC_SE_CD = '0203' THEN 3 WHEN OUTC_CN_MLSFC_SE_CD = '0204' THEN 4 END , OUTC_CN_MLSFC_SE_CD

/*isry.itgcm.fdrmrptstats.mapper.FdrmRptStatsMapper 아웃리치 활동 통계- selectOutrcActvt*/ WITH X AS ( --추후 코드 변경 시 수정될 수 있는 부분 (MAX, MIN 부분...) SELECT ERYY_GR_DSCSN_NO , CASE WHEN MAX(UNEART_ACTVT_SE_CD) = '202' AND MIN(UNEART_ACTVT_PIC_CNT) > 0 THEN '02' ELSE '03' END AS DSCSN_CD FROM SEA140 /*초기집단상담담당자*/ WHERE 1=1 AND DEL_YN = 'N' GROUP BY ERYY_GR_DSCSN_NO ) SELECT A.SCN_CD AS FCLTY_TYPE_SE_CD , A.SCN_NM AS FCLTY_TYPE_SE_CD_NM , B.DSCSN_CD AS DSTNC_DSCSN_SPCLTY_STAFF_CD , B.DSCSN_NM AS DSTNC_DSCSN_SPCLTY_STAFF_SE , SUM(NVL(C.ERYY_DSCSN_MALE_NOPE, 0)) + SUM(NVL(C.ERYY_DSCSN_FEMALE_NOPE, 0)) AS MKCTT_YNGBGS_CNT_T , SUM(NVL(C.ERYY_DSCSN_MALE_NOPE, 0)) AS MKCTT_YNGBGS_CNT_M , SUM(NVL(C.ERYY_DSCSN_FEMALE_NOPE, 0)) AS MKCTT_YNGBGS_CNT_F , SUM(NVL(C.ACTN_SN, 0)) + SUM(NVL(C.ETC_DSCSN_CNT, 0)) AS DSTNC_DSCSN_SUBTOT , SUM(NVL(C.ACTN_SN, 0)) AS DSTNC_DSCSN_OUTHFA , SUM(NVL(C.ETC_DSCSN_CNT, 0)) AS DSTNC_DSCSN_ETC , SUM(NVL(C.NOPE_01_CNT, 0)) AS TRL_INSP -- 인원수(01:심리검사) , SUM(NVL(C.NOPE_02_CNT, 0)) AS CLNIC_MDLRT_SPRT -- 인원수(02:진료 및 치료지원) , SUM(NVL(C.NOPE_03_CNT, 0)) AS MEDICI_NRCLG_SPRT -- 인원수(03:의약품, 의약외품지원) , SUM(NVL(C.NOPE_04_CNT, 0)) AS CLTHA_SPRT -- 인원수(04:의복지원) , SUM(NVL(C.NOPE_05_CNT, 0)) AS SNITAT_SPRT -- 인원수(05:위생지원) , SUM(NVL(C.NOPE_06_CNT, 0)) AS FDSTFA_SPRT -- 인원수(06:먹거리지원) , SUM(NVL(C.NOPE_07_CNT, 0)) AS TRNSPO_MVMN_SPRT -- 인원수(07:교통(이동지원)) , SUM(NVL(C.NOPE_08_CNT, 0)) AS REST_PSTM_SPRT -- 인원수(08:휴식 및 놀이지원) , SUM(NVL(C.NOPE_09_CNT, 0)) AS LVING_SUPLI_SPRT -- 인원수(09:생활용품 지원) , SUM(NVL(C.NOPE_10_CNT, 0)) AS PR_INFO_PVSN -- 인원수(10:홍보 및 정보제공) , SUM(NVL(C.NOPE_99_CNT, 0)) AS SRVC_SPRT_ETC -- 인원수(99:기타) FROM ( SELECT '00' AS SCN_CD , '합계' AS SCN_NM FROM DUAL UNION ALL SELECT A.CMMNS_CD_VALUE AS SCN_CD , A.CMMNS_CD_VALUE_NM AS SCN_NM FROM SAC100 A JOIN SAC110 B ON A.CMMNS_CD_ID = B.CMMNS_CD_ID AND A.CMMNS_CD_VALUE = B.CMMNS_CD_VALUE WHERE A.CMMNS_CD_ID = 'FCLTY_TYPE_SE_CD' AND A.USE_YN = 'Y' AND B.UNT_TASKWK_SE_CD = #{UNT_TASKWK_SE_CD} ) A CROSS JOIN ( SELECT '01' AS DSCSN_CD , '합계' AS DSCSN_NM FROM DUAL UNION ALL SELECT '02' AS DSCSN_CD , '거리상담전문요원' AS DSCSN_NM FROM DUAL UNION ALL SELECT '03' AS DSCSN_CD , '기타인원' AS DSCSN_NM FROM DUAL ) B LEFT JOIN ( ( /*전체합계*/ SELECT '01' AS DSCSN_CD , '00' AS FCLTY_TYPE_SE_CD , SUM(NVL(ERYY_DSCSN_MALE_NOPE, 0)) AS ERYY_DSCSN_MALE_NOPE , SUM(NVL(ERYY_DSCSN_FEMALE_NOPE, 0)) AS ERYY_DSCSN_FEMALE_NOPE , SUM(NVL(C.ACTN_SN, 0)) AS ACTN_SN , SUM(NVL(D.ETC_DSCSN_CNT, 0)) AS ETC_DSCSN_CNT -- 그외상담수 , SUM(NVL(D.NOPE_01_CNT, 0)) AS NOPE_01_CNT -- 인원수(01:심리검사) , SUM(NVL(D.NOPE_02_CNT, 0)) AS NOPE_02_CNT -- 인원수(02:진료 및 치료지원) , SUM(NVL(D.NOPE_03_CNT, 0)) AS NOPE_03_CNT -- 인원수(03:의약품, 의약외품지원) , SUM(NVL(D.NOPE_04_CNT, 0)) AS NOPE_04_CNT -- 인원수(04:의복지원) , SUM(NVL(D.NOPE_05_CNT, 0)) AS NOPE_05_CNT -- 인원수(05:위생지원) , SUM(NVL(D.NOPE_06_CNT, 0)) AS NOPE_06_CNT -- 인원수(06:먹거리지원) , SUM(NVL(D.NOPE_07_CNT, 0)) AS NOPE_07_CNT -- 인원수(07:교통(이동지원)) , SUM(NVL(D.NOPE_08_CNT, 0)) AS NOPE_08_CNT -- 인원수(08:휴식 및 놀이지원) , SUM(NVL(D.NOPE_09_CNT, 0)) AS NOPE_09_CNT -- 인원수(09:생활용품 지원) , SUM(NVL(D.NOPE_10_CNT, 0)) AS NOPE_10_CNT -- 인원수(10:홍보 및 정보제공) , SUM(NVL(D.NOPE_99_CNT, 0)) AS NOPE_99_CNT -- 인원수(99:기타) FROM SEA120 A /*초기집단상담*/ LEFT JOIN AKA500 F ON A.RGTR_INST_NO = F.INST_NO LEFT JOIN X B ON A.ERYY_GR_DSCSN_NO = B.ERYY_GR_DSCSN_NO LEFT JOIN ( SELECT A.ERYY_GR_DSCSN_NO , COUNT(NVL(ACTN_SN, 0)) AS ACTN_SN , B.DSCSN_CD FROM SEA130 A /*집단상담후조치*/ LEFT JOIN X B ON A.ERYY_GR_DSCSN_NO = B.ERYY_GR_DSCSN_NO WHERE 1=1 AND NVL(DEL_YN, 'N') = 'N' GROUP BY A.ERYY_GR_DSCSN_NO, B.DSCSN_CD ) C ON A.ERYY_GR_DSCSN_NO = C.ERYY_GR_DSCSN_NO AND B.DSCSN_CD = C.DSCSN_CD LEFT JOIN ( SELECT A.ERYY_GR_DSCSN_NO , SUM(CASE WHEN SPRT_SRVC_SE_CD = '98' THEN NVL(SPRT_SRVC_TRGT_NOPE,0) ELSE 0 END) AS ETC_DSCSN_CNT -- 그외상담수 , SUM(CASE WHEN SPRT_SRVC_SE_CD = '01' THEN NVL(SPRT_SRVC_TRGT_NOPE,0) ELSE 0 END) AS NOPE_01_CNT -- 인원수(01:심리검사) , SUM(CASE WHEN SPRT_SRVC_SE_CD = '02' THEN NVL(SPRT_SRVC_TRGT_NOPE,0) ELSE 0 END) AS NOPE_02_CNT -- 인원수(02:진료 및 치료지원) , SUM(CASE WHEN SPRT_SRVC_SE_CD = '03' THEN NVL(SPRT_SRVC_TRGT_NOPE,0) ELSE 0 END) AS NOPE_03_CNT -- 인원수(03:의약품, 의약외품지원) , SUM(CASE WHEN SPRT_SRVC_SE_CD = '04' THEN NVL(SPRT_SRVC_TRGT_NOPE,0) ELSE 0 END) AS NOPE_04_CNT -- 인원수(04:의복지원) , SUM(CASE WHEN SPRT_SRVC_SE_CD = '05' THEN NVL(SPRT_SRVC_TRGT_NOPE,0) ELSE 0 END) AS NOPE_05_CNT -- 인원수(05:위생지원) , SUM(CASE WHEN SPRT_SRVC_SE_CD = '06' THEN NVL(SPRT_SRVC_TRGT_NOPE,0) ELSE 0 END) AS NOPE_06_CNT -- 인원수(06:먹거리지원) , SUM(CASE WHEN SPRT_SRVC_SE_CD = '07' THEN NVL(SPRT_SRVC_TRGT_NOPE,0) ELSE 0 END) AS NOPE_07_CNT -- 인원수(07:교통(이동지원)) , SUM(CASE WHEN SPRT_SRVC_SE_CD = '08' THEN NVL(SPRT_SRVC_TRGT_NOPE,0) ELSE 0 END) AS NOPE_08_CNT -- 인원수(08:휴식 및 놀이지원) , SUM(CASE WHEN SPRT_SRVC_SE_CD = '09' THEN NVL(SPRT_SRVC_TRGT_NOPE,0) ELSE 0 END) AS NOPE_09_CNT -- 인원수(09:생활용품 지원) , SUM(CASE WHEN SPRT_SRVC_SE_CD = '10' THEN NVL(SPRT_SRVC_TRGT_NOPE,0) ELSE 0 END) AS NOPE_10_CNT -- 인원수(10:홍보 및 정보제공) , SUM(CASE WHEN SPRT_SRVC_SE_CD = '99' THEN NVL(SPRT_SRVC_TRGT_NOPE,0) ELSE 0 END) AS NOPE_99_CNT -- 인원수(99:기타) , B.DSCSN_CD FROM SEA150 A /*집단상담후지원서비스*/ LEFT JOIN X B ON A.ERYY_GR_DSCSN_NO = B.ERYY_GR_DSCSN_NO WHERE 1=1 AND SPRT_SRVC_SE_CD IN ('01','02','03','04','05','06','07','08','09','10','97','98','99') GROUP BY A.ERYY_GR_DSCSN_NO, B.DSCSN_CD ) D ON A.ERYY_GR_DSCSN_NO = D.ERYY_GR_DSCSN_NO AND B.DSCSN_CD = D.DSCSN_CD LEFT JOIN SAA000 F3 /*통합기관*/ ON F3.INST_NO = F.INST_NO WHERE 1=1 AND F.FCLTY_TYPE_SE_CD IS NOT NULL AND A.DSCSN_YMD BETWEEN #{SRT_DT} AND #{END_DT}
/*시도코드*/ AND F3.CTPV_CD = #{CTPV_CD}
/*시군구코드*/ AND F3.SGG_CD = #{SGG_CD}
/*기관번호*/ AND F3.INST_NO = #{INST_NO}
/* 권한적용 별개로 해야함(자기기관 + 하위기관) */ ) UNION ALL ( /*합계*/ SELECT B.DSCSN_CD , '00' AS FCLTY_TYPE_SE_CD , SUM(NVL(ERYY_DSCSN_MALE_NOPE, 0)) AS ERYY_DSCSN_MALE_NOPE , SUM(NVL(ERYY_DSCSN_FEMALE_NOPE, 0)) AS ERYY_DSCSN_FEMALE_NOPE , SUM(NVL(C.ACTN_SN, 0)) AS ACTN_SN , SUM(NVL(D.ETC_DSCSN_CNT, 0)) AS ETC_DSCSN_CNT -- 그외상담수 , SUM(NVL(D.NOPE_01_CNT, 0)) AS NOPE_01_CNT -- 인원수(01:심리검사) , SUM(NVL(D.NOPE_02_CNT, 0)) AS NOPE_02_CNT -- 인원수(02:진료 및 치료지원) , SUM(NVL(D.NOPE_03_CNT, 0)) AS NOPE_03_CNT -- 인원수(03:의약품, 의약외품지원) , SUM(NVL(D.NOPE_04_CNT, 0)) AS NOPE_04_CNT -- 인원수(04:의복지원) , SUM(NVL(D.NOPE_05_CNT, 0)) AS NOPE_05_CNT -- 인원수(05:위생지원) , SUM(NVL(D.NOPE_06_CNT, 0)) AS NOPE_06_CNT -- 인원수(06:먹거리지원) , SUM(NVL(D.NOPE_07_CNT, 0)) AS NOPE_07_CNT -- 인원수(07:교통(이동지원)) , SUM(NVL(D.NOPE_08_CNT, 0)) AS NOPE_08_CNT -- 인원수(08:휴식 및 놀이지원) , SUM(NVL(D.NOPE_09_CNT, 0)) AS NOPE_09_CNT -- 인원수(09:생활용품 지원) , SUM(NVL(D.NOPE_10_CNT, 0)) AS NOPE_10_CNT -- 인원수(10:홍보 및 정보제공) , SUM(NVL(D.NOPE_99_CNT, 0)) AS NOPE_99_CNT -- 인원수(99:기타) FROM SEA120 A /*초기집단상담*/ LEFT JOIN AKA500 F ON A.RGTR_INST_NO = F.INST_NO LEFT JOIN X B ON A.ERYY_GR_DSCSN_NO = B.ERYY_GR_DSCSN_NO LEFT JOIN ( SELECT A.ERYY_GR_DSCSN_NO , COUNT(NVL(ACTN_SN, 0)) AS ACTN_SN , B.DSCSN_CD FROM SEA130 A /*집단상담후조치*/ LEFT JOIN X B ON A.ERYY_GR_DSCSN_NO = B.ERYY_GR_DSCSN_NO WHERE 1=1 AND NVL(DEL_YN, 'N') = 'N' GROUP BY A.ERYY_GR_DSCSN_NO, B.DSCSN_CD ) C ON A.ERYY_GR_DSCSN_NO = C.ERYY_GR_DSCSN_NO AND B.DSCSN_CD = C.DSCSN_CD LEFT JOIN ( SELECT A.ERYY_GR_DSCSN_NO , SUM(CASE WHEN SPRT_SRVC_SE_CD = '98' THEN NVL(SPRT_SRVC_TRGT_NOPE,0) ELSE 0 END) AS ETC_DSCSN_CNT -- 그외상담수 , SUM(CASE WHEN SPRT_SRVC_SE_CD = '01' THEN NVL(SPRT_SRVC_TRGT_NOPE,0) ELSE 0 END) AS NOPE_01_CNT -- 인원수(01:심리검사) , SUM(CASE WHEN SPRT_SRVC_SE_CD = '02' THEN NVL(SPRT_SRVC_TRGT_NOPE,0) ELSE 0 END) AS NOPE_02_CNT -- 인원수(02:진료 및 치료지원) , SUM(CASE WHEN SPRT_SRVC_SE_CD = '03' THEN NVL(SPRT_SRVC_TRGT_NOPE,0) ELSE 0 END) AS NOPE_03_CNT -- 인원수(03:의약품, 의약외품지원) , SUM(CASE WHEN SPRT_SRVC_SE_CD = '04' THEN NVL(SPRT_SRVC_TRGT_NOPE,0) ELSE 0 END) AS NOPE_04_CNT -- 인원수(04:의복지원) , SUM(CASE WHEN SPRT_SRVC_SE_CD = '05' THEN NVL(SPRT_SRVC_TRGT_NOPE,0) ELSE 0 END) AS NOPE_05_CNT -- 인원수(05:위생지원) , SUM(CASE WHEN SPRT_SRVC_SE_CD = '06' THEN NVL(SPRT_SRVC_TRGT_NOPE,0) ELSE 0 END) AS NOPE_06_CNT -- 인원수(06:먹거리지원) , SUM(CASE WHEN SPRT_SRVC_SE_CD = '07' THEN NVL(SPRT_SRVC_TRGT_NOPE,0) ELSE 0 END) AS NOPE_07_CNT -- 인원수(07:교통(이동지원)) , SUM(CASE WHEN SPRT_SRVC_SE_CD = '08' THEN NVL(SPRT_SRVC_TRGT_NOPE,0) ELSE 0 END) AS NOPE_08_CNT -- 인원수(08:휴식 및 놀이지원) , SUM(CASE WHEN SPRT_SRVC_SE_CD = '09' THEN NVL(SPRT_SRVC_TRGT_NOPE,0) ELSE 0 END) AS NOPE_09_CNT -- 인원수(09:생활용품 지원) , SUM(CASE WHEN SPRT_SRVC_SE_CD = '10' THEN NVL(SPRT_SRVC_TRGT_NOPE,0) ELSE 0 END) AS NOPE_10_CNT -- 인원수(10:홍보 및 정보제공) , SUM(CASE WHEN SPRT_SRVC_SE_CD = '99' THEN NVL(SPRT_SRVC_TRGT_NOPE,0) ELSE 0 END) AS NOPE_99_CNT -- 인원수(99:기타) , B.DSCSN_CD FROM SEA150 A /*집단상담후지원서비스*/ LEFT JOIN X B ON A.ERYY_GR_DSCSN_NO = B.ERYY_GR_DSCSN_NO WHERE 1=1 AND SPRT_SRVC_SE_CD IN ('01','02','03','04','05','06','07','08','09','10','97','98','99') GROUP BY A.ERYY_GR_DSCSN_NO, B.DSCSN_CD ) D ON A.ERYY_GR_DSCSN_NO = D.ERYY_GR_DSCSN_NO AND B.DSCSN_CD = D.DSCSN_CD LEFT JOIN SAA000 F3 /*통합기관*/ ON F3.INST_NO = F.INST_NO WHERE 1=1 AND F.FCLTY_TYPE_SE_CD IS NOT NULL AND A.DSCSN_YMD BETWEEN #{SRT_DT} AND #{END_DT}
/*시도코드*/ AND F3.CTPV_CD = #{CTPV_CD}
/*시군구코드*/ AND F3.SGG_CD = #{SGG_CD}
/*기관번호*/ AND F3.INST_NO = #{INST_NO}
/* 권한적용 별개로 해야함(자기기관 + 하위기관) */
GROUP BY B.DSCSN_CD ) UNION ALL ( /*부분합계*/ SELECT '01' AS DSCSN_CD , F.FCLTY_TYPE_SE_CD , SUM(NVL(ERYY_DSCSN_MALE_NOPE, 0)) AS ERYY_DSCSN_MALE_NOPE , SUM(NVL(ERYY_DSCSN_FEMALE_NOPE, 0)) AS ERYY_DSCSN_FEMALE_NOPE , SUM(NVL(C.ACTN_SN, 0)) AS ACTN_SN , SUM(NVL(D.ETC_DSCSN_CNT, 0)) AS ETC_DSCSN_CNT -- 그외상담수 , SUM(NVL(D.NOPE_01_CNT, 0)) AS NOPE_01_CNT -- 인원수(01:심리검사) , SUM(NVL(D.NOPE_02_CNT, 0)) AS NOPE_02_CNT -- 인원수(02:진료 및 치료지원) , SUM(NVL(D.NOPE_03_CNT, 0)) AS NOPE_03_CNT -- 인원수(03:의약품, 의약외품지원) , SUM(NVL(D.NOPE_04_CNT, 0)) AS NOPE_04_CNT -- 인원수(04:의복지원) , SUM(NVL(D.NOPE_05_CNT, 0)) AS NOPE_05_CNT -- 인원수(05:위생지원) , SUM(NVL(D.NOPE_06_CNT, 0)) AS NOPE_06_CNT -- 인원수(06:먹거리지원) , SUM(NVL(D.NOPE_07_CNT, 0)) AS NOPE_07_CNT -- 인원수(07:교통(이동지원)) , SUM(NVL(D.NOPE_08_CNT, 0)) AS NOPE_08_CNT -- 인원수(08:휴식 및 놀이지원) , SUM(NVL(D.NOPE_09_CNT, 0)) AS NOPE_09_CNT -- 인원수(09:생활용품 지원) , SUM(NVL(D.NOPE_10_CNT, 0)) AS NOPE_10_CNT -- 인원수(10:홍보 및 정보제공) , SUM(NVL(D.NOPE_99_CNT, 0)) AS NOPE_99_CNT -- 인원수(99:기타) FROM SEA120 A /*초기집단상담*/ LEFT JOIN AKA500 F ON A.RGTR_INST_NO = F.INST_NO LEFT JOIN X B ON A.ERYY_GR_DSCSN_NO = B.ERYY_GR_DSCSN_NO LEFT JOIN ( SELECT A.ERYY_GR_DSCSN_NO , COUNT(NVL(ACTN_SN, 0)) AS ACTN_SN , B.DSCSN_CD FROM SEA130 A /*집단상담후조치*/ LEFT JOIN X B ON A.ERYY_GR_DSCSN_NO = B.ERYY_GR_DSCSN_NO WHERE 1=1 AND NVL(DEL_YN, 'N') = 'N' GROUP BY A.ERYY_GR_DSCSN_NO, B.DSCSN_CD ) C ON A.ERYY_GR_DSCSN_NO = C.ERYY_GR_DSCSN_NO AND B.DSCSN_CD = C.DSCSN_CD LEFT JOIN ( SELECT A.ERYY_GR_DSCSN_NO , SUM(CASE WHEN SPRT_SRVC_SE_CD = '98' THEN NVL(SPRT_SRVC_TRGT_NOPE,0) ELSE 0 END) AS ETC_DSCSN_CNT -- 그외상담수 , SUM(CASE WHEN SPRT_SRVC_SE_CD = '01' THEN NVL(SPRT_SRVC_TRGT_NOPE,0) ELSE 0 END) AS NOPE_01_CNT -- 인원수(01:심리검사) , SUM(CASE WHEN SPRT_SRVC_SE_CD = '02' THEN NVL(SPRT_SRVC_TRGT_NOPE,0) ELSE 0 END) AS NOPE_02_CNT -- 인원수(02:진료 및 치료지원) , SUM(CASE WHEN SPRT_SRVC_SE_CD = '03' THEN NVL(SPRT_SRVC_TRGT_NOPE,0) ELSE 0 END) AS NOPE_03_CNT -- 인원수(03:의약품, 의약외품지원) , SUM(CASE WHEN SPRT_SRVC_SE_CD = '04' THEN NVL(SPRT_SRVC_TRGT_NOPE,0) ELSE 0 END) AS NOPE_04_CNT -- 인원수(04:의복지원) , SUM(CASE WHEN SPRT_SRVC_SE_CD = '05' THEN NVL(SPRT_SRVC_TRGT_NOPE,0) ELSE 0 END) AS NOPE_05_CNT -- 인원수(05:위생지원) , SUM(CASE WHEN SPRT_SRVC_SE_CD = '06' THEN NVL(SPRT_SRVC_TRGT_NOPE,0) ELSE 0 END) AS NOPE_06_CNT -- 인원수(06:먹거리지원) , SUM(CASE WHEN SPRT_SRVC_SE_CD = '07' THEN NVL(SPRT_SRVC_TRGT_NOPE,0) ELSE 0 END) AS NOPE_07_CNT -- 인원수(07:교통(이동지원)) , SUM(CASE WHEN SPRT_SRVC_SE_CD = '08' THEN NVL(SPRT_SRVC_TRGT_NOPE,0) ELSE 0 END) AS NOPE_08_CNT -- 인원수(08:휴식 및 놀이지원) , SUM(CASE WHEN SPRT_SRVC_SE_CD = '09' THEN NVL(SPRT_SRVC_TRGT_NOPE,0) ELSE 0 END) AS NOPE_09_CNT -- 인원수(09:생활용품 지원) , SUM(CASE WHEN SPRT_SRVC_SE_CD = '10' THEN NVL(SPRT_SRVC_TRGT_NOPE,0) ELSE 0 END) AS NOPE_10_CNT -- 인원수(10:홍보 및 정보제공) , SUM(CASE WHEN SPRT_SRVC_SE_CD = '99' THEN NVL(SPRT_SRVC_TRGT_NOPE,0) ELSE 0 END) AS NOPE_99_CNT -- 인원수(99:기타) , B.DSCSN_CD FROM SEA150 A /*집단상담후지원서비스*/ LEFT JOIN X B ON A.ERYY_GR_DSCSN_NO = B.ERYY_GR_DSCSN_NO WHERE 1=1 AND SPRT_SRVC_SE_CD IN ('01','02','03','04','05','06','07','08','09','10','97','98','99') GROUP BY A.ERYY_GR_DSCSN_NO, B.DSCSN_CD ) D ON A.ERYY_GR_DSCSN_NO = D.ERYY_GR_DSCSN_NO AND B.DSCSN_CD = D.DSCSN_CD LEFT JOIN SAA000 F3 /*통합기관*/ ON F3.INST_NO = F.INST_NO WHERE 1=1 AND A.DSCSN_YMD BETWEEN #{SRT_DT} AND #{END_DT}
/*시도코드*/ AND F3.CTPV_CD = #{CTPV_CD}
/*시군구코드*/ AND F3.SGG_CD = #{SGG_CD}
/*기관번호*/ AND F3.INST_NO = #{INST_NO}
/* 권한적용 별개로 해야함(자기기관 + 하위기관) */
GROUP BY B.DSCSN_CD, F.FCLTY_TYPE_SE_CD ) UNION ALL ( /*통계*/ SELECT B.DSCSN_CD , F.FCLTY_TYPE_SE_CD , SUM(NVL(ERYY_DSCSN_MALE_NOPE, 0)) AS ERYY_DSCSN_MALE_NOPE , SUM(NVL(ERYY_DSCSN_FEMALE_NOPE, 0)) AS ERYY_DSCSN_FEMALE_NOPE , SUM(NVL(C.ACTN_SN, 0)) AS ACTN_SN , SUM(NVL(D.ETC_DSCSN_CNT, 0)) AS ETC_DSCSN_CNT -- 그외상담수 , SUM(NVL(D.NOPE_01_CNT, 0)) AS NOPE_01_CNT -- 인원수(01:심리검사) , SUM(NVL(D.NOPE_02_CNT, 0)) AS NOPE_02_CNT -- 인원수(02:진료 및 치료지원) , SUM(NVL(D.NOPE_03_CNT, 0)) AS NOPE_03_CNT -- 인원수(03:의약품, 의약외품지원) , SUM(NVL(D.NOPE_04_CNT, 0)) AS NOPE_04_CNT -- 인원수(04:의복지원) , SUM(NVL(D.NOPE_05_CNT, 0)) AS NOPE_05_CNT -- 인원수(05:위생지원) , SUM(NVL(D.NOPE_06_CNT, 0)) AS NOPE_06_CNT -- 인원수(06:먹거리지원) , SUM(NVL(D.NOPE_07_CNT, 0)) AS NOPE_07_CNT -- 인원수(07:교통(이동지원)) , SUM(NVL(D.NOPE_08_CNT, 0)) AS NOPE_08_CNT -- 인원수(08:휴식 및 놀이지원) , SUM(NVL(D.NOPE_09_CNT, 0)) AS NOPE_09_CNT -- 인원수(09:생활용품 지원) , SUM(NVL(D.NOPE_10_CNT, 0)) AS NOPE_10_CNT -- 인원수(10:홍보 및 정보제공) , SUM(NVL(D.NOPE_99_CNT, 0)) AS NOPE_99_CNT -- 인원수(99:기타) FROM SEA120 A /*초기집단상담*/ LEFT JOIN AKA500 F ON A.RGTR_INST_NO = F.INST_NO LEFT JOIN X B ON A.ERYY_GR_DSCSN_NO = B.ERYY_GR_DSCSN_NO LEFT JOIN ( SELECT A.ERYY_GR_DSCSN_NO , COUNT(NVL(ACTN_SN, 0)) AS ACTN_SN , B.DSCSN_CD FROM SEA130 A /*집단상담후조치*/ LEFT JOIN X B ON A.ERYY_GR_DSCSN_NO = B.ERYY_GR_DSCSN_NO WHERE 1=1 AND NVL(DEL_YN, 'N') = 'N' GROUP BY A.ERYY_GR_DSCSN_NO, B.DSCSN_CD ) C ON A.ERYY_GR_DSCSN_NO = C.ERYY_GR_DSCSN_NO AND B.DSCSN_CD = C.DSCSN_CD LEFT JOIN ( SELECT A.ERYY_GR_DSCSN_NO , SUM(CASE WHEN SPRT_SRVC_SE_CD = '98' THEN NVL(SPRT_SRVC_TRGT_NOPE,0) ELSE 0 END) AS ETC_DSCSN_CNT -- 그외상담수 , SUM(CASE WHEN SPRT_SRVC_SE_CD = '01' THEN NVL(SPRT_SRVC_TRGT_NOPE,0) ELSE 0 END) AS NOPE_01_CNT -- 인원수(01:심리검사) , SUM(CASE WHEN SPRT_SRVC_SE_CD = '02' THEN NVL(SPRT_SRVC_TRGT_NOPE,0) ELSE 0 END) AS NOPE_02_CNT -- 인원수(02:진료 및 치료지원) , SUM(CASE WHEN SPRT_SRVC_SE_CD = '03' THEN NVL(SPRT_SRVC_TRGT_NOPE,0) ELSE 0 END) AS NOPE_03_CNT -- 인원수(03:의약품, 의약외품지원) , SUM(CASE WHEN SPRT_SRVC_SE_CD = '04' THEN NVL(SPRT_SRVC_TRGT_NOPE,0) ELSE 0 END) AS NOPE_04_CNT -- 인원수(04:의복지원) , SUM(CASE WHEN SPRT_SRVC_SE_CD = '05' THEN NVL(SPRT_SRVC_TRGT_NOPE,0) ELSE 0 END) AS NOPE_05_CNT -- 인원수(05:위생지원) , SUM(CASE WHEN SPRT_SRVC_SE_CD = '06' THEN NVL(SPRT_SRVC_TRGT_NOPE,0) ELSE 0 END) AS NOPE_06_CNT -- 인원수(06:먹거리지원) , SUM(CASE WHEN SPRT_SRVC_SE_CD = '07' THEN NVL(SPRT_SRVC_TRGT_NOPE,0) ELSE 0 END) AS NOPE_07_CNT -- 인원수(07:교통(이동지원)) , SUM(CASE WHEN SPRT_SRVC_SE_CD = '08' THEN NVL(SPRT_SRVC_TRGT_NOPE,0) ELSE 0 END) AS NOPE_08_CNT -- 인원수(08:휴식 및 놀이지원) , SUM(CASE WHEN SPRT_SRVC_SE_CD = '09' THEN NVL(SPRT_SRVC_TRGT_NOPE,0) ELSE 0 END) AS NOPE_09_CNT -- 인원수(09:생활용품 지원) , SUM(CASE WHEN SPRT_SRVC_SE_CD = '10' THEN NVL(SPRT_SRVC_TRGT_NOPE,0) ELSE 0 END) AS NOPE_10_CNT -- 인원수(10:홍보 및 정보제공) , SUM(CASE WHEN SPRT_SRVC_SE_CD = '99' THEN NVL(SPRT_SRVC_TRGT_NOPE,0) ELSE 0 END) AS NOPE_99_CNT -- 인원수(99:기타) , B.DSCSN_CD FROM SEA150 A /*집단상담후지원서비스*/ LEFT JOIN X B ON A.ERYY_GR_DSCSN_NO = B.ERYY_GR_DSCSN_NO WHERE 1=1 AND SPRT_SRVC_SE_CD IN ('01','02','03','04','05','06','07','08','09','10','97','98','99') GROUP BY A.ERYY_GR_DSCSN_NO, B.DSCSN_CD ) D ON A.ERYY_GR_DSCSN_NO = D.ERYY_GR_DSCSN_NO AND B.DSCSN_CD = D.DSCSN_CD LEFT JOIN SAA000 F3 /*통합기관*/ ON F3.INST_NO = F.INST_NO WHERE 1=1 AND A.DSCSN_YMD BETWEEN #{SRT_DT} AND #{END_DT}
/*시도코드*/ AND F3.CTPV_CD = #{CTPV_CD}
/*시군구코드*/ AND F3.SGG_CD = #{SGG_CD}
/*기관번호*/ AND F3.INST_NO = #{INST_NO}
/* 권한적용 별개로 해야함(자기기관 + 하위기관) */
GROUP BY B.DSCSN_CD, F.FCLTY_TYPE_SE_CD) ) C ON B.DSCSN_CD = C.DSCSN_CD AND A.SCN_CD = C.FCLTY_TYPE_SE_CD WHERE 1=1 GROUP BY B.DSCSN_CD, A.SCN_CD, A.SCN_NM, B.DSCSN_NM ORDER BY CASE WHEN A.SCN_CD = '00' THEN 1 WHEN A.SCN_CD = '01' THEN 3 WHEN A.SCN_CD = '02' THEN 2 WHEN A.SCN_CD = '03' THEN 4 WHEN A.SCN_CD = '04' THEN 5 END , B.DSCSN_CD

/*isry.itgcm.fdrmrptstats.mapper.FdrmRptStatsMapper 가정밖청소년 지원현황- selectOuthfaYngbgsActnPrecon*/ WITH X AS ( SELECT A.DSCSN_YMD , B.ACTN_TYPE_SE_CD , B.ACTN_TYPE_DTL_SE_CD , B.TRPR_INFO_NO , C.SXDC_SE_CD , D.FCLTY_TYPE_SE_CD , E.DSCSN_CD FROM SEA120 A LEFT JOIN SEA130 B ON A.ERYY_GR_DSCSN_NO = B.ERYY_GR_DSCSN_NO LEFT JOIN SEA200 C ON B.TRPR_INFO_NO = C.TRPR_INFO_NO LEFT JOIN AKA500 D ON A.RGTR_INST_NO = D.INST_NO LEFT JOIN( --추후 코드 변경 시 수정할 수 있는 부분 SELECT ERYY_GR_DSCSN_NO , CASE WHEN MAX(UNEART_ACTVT_SE_CD) = '202' AND MIN(UNEART_ACTVT_PIC_CNT) > 0 THEN '02' ELSE '03' END AS DSCSN_CD FROM SEA140 /*초기집단상담담당자*/ WHERE 1=1 AND DEL_YN = 'N' GROUP BY ERYY_GR_DSCSN_NO ) E ON A.ERYY_GR_DSCSN_NO = E.ERYY_GR_DSCSN_NO AND B.ERYY_GR_DSCSN_NO = E.ERYY_GR_DSCSN_NO LEFT JOIN SAA000 F3 /*통합기관*/ ON F3.INST_NO = D.INST_NO WHERE 1=1 AND B.DEL_YN = 'N' AND D.FCLTY_TYPE_SE_CD IS NOT NULL AND A.UNT_TASKWK_SE_CD = #{UNT_TASKWK_SE_CD} AND A.DSCSN_YMD BETWEEN #{SRT_DT} AND #{END_DT}
/*시도코드*/ AND F3.CTPV_CD = #{CTPV_CD}
/*시군구코드*/ AND F3.SGG_CD = #{SGG_CD}
/*기관번호*/ AND F3.INST_NO = #{INST_NO}
/* 권한적용 별개로 해야함(자기기관 + 하위기관) */
) SELECT A.SCN_CD AS FCLTY_TYPE_SE_CD , A.SCN_NM AS FCLTY_TYPE_SE_CD_NM , B.DSCSN_CD AS DSTNC_DSCSN_SPCLTY_STAFF_CD , B.DSCSN_NM AS DSTNC_DSCSN_SPCLTY_STAFF_SE , NVL(C.ACTN_NOPE_M, 0) + NVL(C.ACTN_NOPE_F, 0) + NVL(C.ACTN_NOPE_X, 0) AS ACTN_NOPE_T , NVL(C.ACTN_NOPE_M, 0) AS ACTN_NOPE_M , NVL(C.ACTN_NOPE_F, 0) AS ACTN_NOPE_F , NVL(C.ACTN_NOPE_X, 0) AS ACTN_NOPE_X , NVL(C.ACTN_MATTER_HMCM, 0) AS ACTN_MATTER_HMCM , NVL(C.ACTN_MATTER_OUSH, 0) AS ACTN_MATTER_OUSH , NVL(C.ACTN_MATTER_OTSHTR, 0) AS ACTN_MATTER_OTSHTR , NVL(C.ACTN_MATTER_EMRG_RESC, 0) AS ACTN_MATTER_EMRG_RESC , NVL(C.ACTN_MATTER_OTFCLT_PRTCTN_LINK, 0) AS ACTN_MATTER_OTFCLT_PRTCTN_LINK , NVL(C.ACTN_MATTER_OTHNST_SRVC_LINK, 0) AS ACTN_MATTER_OTHNST_SRVC_LINK , NVL(C.ACTN_MATTER_ETC, 0) AS ACTN_MATTER_ETC FROM ( SELECT '00' AS SCN_CD , '합계' AS SCN_NM FROM DUAL UNION ALL SELECT A.CMMNS_CD_VALUE AS SCN_CD , A.CMMNS_CD_VALUE_NM AS SCN_NM FROM SAC100 A JOIN SAC110 B ON A.CMMNS_CD_ID = B.CMMNS_CD_ID AND A.CMMNS_CD_VALUE = B.CMMNS_CD_VALUE WHERE A.CMMNS_CD_ID = 'FCLTY_TYPE_SE_CD' AND A.USE_YN = 'Y' AND B.UNT_TASKWK_SE_CD = 'U04' ) A CROSS JOIN ( SELECT '01' AS DSCSN_CD , '합계' AS DSCSN_NM FROM DUAL UNION ALL SELECT '02' AS DSCSN_CD , '거리상담전문요원' AS DSCSN_NM FROM DUAL UNION ALL SELECT '03' AS DSCSN_CD , '기타인원' AS DSCSN_NM FROM DUAL ) B LEFT JOIN ( SELECT '00' AS FCLTY_TYPE_SE_CD , '01' AS DSCSN_CD , COUNT(CASE WHEN SXDC_SE_CD = 'M' THEN 1 END) AS ACTN_NOPE_M , COUNT(CASE WHEN SXDC_SE_CD = 'F' THEN 1 END) AS ACTN_NOPE_F , COUNT(CASE WHEN SXDC_SE_CD = 'X' THEN 1 END) AS ACTN_NOPE_X , COUNT(CASE WHEN ACTN_TYPE_SE_CD = '01' THEN 1 END) AS ACTN_MATTER_HMCM , COUNT(CASE WHEN ACTN_TYPE_SE_CD = '02' AND ACTN_TYPE_DTL_SE_CD = '01' THEN 1 END) AS ACTN_MATTER_OUSH , COUNT(CASE WHEN ACTN_TYPE_SE_CD = '02' AND ACTN_TYPE_DTL_SE_CD = '02' THEN 1 END) AS ACTN_MATTER_OTSHTR , COUNT(CASE WHEN ACTN_TYPE_SE_CD = '03' AND ACTN_TYPE_DTL_SE_CD = '03' THEN 1 END) AS ACTN_MATTER_EMRG_RESC , COUNT(CASE WHEN ACTN_TYPE_SE_CD = '03' AND ACTN_TYPE_DTL_SE_CD = '04' THEN 1 END) AS ACTN_MATTER_OTFCLT_PRTCTN_LINK , COUNT(CASE WHEN ACTN_TYPE_SE_CD = '03' AND ACTN_TYPE_DTL_SE_CD = '05' THEN 1 END) AS ACTN_MATTER_OTHNST_SRVC_LINK , COUNT(CASE WHEN ACTN_TYPE_SE_CD = '99' THEN 1 END) AS ACTN_MATTER_ETC FROM X UNION ALL SELECT '00' AS FCLTY_TYPE_SE_CD , DSCSN_CD , COUNT(CASE WHEN SXDC_SE_CD = 'M' THEN 1 END) AS ACTN_NOPE_M , COUNT(CASE WHEN SXDC_SE_CD = 'F' THEN 1 END) AS ACTN_NOPE_F , COUNT(CASE WHEN SXDC_SE_CD = 'X' THEN 1 END) AS ACTN_NOPE_X , COUNT(CASE WHEN ACTN_TYPE_SE_CD = '01' THEN 1 END) AS ACTN_MATTER_HMCM , COUNT(CASE WHEN ACTN_TYPE_SE_CD = '02' AND ACTN_TYPE_DTL_SE_CD = '01' THEN 1 END) AS ACTN_MATTER_OUSH , COUNT(CASE WHEN ACTN_TYPE_SE_CD = '02' AND ACTN_TYPE_DTL_SE_CD = '02' THEN 1 END) AS ACTN_MATTER_OTSHTR , COUNT(CASE WHEN ACTN_TYPE_SE_CD = '03' AND ACTN_TYPE_DTL_SE_CD = '03' THEN 1 END) AS ACTN_MATTER_EMRG_RESC , COUNT(CASE WHEN ACTN_TYPE_SE_CD = '03' AND ACTN_TYPE_DTL_SE_CD = '04' THEN 1 END) AS ACTN_MATTER_OTFCLT_PRTCTN_LINK , COUNT(CASE WHEN ACTN_TYPE_SE_CD = '03' AND ACTN_TYPE_DTL_SE_CD = '05' THEN 1 END) AS ACTN_MATTER_OTHNST_SRVC_LINK , COUNT(CASE WHEN ACTN_TYPE_SE_CD = '99' THEN 1 END) AS ACTN_MATTER_ETC FROM X GROUP BY DSCSN_CD UNION ALL SELECT FCLTY_TYPE_SE_CD , '01' AS DSCSN_CD , COUNT(CASE WHEN SXDC_SE_CD = 'M' THEN 1 END) AS ACTN_NOPE_M , COUNT(CASE WHEN SXDC_SE_CD = 'F' THEN 1 END) AS ACTN_NOPE_F , COUNT(CASE WHEN SXDC_SE_CD = 'X' THEN 1 END) AS ACTN_NOPE_X , COUNT(CASE WHEN ACTN_TYPE_SE_CD = '01' THEN 1 END) AS ACTN_MATTER_HMCM , COUNT(CASE WHEN ACTN_TYPE_SE_CD = '02' AND ACTN_TYPE_DTL_SE_CD = '01' THEN 1 END) AS ACTN_MATTER_OUSH , COUNT(CASE WHEN ACTN_TYPE_SE_CD = '02' AND ACTN_TYPE_DTL_SE_CD = '02' THEN 1 END) AS ACTN_MATTER_OTSHTR , COUNT(CASE WHEN ACTN_TYPE_SE_CD = '03' AND ACTN_TYPE_DTL_SE_CD = '03' THEN 1 END) AS ACTN_MATTER_EMRG_RESC , COUNT(CASE WHEN ACTN_TYPE_SE_CD = '03' AND ACTN_TYPE_DTL_SE_CD = '04' THEN 1 END) AS ACTN_MATTER_OTFCLT_PRTCTN_LINK , COUNT(CASE WHEN ACTN_TYPE_SE_CD = '03' AND ACTN_TYPE_DTL_SE_CD = '05' THEN 1 END) AS ACTN_MATTER_OTHNST_SRVC_LINK , COUNT(CASE WHEN ACTN_TYPE_SE_CD = '99' THEN 1 END) AS ACTN_MATTER_ETC FROM X GROUP BY FCLTY_TYPE_SE_CD, DSCSN_CD UNION ALL SELECT FCLTY_TYPE_SE_CD , DSCSN_CD , COUNT(CASE WHEN SXDC_SE_CD = 'M' THEN 1 END) AS ACTN_NOPE_M , COUNT(CASE WHEN SXDC_SE_CD = 'F' THEN 1 END) AS ACTN_NOPE_F , COUNT(CASE WHEN SXDC_SE_CD = 'X' THEN 1 END) AS ACTN_NOPE_X , COUNT(CASE WHEN ACTN_TYPE_SE_CD = '01' THEN 1 END) AS ACTN_MATTER_HMCM , COUNT(CASE WHEN ACTN_TYPE_SE_CD = '02' AND ACTN_TYPE_DTL_SE_CD = '01' THEN 1 END) AS ACTN_MATTER_OUSH , COUNT(CASE WHEN ACTN_TYPE_SE_CD = '02' AND ACTN_TYPE_DTL_SE_CD = '02' THEN 1 END) AS ACTN_MATTER_OTSHTR , COUNT(CASE WHEN ACTN_TYPE_SE_CD = '03' AND ACTN_TYPE_DTL_SE_CD = '03' THEN 1 END) AS ACTN_MATTER_EMRG_RESC , COUNT(CASE WHEN ACTN_TYPE_SE_CD = '03' AND ACTN_TYPE_DTL_SE_CD = '04' THEN 1 END) AS ACTN_MATTER_OTFCLT_PRTCTN_LINK , COUNT(CASE WHEN ACTN_TYPE_SE_CD = '03' AND ACTN_TYPE_DTL_SE_CD = '05' THEN 1 END) AS ACTN_MATTER_OTHNST_SRVC_LINK , COUNT(CASE WHEN ACTN_TYPE_SE_CD = '99' THEN 1 END) AS ACTN_MATTER_ETC FROM X GROUP BY FCLTY_TYPE_SE_CD, DSCSN_CD ) C ON A.SCN_CD = C.FCLTY_TYPE_SE_CD AND B.DSCSN_CD = C.DSCSN_CD
ORDER BY CASE WHEN A.SCN_CD = '00' THEN 1 WHEN A.SCN_CD = '01' THEN 3 WHEN A.SCN_CD = '02' THEN 2 WHEN A.SCN_CD = '03' THEN 4 WHEN A.SCN_CD = '04' THEN 5 END , B.DSCSN_CD

/*isry.itgcm.fdrmrptstats.mapper.FdrmRptStatsMapper 입퇴소 사례지원(쉼터별) - selectEntrncLvngCaseMngSheltrType*/ WITH X AS ( SELECT A.CASE_PRGRS_STTS_SE_CD --사례진행상태구분코드 , B.TRPR_INFO_NO --대상자정보번호 , A.CASE_MNG_NO , B.INDV_IDNTFC_NO , A.AFTFCT_MNG_YN --사후관리여부 , A.CASE_BGNG_YMD --사례시작일자 , A.CASE_TRMN_YMD --사례종결일자 , B.SXDC_SE_CD --성별구분 , C.AFTFCT_TRMN_YMD --사후종결일자 , A.AFTFCT_MNG_YN AS AFTFCT_YN --사후관리여부 , H.FCLTY_TYPE_SE_CD , TO_DATE(#{SRT_DT} || '000000', 'YYYYMMDDHH24MISS') AS SRT_DT --검색조건시작 , TO_DATE(#{END_DT} || '235959', 'YYYYMMDDHH24MISS') AS END_DT --검색조건종료 , ROUND(CASE WHEN TO_DATE(#{END_DT} || '235959', 'YYYYMMDDHH24MISS') <= NVL(TO_DATE(CASE_TRMN_YMD, 'YYYYMMDDHH24MISS'), TO_DATE(#{END_DT} || '235959', 'YYYYMMDDHH24MISS')) THEN TO_DATE(#{END_DT} || '235959', 'YYYYMMDDHH24MISS') ELSE TO_DATE(CASE_TRMN_YMD || '235959', 'YYYYMMDDHH24MISS') END - CASE WHEN TO_DATE(TO_CHAR(A.CASE_BGNG_YMD || '000000'), 'YYYYMMDDHH24MISS') < TO_DATE(#{SRT_DT} || '000000', 'YYYYMMDDHH24MISS') THEN TO_DATE(#{SRT_DT} || '000000', 'YYYYMMDDHH24MISS') ELSE TO_DATE(TO_CHAR(A.CASE_BGNG_YMD || '000000'), 'YYYYMMDDHH24MISS') END) + 1 AS USE_NMPR FROM SEB100 A JOIN SEA200 B ON A.TRPR_INFO_NO = B.TRPR_INFO_NO LEFT JOIN SEC320 C ON A.CASE_MNG_NO = C.CASE_MNG_NO AND A.CASE_MNG_ODRNO = C.CASE_MNG_ODRNO LEFT JOIN SEB150 F0 /*사례담당자*/ ON F0.PCHPRS_YN = 'Y' AND F0.CASE_MNG_NO = A.CASE_MNG_NO AND F0.CASE_MNG_ODRNO = A.CASE_MNG_ODRNO LEFT JOIN SAA000 F3 /*통합기관*/ ON F3.INST_NO = F0.PIC_INST_NO LEFT JOIN SEB120 D ON A.CASE_MNG_NO = D.CASE_MNG_NO AND A.CASE_MNG_ODRNO = D.CASE_MNG_ODRNO AND D.DEL_YN = 'N' LEFT JOIN SDA420 E /*서비스실행사업*/ ON E.SRVC_EXCN_BIZ_NO = D.SRVC_EXCN_BIZ_NO LEFT JOIN SDA400 F /*서비스사업*/ ON E.SRVC_BIZ_NO = F.SRVC_BIZ_NO LEFT JOIN SDA430 G /*실행서비스사업*/ ON F.BIZ_YR = G.BIZ_YR AND F.SRVC_BIZ_NM = G.SRVC_BIZ_NM AND G.UNT_TASKWK_SE_CD = #{UNT_TASKWK_SE_CD} LEFT JOIN AKA500 H /*센터현황*/ ON H.INST_NO = F3.INST_NO
WHERE 1=1 AND A.UNT_TASKWK_SE_CD = #{UNT_TASKWK_SE_CD}
/*시도코드*/ AND F3.CTPV_CD = #{CTPV_CD}
/*시군구코드*/ AND F3.SGG_CD = #{SGG_CD}
/*기관번호*/ AND F3.INST_NO = #{INST_NO}
/*서비스사업분류구분코드*/ AND F.BIZ_CL_SE_CD = #{SRVC_BIZ_CL}
/*실행사업분류구분코드*/ AND G.BIZ_CL_SE_CD = #{EXCN_SRVC_BIZ_CL}
/* 권한적용 별개로 해야함(자기기관 + 하위기관) */
) SELECT A.SCN_CD AS FCLTY_TYPE_SE_CD /*기관구분*/ , A.SCN_NM AS FCLTY_TYPE_SE_CD_NM /*기관구분*/ , A.SXDC_CD AS SXDC_SE_CD /*성별구분*/ , A.SXDC_NM AS SXDC_SE_CD_NM /*성별구분*/ , NVL(B.ALL_CASE_MNG_ENTRNC, 0) + NVL(B.ALL_CASE_MNG_NEW_ENTRNC, 0) + NVL(B.ALL_CASE_MNG_LVNG, 0) + NVL(B.ALL_CASE_MNG_ENTRNC_LVNG, 0) + NVL(B.ALL_CASE_MNG_AFTFCT_MNG, 0) + NVL(B.ALL_CASE_MNG_AFTFCT_TRMN, 0) AS ALL_CASE_MNG_SUM /*전체사례 계*/ , NVL(B.ALL_CASE_MNG_ENTRNC, 0) AS ALL_CASE_MNG_ENTRNC /*전체사례 입소중*/ , NVL(B.ALL_CASE_MNG_NEW_ENTRNC, 0) AS ALL_CASE_MNG_NEW_ENTRNC /*전체사례 신규입소*/ , NVL(B.ALL_CASE_MNG_LVNG, 0) AS ALL_CASE_MNG_LVNG /*전체사례 퇴소*/ , NVL(B.ALL_CASE_MNG_ENTRNC_LVNG, 0) AS ALL_CASE_MNG_ENTRNC_LVNG /*전체사례 입퇴소*/ , NVL(B.ALL_CASE_MNG_AFTFCT_MNG, 0) AS ALL_CASE_MNG_AFTFCT_MNG /*전체사례 사후관리중*/ , NVL(B.ALL_CASE_MNG_AFTFCT_TRMN, 0) AS ALL_CASE_MNG_AFTFCT_TRMN /*전체사례 사후종결*/
, NVL(B.REAL_CASE_MNG_ENTRNC, 0) + NVL(B.REAL_CASE_MNG_NEW_ENTRNC, 0) + NVL(B.REAL_CASE_MNG_LVNG, 0) + NVL(B.REAL_CASE_MNG_ENTRNC_LVNG, 0) + NVL(B.REAL_CASE_MNG_AFTFCT_MNG, 0) + NVL(B.REAL_CASE_MNG_AFTFCT_TRMN, 0) AS REAL_CASE_MNG_SUM /*실사례 계*/ , NVL(B.REAL_CASE_MNG_ENTRNC, 0) AS REAL_CASE_MNG_ENTRNC /*실사례 입소중*/ , NVL(B.REAL_CASE_MNG_NEW_ENTRNC, 0) AS REAL_CASE_MNG_NEW_ENTRNC /*실사례 신규입소*/ , NVL(B.REAL_CASE_MNG_LVNG, 0) AS REAL_CASE_MNG_LVNG /*실사례 퇴소*/ , NVL(B.REAL_CASE_MNG_ENTRNC_LVNG, 0) AS REAL_CASE_MNG_ENTRNC_LVNG /*실사례 입퇴소*/ , NVL(B.REAL_CASE_MNG_AFTFCT_MNG, 0) AS REAL_CASE_MNG_AFTFCT_MNG /*실사례 사후관리중*/ , NVL(B.REAL_CASE_MNG_AFTFCT_TRMN, 0) AS REAL_CASE_MNG_AFTFCT_TRMN /*실사례 사후종결*/
, NVL(B.UTZTN_YNGBGS_ENTRNC, 0) + NVL(B.UTZTN_YNGBGS_NEW_ENTRNC, 0) + NVL(B.UTZTN_YNGBGS_LVNG, 0) + NVL(B.UTZTN_YNGBGS_ENTRNC_LVNG, 0) AS UTZTN_YNGBGS_SUM /*이용청소년 계*/ , NVL(B.UTZTN_YNGBGS_ENTRNC, 0) AS UTZTN_YNGBGS_ENTRNC /*이용청소년 입소중*/ , NVL(B.UTZTN_YNGBGS_NEW_ENTRNC, 0) AS UTZTN_YNGBGS_NEW_ENTRNC /*이용청소년 신규입소*/ , NVL(B.UTZTN_YNGBGS_LVNG, 0) AS UTZTN_YNGBGS_LVNG /*이용청소년 퇴소*/ , NVL(B.UTZTN_YNGBGS_ENTRNC_LVNG, 0) AS UTZTN_YNGBGS_ENTRNC_LVNG /*이용청소년 입퇴소*/ FROM ( SELECT A.CMMNS_CD_VALUE AS SCN_CD , A.CMMNS_CD_VALUE_NM AS SCN_NM , B.SXDC_CD , B.SXDC_NM FROM SAC100 A JOIN SAC110 B ON A.CMMNS_CD_ID = B.CMMNS_CD_ID AND A.CMMNS_CD_VALUE = B.CMMNS_CD_VALUE CROSS JOIN ( SELECT '0T' AS SXDC_CD , '합계' AS SXDC_NM FROM DUAL UNION ALL SELECT CMMNS_CD_VALUE AS SXDC_CD , CMMNS_CD_VALUE_NM AS SXDC_NM FROM SAC100 WHERE CMMNS_CD_ID = 'SXDC_SE_CD' ) B WHERE A.CMMNS_CD_ID = 'FCLTY_TYPE_SE_CD' AND A.USE_YN = 'Y' AND B.UNT_TASKWK_SE_CD = 'U04' ORDER BY SCN_CD, SXDC_CD ) A LEFT JOIN ( SELECT '0T' AS SXDC_CD , FCLTY_TYPE_SE_CD /*전체 사례관리 인원수*/ , COUNT(CASE WHEN CASE_BGNG_YMD < SRT_DT AND (CASE_TRMN_YMD > END_DT OR CASE_TRMN_YMD IS NULL) THEN TRPR_INFO_NO END) AS ALL_CASE_MNG_ENTRNC , COUNT(CASE WHEN CASE_BGNG_YMD BETWEEN SRT_DT AND END_DT AND (CASE_TRMN_YMD > END_DT OR CASE_TRMN_YMD IS NULL) THEN TRPR_INFO_NO END) AS ALL_CASE_MNG_NEW_ENTRNC , COUNT(CASE WHEN CASE_TRMN_YMD BETWEEN SRT_DT AND END_DT AND CASE_BGNG_YMD < SRT_DT THEN TRPR_INFO_NO END) AS ALL_CASE_MNG_LVNG , COUNT(CASE WHEN (CASE_BGNG_YMD BETWEEN SRT_DT AND END_DT) AND (CASE_TRMN_YMD BETWEEN SRT_DT AND END_DT) THEN TRPR_INFO_NO END) AS ALL_CASE_MNG_ENTRNC_LVNG , COUNT(CASE WHEN CASE_TRMN_YMD <= END_DT AND (AFTFCT_TRMN_YMD > END_DT OR AFTFCT_TRMN_YMD IS NULL) THEN TRPR_INFO_NO END) AS ALL_CASE_MNG_AFTFCT_MNG , COUNT(CASE WHEN AFTFCT_TRMN_YMD BETWEEN SRT_DT AND END_DT THEN TRPR_INFO_NO END) AS ALL_CASE_MNG_AFTFCT_TRMN /*실 사례관리 인원수*/ , COUNT(DISTINCT CASE WHEN CASE_BGNG_YMD < SRT_DT AND (CASE_TRMN_YMD > END_DT OR CASE_TRMN_YMD IS NULL) THEN NVL(INDV_IDNTFC_NO, TRPR_INFO_NO) END) AS REAL_CASE_MNG_ENTRNC , COUNT(DISTINCT CASE WHEN CASE_BGNG_YMD BETWEEN SRT_DT AND END_DT AND (CASE_TRMN_YMD > END_DT OR CASE_TRMN_YMD IS NULL) THEN NVL(INDV_IDNTFC_NO, TRPR_INFO_NO) END) AS REAL_CASE_MNG_NEW_ENTRNC , COUNT(DISTINCT CASE WHEN CASE_TRMN_YMD BETWEEN SRT_DT AND END_DT AND CASE_BGNG_YMD < SRT_DT THEN NVL(INDV_IDNTFC_NO, TRPR_INFO_NO) END) AS REAL_CASE_MNG_LVNG , COUNT(DISTINCT CASE WHEN CASE_BGNG_YMD BETWEEN SRT_DT AND END_DT AND CASE_TRMN_YMD BETWEEN SRT_DT AND END_DT THEN NVL(INDV_IDNTFC_NO, TRPR_INFO_NO) END) AS REAL_CASE_MNG_ENTRNC_LVNG , COUNT(DISTINCT CASE WHEN CASE_TRMN_YMD <= END_DT AND (AFTFCT_TRMN_YMD > END_DT OR AFTFCT_TRMN_YMD IS NULL) THEN NVL(INDV_IDNTFC_NO, TRPR_INFO_NO) END) AS REAL_CASE_MNG_AFTFCT_MNG , COUNT(DISTINCT CASE WHEN AFTFCT_TRMN_YMD BETWEEN SRT_DT AND END_DT THEN NVL(INDV_IDNTFC_NO, TRPR_INFO_NO) END) AS REAL_CASE_MNG_AFTFCT_TRMN /*이용청소년(연인원)*/ , SUM(CASE WHEN CASE_BGNG_YMD < SRT_DT AND (CASE_TRMN_YMD > END_DT OR CASE_TRMN_YMD IS NULL) THEN USE_NMPR END) AS UTZTN_YNGBGS_ENTRNC , SUM(CASE WHEN CASE_BGNG_YMD BETWEEN SRT_DT AND END_DT AND (CASE_TRMN_YMD > END_DT OR CASE_TRMN_YMD IS NULL) THEN USE_NMPR END) AS UTZTN_YNGBGS_NEW_ENTRNC , SUM(CASE WHEN CASE_TRMN_YMD BETWEEN SRT_DT AND END_DT AND CASE_BGNG_YMD < SRT_DT THEN USE_NMPR END) AS UTZTN_YNGBGS_LVNG , SUM(CASE WHEN CASE_BGNG_YMD BETWEEN SRT_DT AND END_DT AND CASE_TRMN_YMD BETWEEN SRT_DT AND END_DT THEN USE_NMPR END) AS UTZTN_YNGBGS_ENTRNC_LVNG FROM X GROUP BY FCLTY_TYPE_SE_CD UNION ALL SELECT SXDC_SE_CD AS SXDC_CD , FCLTY_TYPE_SE_CD /*전체 사례관리 인원수*/ , COUNT(CASE WHEN CASE_BGNG_YMD < SRT_DT AND (CASE_TRMN_YMD > END_DT OR CASE_TRMN_YMD IS NULL) THEN TRPR_INFO_NO END) AS 입소중 , COUNT(CASE WHEN CASE_BGNG_YMD BETWEEN SRT_DT AND END_DT AND (CASE_TRMN_YMD > END_DT OR CASE_TRMN_YMD IS NULL) THEN TRPR_INFO_NO END) AS 신규입소 , COUNT(CASE WHEN CASE_TRMN_YMD BETWEEN SRT_DT AND END_DT AND CASE_BGNG_YMD < SRT_DT THEN TRPR_INFO_NO END) AS 퇴소 , COUNT(CASE WHEN (CASE_BGNG_YMD BETWEEN SRT_DT AND END_DT) AND (CASE_TRMN_YMD BETWEEN SRT_DT AND END_DT) THEN TRPR_INFO_NO END) AS 조회기간중입퇴소 , COUNT(CASE WHEN CASE_TRMN_YMD <= END_DT AND (AFTFCT_TRMN_YMD > END_DT OR AFTFCT_TRMN_YMD IS NULL) THEN TRPR_INFO_NO END) AS 사후관리중 , COUNT(CASE WHEN AFTFCT_TRMN_YMD BETWEEN SRT_DT AND END_DT THEN TRPR_INFO_NO END) AS 사후종결 /*실 사례관리 인원수*/ , COUNT(DISTINCT CASE WHEN CASE_BGNG_YMD < SRT_DT AND (CASE_TRMN_YMD > END_DT OR CASE_TRMN_YMD IS NULL) THEN NVL(INDV_IDNTFC_NO, TRPR_INFO_NO) END) AS 입소중 , COUNT(DISTINCT CASE WHEN CASE_BGNG_YMD BETWEEN SRT_DT AND END_DT AND (CASE_TRMN_YMD > END_DT OR CASE_TRMN_YMD IS NULL) THEN NVL(INDV_IDNTFC_NO, TRPR_INFO_NO) END) AS 신규입소 , COUNT(DISTINCT CASE WHEN CASE_TRMN_YMD BETWEEN SRT_DT AND END_DT AND CASE_BGNG_YMD < SRT_DT THEN NVL(INDV_IDNTFC_NO, TRPR_INFO_NO) END) AS 퇴소 , COUNT(DISTINCT CASE WHEN CASE_BGNG_YMD BETWEEN SRT_DT AND END_DT AND CASE_TRMN_YMD BETWEEN SRT_DT AND END_DT THEN NVL(INDV_IDNTFC_NO, TRPR_INFO_NO) END) AS 조회기간중입퇴소 , COUNT(DISTINCT CASE WHEN CASE_TRMN_YMD <= END_DT AND (AFTFCT_TRMN_YMD > END_DT OR AFTFCT_TRMN_YMD IS NULL) THEN NVL(INDV_IDNTFC_NO, TRPR_INFO_NO) END) AS 사후관리중 , COUNT(DISTINCT CASE WHEN AFTFCT_TRMN_YMD BETWEEN SRT_DT AND END_DT THEN NVL(INDV_IDNTFC_NO, TRPR_INFO_NO) END) AS 사후종결 /*이용청소년(연인원)*/ , SUM(CASE WHEN CASE_BGNG_YMD < SRT_DT AND (CASE_TRMN_YMD > END_DT OR CASE_TRMN_YMD IS NULL) THEN USE_NMPR END) AS 입소중 , SUM(CASE WHEN CASE_BGNG_YMD BETWEEN SRT_DT AND END_DT AND (CASE_TRMN_YMD > END_DT OR CASE_TRMN_YMD IS NULL) THEN USE_NMPR END) AS 신규입소 , SUM(CASE WHEN CASE_TRMN_YMD BETWEEN SRT_DT AND END_DT AND CASE_BGNG_YMD < SRT_DT THEN USE_NMPR END) AS 퇴소 , SUM(CASE WHEN CASE_BGNG_YMD BETWEEN SRT_DT AND END_DT AND CASE_TRMN_YMD BETWEEN SRT_DT AND END_DT THEN USE_NMPR END) AS 조회기간중입퇴소 FROM X GROUP BY SXDC_SE_CD, FCLTY_TYPE_SE_CD ) B ON A.SXDC_CD = B.SXDC_CD AND A.SCN_CD = B.FCLTY_TYPE_SE_CD
ORDER BY CASE WHEN A.SCN_CD = '01' THEN 2 WHEN A.SCN_CD = '02' THEN 1 WHEN A.SCN_CD = '03' THEN 3 WHEN A.SCN_CD = '04' THEN 4 END , CASE WHEN A.SXDC_CD = '0T' THEN 1 WHEN A.SXDC_CD = 'M' THEN 2 WHEN A.SXDC_CD = 'F' THEN 3 WHEN A.SXDC_CD = 'X' THEN 4 END

/*isry.itgcm.fdrmrptstats.mapper.FdrmRptStatsMapper 입퇴소 사례지원(성별) - selectEntrncLvngCaseMngSxdc*/ WITH X AS ( SELECT A.CASE_PRGRS_STTS_SE_CD --사례진행상태구분코드 , B.TRPR_INFO_NO --대상자정보번호 , A.CASE_MNG_NO , B.INDV_IDNTFC_NO , A.AFTFCT_MNG_YN --사후관리여부 , A.CASE_BGNG_YMD --사례시작일자 , A.CASE_TRMN_YMD --사례종결일자 , B.SXDC_SE_CD --성별구분 , C.AFTFCT_TRMN_YMD --사후종결일자 , A.AFTFCT_MNG_YN AS AFTFCT_YN --사후관리여부 , TO_DATE('20230101' || '000000', 'YYYYMMDDHH24MISS') AS SRT_DT --검색조건시작 , TO_DATE('20231231' || '235959', 'YYYYMMDDHH24MISS') AS END_DT --검색조건종료 , ROUND(CASE WHEN TO_DATE('20231231' || '235959', 'YYYYMMDDHH24MISS') <= NVL(TO_DATE(CASE_TRMN_YMD, 'YYYYMMDDHH24MISS'), TO_DATE('20231231' || '235959', 'YYYYMMDDHH24MISS')) THEN TO_DATE('20231231' || '235959', 'YYYYMMDDHH24MISS') ELSE TO_DATE(CASE_TRMN_YMD || '235959', 'YYYYMMDDHH24MISS') END - CASE WHEN TO_DATE(TO_CHAR(A.CASE_BGNG_YMD || '000000'), 'YYYYMMDDHH24MISS') < TO_DATE('20230101' || '000000', 'YYYYMMDDHH24MISS') THEN TO_DATE('20230101' || '000000', 'YYYYMMDDHH24MISS') ELSE TO_DATE(TO_CHAR(A.CASE_BGNG_YMD || '000000'), 'YYYYMMDDHH24MISS') END) + 1 AS USE_NMPR FROM SEB100 A JOIN SEA200 B ON A.TRPR_INFO_NO = B.TRPR_INFO_NO LEFT JOIN SEC320 C ON A.CASE_MNG_NO = C.CASE_MNG_NO AND A.CASE_MNG_ODRNO = C.CASE_MNG_ODRNO LEFT JOIN SEB150 F0 /*사례담당자*/ ON F0.PCHPRS_YN = 'Y' AND F0.CASE_MNG_NO = A.CASE_MNG_NO AND F0.CASE_MNG_ODRNO = A.CASE_MNG_ODRNO LEFT JOIN SAA000 F3 /*통합기관*/ ON F3.INST_NO = F0.PIC_INST_NO LEFT JOIN SEB120 D ON A.CASE_MNG_NO = D.CASE_MNG_NO AND A.CASE_MNG_ODRNO = D.CASE_MNG_ODRNO AND D.DEL_YN = 'N' LEFT JOIN SDA420 E /*서비스실행사업*/ ON E.SRVC_EXCN_BIZ_NO = D.SRVC_EXCN_BIZ_NO LEFT JOIN SDA400 F /*서비스사업*/ ON E.SRVC_BIZ_NO = F.SRVC_BIZ_NO LEFT JOIN SDA430 G /*실행서비스사업*/ ON F.BIZ_YR = G.BIZ_YR AND F.SRVC_BIZ_NM = G.SRVC_BIZ_NM AND G.UNT_TASKWK_SE_CD = #{UNT_TASKWK_SE_CD}
WHERE 1=1 AND A.UNT_TASKWK_SE_CD = #{UNT_TASKWK_SE_CD}
/*시도코드*/ AND F3.CTPV_CD = #{CTPV_CD}
/*시군구코드*/ AND F3.SGG_CD = #{SGG_CD}
/*기관번호*/ AND F3.INST_NO = #{INST_NO}
/*서비스사업분류구분코드*/ AND F.BIZ_CL_SE_CD = #{SRVC_BIZ_CL}
/*실행사업분류구분코드*/ AND G.BIZ_CL_SE_CD = #{EXCN_SRVC_BIZ_CL}
/* 권한적용 별개로 해야함(자기기관 + 하위기관) */
) SELECT A.SCN_CD AS SXDC_SE_CD /*구분*/ , A.SCN_NM AS SXDC_SE_CD_NM /*구분*/ , NVL(B.ALL_CASE_MNG_ENTRNC, 0) + NVL(B.ALL_CASE_MNG_NEW_ENTRNC, 0) + NVL(B.ALL_CASE_MNG_LVNG, 0) + NVL(B.ALL_CASE_MNG_ENTRNC_LVNG, 0) + NVL(B.ALL_CASE_MNG_AFTFCT_MNG, 0) + NVL(B.ALL_CASE_MNG_AFTFCT_TRMN, 0) AS ALL_CASE_MNG_SUM /*전체사례 계*/ , NVL(B.ALL_CASE_MNG_ENTRNC, 0) AS ALL_CASE_MNG_ENTRNC /*전체사례 입소중*/ , NVL(B.ALL_CASE_MNG_NEW_ENTRNC, 0) AS ALL_CASE_MNG_NEW_ENTRNC /*전체사례 신규입소*/ , NVL(B.ALL_CASE_MNG_LVNG, 0) AS ALL_CASE_MNG_LVNG /*전체사례 퇴소*/ , NVL(B.ALL_CASE_MNG_ENTRNC_LVNG, 0) AS ALL_CASE_MNG_ENTRNC_LVNG /*전체사례 입퇴소*/ , NVL(B.ALL_CASE_MNG_AFTFCT_MNG, 0) AS ALL_CASE_MNG_AFTFCT_MNG /*전체사례 사후관리중*/ , NVL(B.ALL_CASE_MNG_AFTFCT_TRMN, 0) AS ALL_CASE_MNG_AFTFCT_TRMN /*전체사례 사후종결*/ , NVL(B.REAL_CASE_MNG_ENTRNC, 0) + NVL(B.REAL_CASE_MNG_NEW_ENTRNC, 0) + NVL(B.REAL_CASE_MNG_LVNG, 0) + NVL(B.REAL_CASE_MNG_ENTRNC_LVNG, 0) + NVL(B.REAL_CASE_MNG_AFTFCT_MNG, 0) + NVL(B.REAL_CASE_MNG_AFTFCT_TRMN, 0) AS REAL_CASE_MNG_SUM /*실사례 계*/ , NVL(B.REAL_CASE_MNG_ENTRNC, 0) AS REAL_CASE_MNG_ENTRNC /*실사례 입소중*/ , NVL(B.REAL_CASE_MNG_NEW_ENTRNC, 0) AS REAL_CASE_MNG_NEW_ENTRNC /*실사례 신규입소*/ , NVL(B.REAL_CASE_MNG_LVNG, 0) AS REAL_CASE_MNG_LVNG /*실사례 퇴소*/ , NVL(B.REAL_CASE_MNG_ENTRNC_LVNG, 0) AS REAL_CASE_MNG_ENTRNC_LVNG /*실사례 입퇴소*/ , NVL(B.REAL_CASE_MNG_AFTFCT_MNG, 0) AS REAL_CASE_MNG_AFTFCT_MNG /*실사례 사후관리중*/ , NVL(B.REAL_CASE_MNG_AFTFCT_TRMN, 0) AS REAL_CASE_MNG_AFTFCT_TRMN /*실사례 사후종결*/ , NVL(B.UTZTN_YNGBGS_ENTRNC, 0) + NVL(B.UTZTN_YNGBGS_NEW_ENTRNC, 0) + NVL(B.UTZTN_YNGBGS_LVNG, 0) + NVL(B.UTZTN_YNGBGS_ENTRNC_LVNG, 0) AS UTZTN_YNGBGS_SUM /*이용청소년 계*/ , NVL(B.UTZTN_YNGBGS_ENTRNC, 0) AS UTZTN_YNGBGS_ENTRNC /*이용청소년 입소중*/ , NVL(B.UTZTN_YNGBGS_NEW_ENTRNC, 0) AS UTZTN_YNGBGS_NEW_ENTRNC /*이용청소년 신규입소*/ , NVL(B.UTZTN_YNGBGS_LVNG, 0) AS UTZTN_YNGBGS_LVNG /*이용청소년 퇴소*/ , NVL(B.UTZTN_YNGBGS_ENTRNC_LVNG, 0) AS UTZTN_YNGBGS_ENTRNC_LVNG /*이용청소년 입퇴소*/ FROM ( SELECT '00' AS SCN_CD , '합계' AS SCN_NM FROM DUAL UNION ALL SELECT CMMNS_CD_VALUE AS SCN_CD , CMMNS_CD_VALUE_NM AS SCN_NM FROM SAC100 WHERE CMMNS_CD_ID = 'SXDC_SE_CD'
AND CMMNS_CD_VALUE NOT IN ('X')
) A LEFT JOIN ( /*전체*/ SELECT '00' AS SXDC_SE_CD /*전체사례 -이용*/ , COUNT(CASE WHEN CASE_BGNG_YMD < SRT_DT AND (CASE_TRMN_YMD > END_DT OR CASE_TRMN_YMD IS NULL) THEN TRPR_INFO_NO END) AS ALL_CASE_MNG_ENTRNC , COUNT(CASE WHEN CASE_BGNG_YMD BETWEEN SRT_DT AND END_DT AND (CASE_TRMN_YMD > END_DT OR CASE_TRMN_YMD IS NULL) THEN TRPR_INFO_NO END) AS ALL_CASE_MNG_NEW_ENTRNC , COUNT(CASE WHEN CASE_TRMN_YMD BETWEEN SRT_DT AND END_DT AND CASE_BGNG_YMD < SRT_DT THEN TRPR_INFO_NO END) AS ALL_CASE_MNG_LVNG , COUNT(CASE WHEN CASE_BGNG_YMD BETWEEN SRT_DT AND END_DT AND CASE_TRMN_YMD BETWEEN SRT_DT AND END_DT THEN TRPR_INFO_NO END) AS ALL_CASE_MNG_ENTRNC_LVNG
/*전체사례 -사후관리*/ , COUNT(CASE WHEN CASE_TRMN_YMD <= END_DT AND (AFTFCT_TRMN_YMD > END_DT OR AFTFCT_TRMN_YMD IS NULL) THEN TRPR_INFO_NO END) AS ALL_CASE_MNG_AFTFCT_MNG , COUNT(CASE WHEN AFTFCT_TRMN_YMD BETWEEN SRT_DT AND END_DT THEN TRPR_INFO_NO END) AS ALL_CASE_MNG_AFTFCT_TRMN
/*실사례 -이용*/ , COUNT(DISTINCT CASE WHEN CASE_BGNG_YMD < SRT_DT AND (CASE_TRMN_YMD > END_DT OR CASE_TRMN_YMD IS NULL) THEN TRPR_INFO_NO END) AS REAL_CASE_MNG_ENTRNC , COUNT(DISTINCT CASE WHEN CASE_BGNG_YMD BETWEEN SRT_DT AND END_DT AND (CASE_TRMN_YMD > END_DT OR CASE_TRMN_YMD IS NULL) THEN TRPR_INFO_NO END) AS REAL_CASE_MNG_NEW_ENTRNC , COUNT(DISTINCT CASE WHEN CASE_TRMN_YMD BETWEEN SRT_DT AND END_DT AND CASE_BGNG_YMD < SRT_DT THEN TRPR_INFO_NO END) AS REAL_CASE_MNG_LVNG , COUNT(DISTINCT CASE WHEN CASE_BGNG_YMD BETWEEN SRT_DT AND END_DT AND CASE_TRMN_YMD BETWEEN SRT_DT AND END_DT THEN TRPR_INFO_NO END) AS REAL_CASE_MNG_ENTRNC_LVNG
/*전체사례 -사후관리*/ , COUNT(DISTINCT CASE WHEN CASE_TRMN_YMD <= END_DT AND (AFTFCT_TRMN_YMD > END_DT OR AFTFCT_TRMN_YMD IS NULL) THEN TRPR_INFO_NO END) AS REAL_CASE_MNG_AFTFCT_MNG , COUNT(DISTINCT CASE WHEN AFTFCT_TRMN_YMD BETWEEN SRT_DT AND END_DT THEN TRPR_INFO_NO END) AS REAL_CASE_MNG_AFTFCT_TRMN
/*이용청소년*/ , SUM(CASE WHEN CASE_BGNG_YMD < SRT_DT AND (CASE_TRMN_YMD > END_DT OR CASE_TRMN_YMD IS NULL) THEN USE_NMPR END) AS UTZTN_YNGBGS_ENTRNC , SUM(CASE WHEN CASE_BGNG_YMD BETWEEN SRT_DT AND END_DT AND (CASE_TRMN_YMD > END_DT OR CASE_TRMN_YMD IS NULL) THEN USE_NMPR END) AS UTZTN_YNGBGS_NEW_ENTRNC , SUM(CASE WHEN CASE_TRMN_YMD BETWEEN SRT_DT AND END_DT AND CASE_BGNG_YMD < SRT_DT THEN USE_NMPR END) AS UTZTN_YNGBGS_LVNG , SUM(CASE WHEN CASE_BGNG_YMD BETWEEN SRT_DT AND END_DT AND CASE_TRMN_YMD BETWEEN SRT_DT AND END_DT THEN USE_NMPR END) AS UTZTN_YNGBGS_ENTRNC_LVNG FROM X UNION ALL /*통계*/ SELECT SXDC_SE_CD /*전체사례 -이용*/ , COUNT(CASE WHEN CASE_BGNG_YMD < SRT_DT AND (CASE_TRMN_YMD > END_DT OR CASE_TRMN_YMD IS NULL) THEN TRPR_INFO_NO END) AS ALL_CASE_MNG_ENTRNC , COUNT(CASE WHEN CASE_BGNG_YMD BETWEEN SRT_DT AND END_DT AND (CASE_TRMN_YMD > END_DT OR CASE_TRMN_YMD IS NULL) THEN TRPR_INFO_NO END) AS ALL_CASE_MNG_NEW_ENTRNC , COUNT(CASE WHEN CASE_TRMN_YMD BETWEEN SRT_DT AND END_DT AND CASE_BGNG_YMD < SRT_DT THEN TRPR_INFO_NO END) AS ALL_CASE_MNG_LVNG , COUNT(CASE WHEN CASE_BGNG_YMD BETWEEN SRT_DT AND END_DT AND CASE_TRMN_YMD BETWEEN SRT_DT AND END_DT THEN TRPR_INFO_NO END) AS ALL_CASE_MNG_ENTRNC_LVNG
/*전체사례 -사후관리*/ , COUNT(CASE WHEN CASE_TRMN_YMD <= END_DT AND (AFTFCT_TRMN_YMD > END_DT OR AFTFCT_TRMN_YMD IS NULL) THEN TRPR_INFO_NO END) AS ALL_CASE_MNG_AFTFCT_MNG , COUNT(CASE WHEN AFTFCT_TRMN_YMD BETWEEN SRT_DT AND END_DT THEN TRPR_INFO_NO END) AS ALL_CASE_MNG_AFTFCT_TRMN
/*실사례 -이용*/ , COUNT(DISTINCT CASE WHEN CASE_BGNG_YMD < SRT_DT AND (CASE_TRMN_YMD > END_DT OR CASE_TRMN_YMD IS NULL) THEN TRPR_INFO_NO END) AS REAL_CASE_MNG_ENTRNC , COUNT(DISTINCT CASE WHEN CASE_BGNG_YMD BETWEEN SRT_DT AND END_DT AND (CASE_TRMN_YMD > END_DT OR CASE_TRMN_YMD IS NULL) THEN TRPR_INFO_NO END) AS REAL_CASE_MNG_NEW_ENTRNC , COUNT(DISTINCT CASE WHEN CASE_TRMN_YMD BETWEEN SRT_DT AND END_DT AND CASE_BGNG_YMD < SRT_DT THEN TRPR_INFO_NO END) AS REAL_CASE_MNG_LVNG , COUNT(DISTINCT CASE WHEN CASE_BGNG_YMD BETWEEN SRT_DT AND END_DT AND CASE_TRMN_YMD BETWEEN SRT_DT AND END_DT THEN TRPR_INFO_NO END) AS REAL_CASE_MNG_ENTRNC_LVNG
/*전체사례 -사후관리*/ , COUNT(DISTINCT CASE WHEN CASE_TRMN_YMD <= END_DT AND (AFTFCT_TRMN_YMD > END_DT OR AFTFCT_TRMN_YMD IS NULL) THEN TRPR_INFO_NO END) AS REAL_CASE_MNG_AFTFCT_MNG , COUNT(DISTINCT CASE WHEN AFTFCT_TRMN_YMD BETWEEN SRT_DT AND END_DT THEN TRPR_INFO_NO END) AS REAL_CASE_MNG_AFTFCT_TRMN
/*이용청소년*/ , SUM(CASE WHEN CASE_BGNG_YMD < SRT_DT AND (CASE_TRMN_YMD > END_DT OR CASE_TRMN_YMD IS NULL) THEN USE_NMPR END) AS UTZTN_YNGBGS_ENTRNC , SUM(CASE WHEN CASE_BGNG_YMD BETWEEN SRT_DT AND END_DT AND (CASE_TRMN_YMD > END_DT OR CASE_TRMN_YMD IS NULL) THEN USE_NMPR END) AS UTZTN_YNGBGS_NEW_ENTRNC , SUM(CASE WHEN CASE_TRMN_YMD BETWEEN SRT_DT AND END_DT AND CASE_BGNG_YMD < SRT_DT THEN USE_NMPR END) AS UTZTN_YNGBGS_LVNG , SUM(CASE WHEN CASE_BGNG_YMD BETWEEN SRT_DT AND END_DT AND CASE_TRMN_YMD BETWEEN SRT_DT AND END_DT THEN USE_NMPR END) AS UTZTN_YNGBGS_ENTRNC_LVNG FROM X GROUP BY SXDC_SE_CD ) B ON A.SCN_CD = B.SXDC_SE_CD ORDER BY CASE WHEN A.SCN_CD = '00' THEN 1 WHEN A.SCN_CD = 'M' THEN 2 WHEN A.SCN_CD = 'F' THEN 3 WHEN A.SCN_CD = 'X' THEN 4 END

/*isry.itgcm.fdrmrptstats.mapper.FdrmRptStatsMapper 퇴소후 자립현황(쉼터별) - selectPstrtrSrlstSheltrType LEE.SEOUNG.JAE*/ WITH TMP AS( SELECT D.PSTRTR_SLFRL_SE_CD , D.PSTRTR_SLFRL_DTL_SE_CD , B.SHELTR_TRPR_SE_CD , C.SXDC_SE_CD , G.FCLTY_TYPE_SE_CD , A.CASE_MNG_NO , A.CASE_MNG_ODRNO , C.TRPR_INFO_NO FROM SEB100 A JOIN AEA100 B ON B.CASE_MNG_NO = A.CASE_MNG_NO AND B.CASE_MNG_ODRNO = A.CASE_MNG_ODRNO JOIN SEA200 C ON A.TRPR_INFO_NO = C.TRPR_INFO_NO JOIN AEA130 D ON D.CASE_MNG_NO = A.CASE_MNG_NO AND D.CASE_MNG_ODRNO = A.CASE_MNG_ODRNO JOIN SEB150 E ON A.CASE_MNG_NO = E.CASE_MNG_NO AND A.CASE_MNG_ODRNO = E.CASE_MNG_ODRNO AND E.PCHPRS_YN = 'Y' JOIN SAA000 F ON F.INST_NO = E.PIC_INST_NO JOIN AKA500 G ON G.INST_NO = F.INST_NO WHERE A.UNT_TASKWK_SE_CD = #{UNT_TASKWK_SE_CD} -- 기간구분 AND A.CASE_TRMN_YMD BETWEEN #{SRT_DT} AND #{END_DT} AND C.DEL_YN = 'N' AND B.SHELTR_TRPR_SE_CD IN ('1','2') AND G.FCLTY_TYPE_SE_CD IS NOT NULL
-- 시도코드 AND F.CTPV_CD = #{CTPV_CD}
-- 시군구코드 AND F.SGG_CD = #{SGG_CD}
-- 기관번호 AND F.INST_NO = #{INST_NO}
-- 사업분류구분코드 AND #{SRVC_BIZ_CL} IN ( SELECT SRVC_BIZ_CL_SE_CD FROM SEB120 AA JOIN SDA420 BB ON BB.SRVC_EXCN_BIZ_NO = AA.SRVC_EXCN_BIZ_NO JOIN SDA400 CC ON CC.SRVC_BIZ_NO = BB.SRVC_BIZ_NO WHERE AA.DEL_YN = 'N' AND AA.CASE_MNG_NO = A.CASE_MNG_NO AND AA.CASE_MNG_ODRNO = A.CASE_MNG_ODRNO )
-- 사업분류구분코드 AND #{EXCN_SRVC_BIZ_CL} IN ( SELECT SRVC_BIZ_CL_SE_CD FROM SEB120 AA JOIN SDA420 BB ON BB.SRVC_EXCN_BIZ_NO = AA.SRVC_EXCN_BIZ_NO JOIN SDA400 CC ON CC.SRVC_BIZ_NO = BB.SRVC_BIZ_NO WHERE AA.DEL_YN = 'N' AND AA.CASE_MNG_NO = A.CASE_MNG_NO AND AA.CASE_MNG_ODRNO = A.CASE_MNG_ODRNO )
#{instNo}
)
SELECT PSTRTR_SLFRL_SE_CD , PSTRTR_SLFRL_DTL_SE_CD , SXDC_SE_CD , FCLTY_TYPE_SE_CD , CASE WHEN SXDC_SE_CD = 'A' THEN '합계' ELSE B.CMMNS_CD_VALUE_NM END AS SXDC_SE_CD_NM , CASE WHEN FCLTY_TYPE_SE_CD = '00' THEN '합계' ELSE C.CMMNS_CD_VALUE_NM END AS FCLTY_TYPE_SE_CD_NM , NOPE FROM ( SELECT CASE GROUPING(A.PSTRTR_SLFRL_SE_CD) WHEN 1 THEN '00' ELSE A.PSTRTR_SLFRL_SE_CD END AS PSTRTR_SLFRL_SE_CD , CASE GROUPING(A.PSTRTR_SLFRL_DTL_SE_CD) WHEN 1 THEN '00' ELSE A.PSTRTR_SLFRL_DTL_SE_CD END AS PSTRTR_SLFRL_DTL_SE_CD , CASE GROUPING(A.SXDC_SE_CD) WHEN 1 THEN 'A' ELSE A.SXDC_SE_CD END AS SXDC_SE_CD , CASE GROUPING(A.FCLTY_TYPE_SE_CD) WHEN 1 THEN '00' ELSE A.FCLTY_TYPE_SE_CD END AS FCLTY_TYPE_SE_CD , NVL(COUNT(TRPR_INFO_NO),0) AS NOPE FROM ( SELECT A.CMMNS_CD_VALUE AS FCLTY_TYPE_SE_CD , B.CMMNS_CD_VALUE AS SXDC_SE_CD , D.CMMNS_CD_VALUE AS PSTRTR_SLFRL_SE_CD , E.CMMNS_CD_VALUE AS PSTRTR_SLFRL_DTL_SE_CD FROM SAC100 A JOIN SAC110 C ON A.CMMNS_CD_ID = C.CMMNS_CD_ID AND A.CMMNS_CD_VALUE = C.CMMNS_CD_VALUE CROSS JOIN SAC100 B CROSS JOIN SAC100 D LEFT JOIN ( SELECT A.CMMNS_CD_VALUE AS UP_CMMNS_CD_VALUE , CASE WHEN A.CMMNS_CD_VALUE = '02' THEN B.CMMNS_CD_VALUE END AS CMMNS_CD_VALUE , CASE WHEN A.CMMNS_CD_VALUE = '02' THEN B.CMMNS_CD_VALUE_NM END AS CMMNS_CD_VALUE_NM FROM SAC100 A LEFT JOIN SAC100 B ON 1=1 WHERE A.CMMNS_CD_ID= 'PSTRTR_SLFRL_SE_CD' AND B.CMMNS_CD_ID = 'PSTRTR_SLFRL_DTL_SE_CD' AND A.CMMNS_CD_VALUE = '02' ) E ON E.UP_CMMNS_CD_VALUE = D.CMMNS_CD_VALUE
WHERE A.CMMNS_CD_ID = 'FCLTY_TYPE_SE_CD' AND B.CMMNS_CD_ID = 'SXDC_SE_CD' AND C.UNT_TASKWK_SE_CD = #{UNT_TASKWK_SE_CD} AND D.CMMNS_CD_ID = 'PSTRTR_SLFRL_SE_CD'
ORDER BY A.CMMNS_CD_VALUE, B.SRTNG_SQNCE, D.CMMNS_CD_VALUE, E.CMMNS_CD_VALUE ) A LEFT JOIN TMP B ON A.PSTRTR_SLFRL_SE_CD = B.PSTRTR_SLFRL_SE_CD AND A.SXDC_SE_CD = B.SXDC_SE_CD AND A.FCLTY_TYPE_SE_CD = B.FCLTY_TYPE_SE_CD AND (A.PSTRTR_SLFRL_DTL_SE_CD = B.PSTRTR_SLFRL_DTL_SE_CD OR B.PSTRTR_SLFRL_DTL_SE_CD IS NULL)
GROUP BY GROUPING SETS( (A.PSTRTR_SLFRL_SE_CD, A.SXDC_SE_CD, A.FCLTY_TYPE_SE_CD, A.PSTRTR_SLFRL_DTL_SE_CD) , (A.FCLTY_TYPE_SE_CD, A.SXDC_SE_CD) , (A.FCLTY_TYPE_SE_CD, A.PSTRTR_SLFRL_SE_CD, A.PSTRTR_SLFRL_DTL_SE_CD) , (A.FCLTY_TYPE_SE_CD) , (A.SXDC_SE_CD) , () , (A.SXDC_SE_CD, A.PSTRTR_SLFRL_SE_CD, A.PSTRTR_SLFRL_DTL_SE_CD) , (A.PSTRTR_SLFRL_SE_CD, A.PSTRTR_SLFRL_DTL_SE_CD) ) ORDER BY FCLTY_TYPE_SE_CD, SXDC_SE_CD ) A LEFT JOIN SAC100 B ON B.CMMNS_CD_ID = 'SXDC_SE_CD' AND B.CMMNS_CD_VALUE = A.SXDC_SE_CD LEFT JOIN SAC100 C ON C.CMMNS_CD_ID = 'FCLTY_TYPE_SE_CD' AND C.CMMNS_CD_VALUE = A.FCLTY_TYPE_SE_CD
ORDER BY CASE WHEN FCLTY_TYPE_SE_CD = '00' THEN 0 WHEN FCLTY_TYPE_SE_CD = '01' THEN 2 WHEN FCLTY_TYPE_SE_CD = '02' THEN 1 WHEN FCLTY_TYPE_SE_CD = '03' THEN 3 WHEN FCLTY_TYPE_SE_CD = '04' THEN 4 END , CASE WHEN SXDC_SE_CD = 'A' THEN 1 WHEN SXDC_SE_CD = 'M' THEN 2 WHEN SXDC_SE_CD = 'F' THEN 3 WHEN SXDC_SE_CD = 'X' THEN 4 END

/*isry.itgcm.fdrmrptstats.mapper.FdrmRptStatsMapper 퇴소후 자립현황(성별) - selectPstrtrSrlstSxdc - LEE.SEOUNG.JAE*/ WITH TMP AS( SELECT D.PSTRTR_SLFRL_SE_CD , D.PSTRTR_SLFRL_DTL_SE_CD , B.SLFRL_SPRT_TRPR_SE_CD , C.SXDC_SE_CD , A.CASE_MNG_NO , A.CASE_MNG_ODRNO , C.TRPR_INFO_NO FROM SEB100 A JOIN AEB120 B ON B.CASE_MNG_NO = A.CASE_MNG_NO AND B.CASE_MNG_ODRNO = A.CASE_MNG_ODRNO JOIN SEA200 C ON A.TRPR_INFO_NO = C.TRPR_INFO_NO JOIN AEA130 D ON D.CASE_MNG_NO = A.CASE_MNG_NO AND D.CASE_MNG_ODRNO = A.CASE_MNG_ODRNO JOIN SEB150 E ON A.CASE_MNG_NO = E.CASE_MNG_NO AND A.CASE_MNG_ODRNO = E.CASE_MNG_ODRNO AND E.PCHPRS_YN = 'Y' JOIN SAA000 F ON F.INST_NO = E.PIC_INST_NO WHERE A.UNT_TASKWK_SE_CD = #{UNT_TASKWK_SE_CD} -- 기간구분 AND A.CASE_TRMN_YMD BETWEEN #{SRT_DT} AND #{END_DT} AND C.DEL_YN = 'N' AND B.SLFRL_SPRT_TRPR_SE_CD IN ('1','2')
-- 시도코드 AND F.CTPV_CD = #{CTPV_CD}
-- 시군구코드 AND F.SGG_CD = #{SGG_CD}
-- 기관번호 AND F.INST_NO = #{INST_NO}
-- 사업분류구분코드 AND #{SRVC_BIZ_CL} IN ( SELECT SRVC_BIZ_CL_SE_CD FROM SEB120 AA JOIN SDA420 BB ON BB.SRVC_EXCN_BIZ_NO = AA.SRVC_EXCN_BIZ_NO JOIN SDA400 CC ON CC.SRVC_BIZ_NO = BB.SRVC_BIZ_NO WHERE AA.DEL_YN = 'N' AND AA.CASE_MNG_NO = A.CASE_MNG_NO AND AA.CASE_MNG_ODRNO = A.CASE_MNG_ODRNO )
-- 사업분류구분코드 AND #{EXCN_SRVC_BIZ_CL} IN ( SELECT SRVC_BIZ_CL_SE_CD FROM SEB120 AA JOIN SDA420 BB ON BB.SRVC_EXCN_BIZ_NO = AA.SRVC_EXCN_BIZ_NO JOIN SDA400 CC ON CC.SRVC_BIZ_NO = BB.SRVC_BIZ_NO WHERE AA.DEL_YN = 'N' AND AA.CASE_MNG_NO = A.CASE_MNG_NO AND AA.CASE_MNG_ODRNO = A.CASE_MNG_ODRNO )
#{instNo}
)
SELECT PSTRTR_SLFRL_SE_CD , PSTRTR_SLFRL_DTL_SE_CD , SXDC_SE_CD , CASE WHEN SXDC_SE_CD = 'A' THEN '합계' ELSE B.CMMNS_CD_VALUE_NM END AS SXDC_SE_CD_NM , NOPE FROM ( SELECT CASE GROUPING(A.PSTRTR_SLFRL_SE_CD) WHEN 1 THEN '00' ELSE A.PSTRTR_SLFRL_SE_CD END AS PSTRTR_SLFRL_SE_CD , CASE GROUPING(A.PSTRTR_SLFRL_DTL_SE_CD) WHEN 1 THEN '00' ELSE A.PSTRTR_SLFRL_DTL_SE_CD END AS PSTRTR_SLFRL_DTL_SE_CD , CASE GROUPING(A.SXDC_SE_CD) WHEN 1 THEN 'A' ELSE A.SXDC_SE_CD END AS SXDC_SE_CD , NVL(COUNT(TRPR_INFO_NO),0) AS NOPE FROM ( SELECT B.CMMNS_CD_VALUE AS SXDC_SE_CD , D.CMMNS_CD_VALUE AS PSTRTR_SLFRL_SE_CD , E.CMMNS_CD_VALUE AS PSTRTR_SLFRL_DTL_SE_CD FROM SAC100 B CROSS JOIN SAC100 D LEFT JOIN ( SELECT A.CMMNS_CD_VALUE AS UP_CMMNS_CD_VALUE , CASE WHEN A.CMMNS_CD_VALUE = '02' THEN B.CMMNS_CD_VALUE END AS CMMNS_CD_VALUE , CASE WHEN A.CMMNS_CD_VALUE = '02' THEN B.CMMNS_CD_VALUE_NM END AS CMMNS_CD_VALUE_NM FROM SAC100 A LEFT JOIN SAC100 B ON 1=1 WHERE A.CMMNS_CD_ID= 'PSTRTR_SLFRL_SE_CD' AND B.CMMNS_CD_ID = 'PSTRTR_SLFRL_DTL_SE_CD' AND A.CMMNS_CD_VALUE = '02' ) E ON E.UP_CMMNS_CD_VALUE = D.CMMNS_CD_VALUE
WHERE B.CMMNS_CD_ID = 'SXDC_SE_CD' AND D.CMMNS_CD_ID = 'PSTRTR_SLFRL_SE_CD'
ORDER BY B.SRTNG_SQNCE, D.CMMNS_CD_VALUE, E.CMMNS_CD_VALUE ) A LEFT JOIN TMP B ON A.PSTRTR_SLFRL_SE_CD = B.PSTRTR_SLFRL_SE_CD AND A.SXDC_SE_CD = B.SXDC_SE_CD AND (A.PSTRTR_SLFRL_DTL_SE_CD = B.PSTRTR_SLFRL_DTL_SE_CD OR B.PSTRTR_SLFRL_DTL_SE_CD IS NULL)
GROUP BY GROUPING SETS( (A.PSTRTR_SLFRL_SE_CD, A.SXDC_SE_CD, A.PSTRTR_SLFRL_DTL_SE_CD) , (A.SXDC_SE_CD) , (A.PSTRTR_SLFRL_SE_CD, A.PSTRTR_SLFRL_DTL_SE_CD) , (A.SXDC_SE_CD) , () , (A.SXDC_SE_CD, A.PSTRTR_SLFRL_SE_CD, A.PSTRTR_SLFRL_DTL_SE_CD) , (A.PSTRTR_SLFRL_SE_CD, A.PSTRTR_SLFRL_DTL_SE_CD) ) ORDER BY SXDC_SE_CD ) A LEFT JOIN SAC100 B ON B.CMMNS_CD_ID = 'SXDC_SE_CD' AND B.CMMNS_CD_VALUE = A.SXDC_SE_CD
ORDER BY CASE WHEN SXDC_SE_CD = 'A' THEN 1 WHEN SXDC_SE_CD = 'M' THEN 2 WHEN SXDC_SE_CD = 'F' THEN 3 WHEN SXDC_SE_CD = 'X' THEN 4 END

/*isry.itgcm.fdrmrptstats.mapper.FdrmRptStatsMapper - selectAftfctSprtSrvcSheltrType[사후지원서비스(쉼터유형별)] : Lee SangHoon*/
SELECT NVL(T1.FCLTY_TYPE_SE_CD,'00') AS FCLTY_TYPE_SE_CD --시설유형구분코드 , NVL(T1.FCLTY_TYPE_SE_CD_NM,'합계') AS FCLTY_TYPE_SE_CD_NM --시설유형구분코드명 , NVL(T2.SXDC_SE_CD_NM,'합계') AS SXDC_SE_CD_NM --성별구분코드명 , NVL(T3.SRVC_RESRCE_LCLAS_SE_CD,'00') AS SRVC_RESRCE_LCLAS_SE_CD --서비스자원대분류구분코드 , NVL(SUM(T.NOPE),0) AS NOPE --인원수 , NVL(T2.SXDC_SRTNG_SQNCE,0) AS SXDC_SRTNG_SQNCE --성별코드순번 FROM (SELECT A.CMMNS_CD_VALUE AS FCLTY_TYPE_SE_CD --시설유형구분코드 , A.CMMNS_CD_VALUE_NM AS FCLTY_TYPE_SE_CD_NM --시설유형구분코드명 FROM SAC100 A /*공통코드 값*/ LEFT JOIN SAC110 B /*공통코드값 사용시스템*/ ON B.CMMNS_CD_ID = A.CMMNS_CD_ID AND B.CMMNS_CD_VALUE = A.CMMNS_CD_VALUE WHERE A.CMMNS_CD_ID = 'FCLTY_TYPE_SE_CD' AND (B.UNT_TASKWK_SE_CD = #{UNT_TASKWK_SE_CD} OR B.UNT_TASKWK_SE_CD IS NULL) ) T1 CROSS JOIN (SELECT A.CMMNS_CD_VALUE AS SXDC_SE_CD /*성별구분코드*/ , A.CMMNS_CD_VALUE_NM AS SXDC_SE_CD_NM /*성별구분코드명*/ , A.SRTNG_SQNCE AS SXDC_SRTNG_SQNCE /*성별코드순번*/ FROM SAC100 A /*공통코드 값*/ LEFT JOIN SAC110 B /*공통코드값 사용시스템*/ ON B.CMMNS_CD_ID = A.CMMNS_CD_ID AND B.CMMNS_CD_VALUE = A.CMMNS_CD_VALUE WHERE A.CMMNS_CD_ID = 'SXDC_SE_CD' AND (B.UNT_TASKWK_SE_CD = #{UNT_TASKWK_SE_CD} OR B.UNT_TASKWK_SE_CD IS NULL) ) T2 CROSS JOIN (SELECT A.CMMNS_CD_VALUE AS SRVC_RESRCE_LCLAS_SE_CD --서비스자원대분류구분코드 FROM SAC100 A /*공통코드 값*/ LEFT JOIN SAC110 B /*공통코드값 사용시스템*/ ON B.CMMNS_CD_ID = A.CMMNS_CD_ID AND B.CMMNS_CD_VALUE = A.CMMNS_CD_VALUE WHERE A.CMMNS_CD_ID = 'SRVC_RESRCE_LCLAS_SE_CD' AND (B.UNT_TASKWK_SE_CD = #{UNT_TASKWK_SE_CD} OR B.UNT_TASKWK_SE_CD IS NULL) ) T3 LEFT JOIN (SELECT E.FCLTY_TYPE_SE_CD --시설유형구분코드 , F.SXDC_SE_CD --성별구분코드 , B.SRVC_RESRCE_LCLAS_SE_CD --서비스자원대분류구분코드 , COUNT(A.CASE_MNG_NO) AS NOPE --인원수 FROM SEB100 A /*사례기본*/ JOIN SEC300 B /*사후관리*/ ON B.CASE_MNG_NO = A.CASE_MNG_NO AND B.CASE_MNG_ODRNO = A.CASE_MNG_ODRNO AND B.DEL_YN = 'N' JOIN SEC310 C /*사후관리담당자*/ ON C.AFTFCT_MNG_NO = B.AFTFCT_MNG_NO AND C.CASE_MNG_NO = B.CASE_MNG_NO AND C.CASE_MNG_ODRNO = B.CASE_MNG_ODRNO AND C.DEL_YN = 'N' AND C.PCHPRS_YN = 'Y' JOIN SAA000 D /*통합기관*/ ON D.INST_NO = C.PIC_INST_NO AND D.DEL_YN = 'N' JOIN AKA500 E /*센터현황*/ ON E.INST_NO = D.INST_NO JOIN SEA200 F /*대상자정보*/ ON F.TRPR_INFO_NO = A.TRPR_INFO_NO AND F.DEL_YN = 'N' WHERE B.AFTFCT_MNG_YMD BETWEEN #{SRT_DT} AND #{END_DT} AND A.UNT_TASKWK_SE_CD = #{UNT_TASKWK_SE_CD}
AND D.INST_NO = #{INST_NO}
AND D.CTPV_CD = #{CTPV_CD}
AND D.SGG_CD = #{SGG_CD}
AND #{SRVC_BIZ_CL} IN (SELECT AD3.BIZ_CL_SE_CD FROM SEB120 AD1 JOIN SDA420 AD2 ON AD2.SRVC_EXCN_BIZ_NO = AD1.SRVC_EXCN_BIZ_NO JOIN SDA400 AD3 ON AD3.SRVC_BIZ_NO = AD2.SRVC_BIZ_NO WHERE AD1.CASE_MNG_NO = A.CASE_MNG_NO AND AD1.CASE_MNG_ODRNO = A.CASE_MNG_ODRNO AND AD1.DEL_YN = 'N')
#{instNo}
GROUP BY E.FCLTY_TYPE_SE_CD, F.SXDC_SE_CD, B.SRVC_RESRCE_LCLAS_SE_CD ) T ON T.FCLTY_TYPE_SE_CD = T1.FCLTY_TYPE_SE_CD AND T.SXDC_SE_CD = T2.SXDC_SE_CD AND T.SRVC_RESRCE_LCLAS_SE_CD = T3.SRVC_RESRCE_LCLAS_SE_CD GROUP BY CUBE(T1.FCLTY_TYPE_SE_CD, T1.FCLTY_TYPE_SE_CD_NM, T2.SXDC_SE_CD_NM, T2.SXDC_SRTNG_SQNCE, T3.SRVC_RESRCE_LCLAS_SE_CD) HAVING GROUPING(T1.FCLTY_TYPE_SE_CD) = GROUPING(T1.FCLTY_TYPE_SE_CD_NM) AND GROUPING(T2.SXDC_SE_CD_NM) = GROUPING(T2.SXDC_SRTNG_SQNCE) ORDER BY CASE WHEN FCLTY_TYPE_SE_CD = '00' THEN 0 WHEN FCLTY_TYPE_SE_CD = '01' THEN 2 WHEN FCLTY_TYPE_SE_CD = '02' THEN 1 WHEN FCLTY_TYPE_SE_CD = '03' THEN 3 WHEN FCLTY_TYPE_SE_CD = '04' THEN 4 END, SXDC_SRTNG_SQNCE, SRVC_RESRCE_LCLAS_SE_CD

/*isry.itgcm.fdrmrptstats.mapper.FdrmRptStatsMapper - selectAftfctSprtSrvcSxdc[사후지원서비스(성별)] : Lee SangHoon*/
SELECT NVL(T1.SXDC_SE_CD,'T') AS SXDC_SE_CD --성별구분코드 , NVL(T1.SXDC_SE_CD_NM,'합계') AS SXDC_SE_CD_NM --성별구분코드명 , NVL(T2.SRVC_RESRCE_LCLAS_SE_CD,'00') AS SRVC_RESRCE_LCLAS_SE_CD --서비스자원대분류구분코드 , NVL(SUM(T.NOPE),0) AS NOPE --인원수 , NVL(T1.SXDC_SRTNG_SQNCE,0) AS SXDC_SRTNG_SQNCE --성별코드순번 FROM (SELECT A.CMMNS_CD_VALUE AS SXDC_SE_CD --성별구분코드 , A.CMMNS_CD_VALUE_NM AS SXDC_SE_CD_NM --성별구분코드명 , A.SRTNG_SQNCE AS SXDC_SRTNG_SQNCE --성별코드순번 FROM SAC100 A /*공통코드 값*/ LEFT JOIN SAC110 B /*공통코드값 사용시스템*/ ON B.CMMNS_CD_ID = A.CMMNS_CD_ID AND B.CMMNS_CD_VALUE = A.CMMNS_CD_VALUE WHERE A.CMMNS_CD_ID = 'SXDC_SE_CD' AND (B.UNT_TASKWK_SE_CD = #{UNT_TASKWK_SE_CD} OR B.UNT_TASKWK_SE_CD IS NULL) ) T1 CROSS JOIN (SELECT A.CMMNS_CD_VALUE AS SRVC_RESRCE_LCLAS_SE_CD --서비스자원대분류구분코드 FROM SAC100 A /*공통코드 값*/ LEFT JOIN SAC110 B /*공통코드값 사용시스템*/ ON B.CMMNS_CD_ID = A.CMMNS_CD_ID AND B.CMMNS_CD_VALUE = A.CMMNS_CD_VALUE WHERE A.CMMNS_CD_ID = 'SRVC_RESRCE_LCLAS_SE_CD' AND (B.UNT_TASKWK_SE_CD = #{UNT_TASKWK_SE_CD} OR B.UNT_TASKWK_SE_CD IS NULL) ) T2 LEFT JOIN (SELECT F.SXDC_SE_CD --성별구분코드 , B.SRVC_RESRCE_LCLAS_SE_CD --서비스자원대분류구분코드 , COUNT(A.CASE_MNG_NO) AS NOPE --인원수 FROM SEB100 A /*사례기본*/ JOIN SEC300 B /*사후관리*/ ON B.CASE_MNG_NO = A.CASE_MNG_NO AND B.CASE_MNG_ODRNO = A.CASE_MNG_ODRNO AND B.DEL_YN = 'N' JOIN SEC310 C /*사후관리담당자*/ ON C.AFTFCT_MNG_NO = B.AFTFCT_MNG_NO AND C.CASE_MNG_NO = B.CASE_MNG_NO AND C.CASE_MNG_ODRNO = B.CASE_MNG_ODRNO AND C.DEL_YN = 'N' AND C.PCHPRS_YN = 'Y' JOIN SAA000 D /*통합기관*/ ON D.INST_NO = C.PIC_INST_NO AND D.DEL_YN = 'N' JOIN SEA200 F /*대상자정보*/ ON F.TRPR_INFO_NO = A.TRPR_INFO_NO AND F.DEL_YN = 'N' WHERE B.AFTFCT_MNG_YMD BETWEEN #{SRT_DT} AND #{END_DT} AND A.UNT_TASKWK_SE_CD = #{UNT_TASKWK_SE_CD}
AND D.INST_NO = #{INST_NO}
AND D.CTPV_CD = #{CTPV_CD}
AND D.SGG_CD = #{SGG_CD}
AND #{SRVC_BIZ_CL} IN (SELECT AD3.BIZ_CL_SE_CD FROM SEB120 AD1 JOIN SDA420 AD2 ON AD2.SRVC_EXCN_BIZ_NO = AD1.SRVC_EXCN_BIZ_NO JOIN SDA400 AD3 ON AD3.SRVC_BIZ_NO = AD2.SRVC_BIZ_NO WHERE AD1.CASE_MNG_NO = A.CASE_MNG_NO AND AD1.CASE_MNG_ODRNO = A.CASE_MNG_ODRNO AND AD1.DEL_YN = 'N')
#{instNo}
GROUP BY F.SXDC_SE_CD, B.SRVC_RESRCE_LCLAS_SE_CD ) T ON T.SXDC_SE_CD = T1.SXDC_SE_CD AND T.SRVC_RESRCE_LCLAS_SE_CD = T2.SRVC_RESRCE_LCLAS_SE_CD GROUP BY CUBE(T1.SXDC_SE_CD, T1.SXDC_SE_CD_NM, T1.SXDC_SRTNG_SQNCE, T2.SRVC_RESRCE_LCLAS_SE_CD) HAVING GROUPING(T1.SXDC_SE_CD) = GROUPING(T1.SXDC_SE_CD_NM) AND GROUPING(T1.SXDC_SE_CD_NM) = GROUPING(T1.SXDC_SRTNG_SQNCE) ORDER BY SXDC_SRTNG_SQNCE, SRVC_RESRCE_LCLAS_SE_CD

/*isry.itgcm.fdrmrptstats.mapper.FdrmRptStatsMapper 서비스 만족도(쉼터별) - selectSrvcDgstfnSheltrType - LEE.SEOUNG.JAE*/ WITH TMP AS( SELECT C.SXDC_SE_CD , G.FCLTY_TYPE_SE_CD , C.TRPR_INFO_NO , I.SRVY_SCORE FROM SEB100 A JOIN AEA100 B ON B.CASE_MNG_NO = A.CASE_MNG_NO AND B.CASE_MNG_ODRNO = A.CASE_MNG_ODRNO JOIN SEA200 C ON A.TRPR_INFO_NO = C.TRPR_INFO_NO JOIN AEA130 D ON D.CASE_MNG_NO = A.CASE_MNG_NO AND D.CASE_MNG_ODRNO = A.CASE_MNG_ODRNO JOIN SEB150 E ON A.CASE_MNG_NO = E.CASE_MNG_NO AND A.CASE_MNG_ODRNO = E.CASE_MNG_ODRNO AND E.PCHPRS_YN = 'Y' JOIN SAA000 F ON F.INST_NO = E.PIC_INST_NO JOIN AKA500 G ON G.INST_NO = F.INST_NO JOIN ( SELECT AA.CASE_MNG_NO , AA.CASE_MNG_ODRNO , SUM(CC.QESITM_SINGL_RSPNS_VALUE) AS SRVY_SCORE , ROW_NUMBER() OVER(PARTITION BY AA.CASE_MNG_NO, AA.CASE_MNG_ODRNO ORDER BY AA.QUSTNB_MNG_NO, CC.SRVY_RSPNS_MNG_NO) AS RN FROM SBB110 AA JOIN SBB500 BB ON BB.QUSTNB_MNG_NO = AA.QUSTNB_MNG_NO AND BB.QUSTNB_TMPT_MNG_NO = AA.QUSTNB_TMPT_MNG_NO JOIN SBB220 CC ON CC.SRVY_RSPNS_MNG_NO = BB.SRVY_RSPNS_MNG_NO WHERE AA.QUSTNB_SHAPE_SE_CD = '08' AND BB.RSPNS_DT BETWEEN TO_DATE(#{SRT_DT}||'000000','YYYYMMDDHH24MISS') AND TO_DATE(#{END_DT}||'235959','YYYYMMDDHH24MISS') GROUP BY AA.QUSTNB_MNG_NO, AA.CASE_MNG_NO, AA.CASE_MNG_ODRNO, CC.SRVY_RSPNS_MNG_NO ) I ON I.CASE_MNG_NO = A.CASE_MNG_NO AND I.CASE_MNG_ODRNO = A.CASE_MNG_ODRNO AND I.RN = 1 WHERE A.UNT_TASKWK_SE_CD = #{UNT_TASKWK_SE_CD} AND C.DEL_YN = 'N' AND B.SHELTR_TRPR_SE_CD IN ('1','2') AND G.FCLTY_TYPE_SE_CD IS NOT NULL
-- 시도코드 AND F.CTPV_CD = #{CTPV_CD}
-- 시군구코드 AND F.SGG_CD = #{SGG_CD}
-- 기관번호 AND F.INST_NO = #{INST_NO}
-- 사업분류구분코드 AND #{SRVC_BIZ_CL} IN ( SELECT SRVC_BIZ_CL_SE_CD FROM SEB120 AA JOIN SDA420 BB ON BB.SRVC_EXCN_BIZ_NO = AA.SRVC_EXCN_BIZ_NO JOIN SDA400 CC ON CC.SRVC_BIZ_NO = BB.SRVC_BIZ_NO WHERE AA.DEL_YN = 'N' AND AA.CASE_MNG_NO = A.CASE_MNG_NO AND AA.CASE_MNG_ODRNO = A.CASE_MNG_ODRNO )
-- 사업분류구분코드 AND #{EXCN_SRVC_BIZ_CL} IN ( SELECT SRVC_BIZ_CL_SE_CD FROM SEB120 AA JOIN SDA420 BB ON BB.SRVC_EXCN_BIZ_NO = AA.SRVC_EXCN_BIZ_NO JOIN SDA400 CC ON CC.SRVC_BIZ_NO = BB.SRVC_BIZ_NO WHERE AA.DEL_YN = 'N' AND AA.CASE_MNG_NO = A.CASE_MNG_NO AND AA.CASE_MNG_ODRNO = A.CASE_MNG_ODRNO )
#{instNo}
)
SELECT * FROM( SELECT NVL(A.FCLTY_TYPE_SE_CD,'00') AS FCLTY_TYPE_SE_CD , NVL(A.FCLTY_TYPE_SE_CD_NM, '합계') AS FCLTY_TYPE_SE_CD_NM , NVL(A.SXDC_SE_CD, 'A') AS SXDC_SE_CD , NVL(A.SXDC_SE_CD_NM, '합계') AS SXDC_SE_CD_NM , COUNT(B.TRPR_INFO_NO) AS EVL_CASE_CNT , NVL(ROUND(AVG(B.SRVY_SCORE)*100)/100,0) AS SRVC_DGSTFN_SCORE FROM ( SELECT A.CMMNS_CD_VALUE AS FCLTY_TYPE_SE_CD , A.CMMNS_CD_VALUE_NM AS FCLTY_TYPE_SE_CD_NM , B.CMMNS_CD_VALUE AS SXDC_SE_CD , B.CMMNS_CD_VALUE_NM AS SXDC_SE_CD_NM , B.SRTNG_SQNCE FROM SAC100 A JOIN SAC110 C ON A.CMMNS_CD_ID = C.CMMNS_CD_ID AND A.CMMNS_CD_VALUE = C.CMMNS_CD_VALUE CROSS JOIN SAC100 B
WHERE A.CMMNS_CD_ID = 'FCLTY_TYPE_SE_CD' AND B.CMMNS_CD_ID = 'SXDC_SE_CD' AND C.UNT_TASKWK_SE_CD = #{UNT_TASKWK_SE_CD}
ORDER BY A.CMMNS_CD_VALUE, B.SRTNG_SQNCE ) A LEFT JOIN TMP B ON A.FCLTY_TYPE_SE_CD = B.FCLTY_TYPE_SE_CD AND A.SXDC_SE_CD = B.SXDC_SE_CD GROUP BY CUBE((A.FCLTY_TYPE_SE_CD, FCLTY_TYPE_SE_CD_NM), (A.SXDC_SE_CD, SXDC_SE_CD_NM)) ) ORDER BY CASE WHEN FCLTY_TYPE_SE_CD = '00' THEN 0 WHEN FCLTY_TYPE_SE_CD = '01' THEN 2 WHEN FCLTY_TYPE_SE_CD = '02' THEN 1 WHEN FCLTY_TYPE_SE_CD = '03' THEN 3 WHEN FCLTY_TYPE_SE_CD = '04' THEN 4 END , CASE WHEN SXDC_SE_CD = 'A' THEN 1 WHEN SXDC_SE_CD = 'M' THEN 2 WHEN SXDC_SE_CD = 'F' THEN 3 ELSE 4 END

/*isry.itgcm.fdrmrptstats.mapper.FdrmRptStatsMapper 서비스 만족도(성별)- selectSrvcDgstfnSxdc - LEE.SEOUNG.JAE*/ WITH TMP AS( SELECT C.SXDC_SE_CD , C.TRPR_INFO_NO , I.SRVY_SCORE FROM SEB100 A JOIN AEB120 B ON B.CASE_MNG_NO = A.CASE_MNG_NO AND B.CASE_MNG_ODRNO = A.CASE_MNG_ODRNO JOIN SEA200 C ON A.TRPR_INFO_NO = C.TRPR_INFO_NO JOIN SEB150 E ON A.CASE_MNG_NO = E.CASE_MNG_NO AND A.CASE_MNG_ODRNO = E.CASE_MNG_ODRNO AND E.PCHPRS_YN = 'Y' JOIN SAA000 F ON F.INST_NO = E.PIC_INST_NO JOIN ( SELECT AA.CASE_MNG_NO , AA.CASE_MNG_ODRNO , SUM(CC.QESITM_SINGL_RSPNS_VALUE) AS SRVY_SCORE , ROW_NUMBER() OVER(PARTITION BY AA.CASE_MNG_NO, AA.CASE_MNG_ODRNO ORDER BY AA.QUSTNB_MNG_NO, CC.SRVY_RSPNS_MNG_NO) AS RN FROM SBB110 AA JOIN SBB500 BB ON BB.QUSTNB_MNG_NO = AA.QUSTNB_MNG_NO AND BB.QUSTNB_TMPT_MNG_NO = AA.QUSTNB_TMPT_MNG_NO JOIN SBB220 CC ON CC.SRVY_RSPNS_MNG_NO = BB.SRVY_RSPNS_MNG_NO WHERE AA.QUSTNB_SHAPE_SE_CD = '08' AND BB.RSPNS_DT BETWEEN TO_DATE(#{SRT_DT}||'000000','YYYYMMDDHH24MISS') AND TO_DATE(#{END_DT}||'235959','YYYYMMDDHH24MISS') GROUP BY AA.QUSTNB_MNG_NO, AA.CASE_MNG_NO, AA.CASE_MNG_ODRNO, CC.SRVY_RSPNS_MNG_NO ) I ON I.CASE_MNG_NO = A.CASE_MNG_NO AND I.CASE_MNG_ODRNO = A.CASE_MNG_ODRNO AND I.RN = 1 WHERE A.UNT_TASKWK_SE_CD = #{UNT_TASKWK_SE_CD} AND C.DEL_YN = 'N' AND B.SLFRL_SPRT_TRPR_SE_CD IN ('1','2')
-- 시도코드 AND F.CTPV_CD = #{CTPV_CD}
-- 시군구코드 AND F.SGG_CD = #{SGG_CD}
-- 기관번호 AND F.INST_NO = #{INST_NO}
-- 사업분류구분코드 AND #{SRVC_BIZ_CL} IN ( SELECT SRVC_BIZ_CL_SE_CD FROM SEB120 AA JOIN SDA420 BB ON BB.SRVC_EXCN_BIZ_NO = AA.SRVC_EXCN_BIZ_NO JOIN SDA400 CC ON CC.SRVC_BIZ_NO = BB.SRVC_BIZ_NO WHERE AA.DEL_YN = 'N' AND AA.CASE_MNG_NO = A.CASE_MNG_NO AND AA.CASE_MNG_ODRNO = A.CASE_MNG_ODRNO )
-- 사업분류구분코드 AND #{EXCN_SRVC_BIZ_CL} IN ( SELECT SRVC_BIZ_CL_SE_CD FROM SEB120 AA JOIN SDA420 BB ON BB.SRVC_EXCN_BIZ_NO = AA.SRVC_EXCN_BIZ_NO JOIN SDA400 CC ON CC.SRVC_BIZ_NO = BB.SRVC_BIZ_NO WHERE AA.DEL_YN = 'N' AND AA.CASE_MNG_NO = A.CASE_MNG_NO AND AA.CASE_MNG_ODRNO = A.CASE_MNG_ODRNO )
#{instNo}
)
SELECT * FROM( SELECT NVL(A.SXDC_SE_CD, 'A') AS SXDC_SE_CD , NVL(A.SXDC_SE_CD_NM, '합계') AS SXDC_SE_CD_NM , COUNT(B.TRPR_INFO_NO) AS EVL_CASE_CNT , NVL(ROUND(AVG(B.SRVY_SCORE)*100)/100,0) AS SRVC_DGSTFN_SCORE FROM ( SELECT A.CMMNS_CD_VALUE AS SXDC_SE_CD , A.CMMNS_CD_VALUE_NM AS SXDC_SE_CD_NM FROM SAC100 A
WHERE A.CMMNS_CD_ID = 'SXDC_SE_CD'
ORDER BY A.SRTNG_SQNCE ) A LEFT JOIN TMP B ON A.SXDC_SE_CD = B.SXDC_SE_CD GROUP BY CUBE((A.SXDC_SE_CD, A.SXDC_SE_CD_NM)) ) ORDER BY CASE WHEN SXDC_SE_CD = 'A' THEN 1 WHEN SXDC_SE_CD = 'M' THEN 2 WHEN SXDC_SE_CD = 'F' THEN 3 ELSE 4 END

/*isry.itgcm.fdrmrptstats.mapper.FdrmRptStatsMapper 퇴소사유별현황- selectLvngCsPrecon*/
SELECT NVL(T1.SXDC_SE_CD_NM,'합계') AS SE --구분 , COUNT(T.SPRINT_CNSGN_EXPRY) + COUNT(T.REDUCE) + COUNT(T.DSPS_CHG) + COUNT(T.WTRMS_OUT) + COUNT(T.INST_CLSBIZ) + COUNT(T.SCHULW) + COUNT(T.FCLTY_MALADJ) + COUNT(T.ETC) AS ALLTOT --계 , COUNT(T.SPRINT_CNSGN_EXPRY) AS SPRINT_CNSGN_EXPRY --감호위탁만료 , COUNT(T.REDUCE) + COUNT(T.DSPS_CHG) + COUNT(T.WTRMS_OUT) AS SUBTOT1 --감호위탁취소 소계 , COUNT(T.REDUCE) AS REDUCE --감형 , COUNT(T.DSPS_CHG) AS DSPS_CHG --6~10호처분변경 , COUNT(T.WTRMS_OUT) AS WTRMS_OUT --무단이탈 , COUNT(T.INST_CLSBIZ) + COUNT(T.SCHULW) + COUNT(T.FCLTY_MALADJ) AS SUBTOT2 --감호위탁기관변경 소계 , COUNT(T.INST_CLSBIZ) AS INST_CLSBIZ --기관폐업 , COUNT(T.SCHULW) AS SCHULW --학업(진학,전학) , COUNT(T.FCLTY_MALADJ) AS FCLTY_MALADJ --시설부적응 , COUNT(T.ETC) AS ETC --기타 , NVL(T1.SXDC_SRTNG_SQNCE,0) AS SXDC_SRTNG_SQNCE --성별코드순번 FROM (SELECT A.CMMNS_CD_VALUE AS SXDC_SE_CD --성별구분코드 , A.CMMNS_CD_VALUE_NM AS SXDC_SE_CD_NM --성별구분코드명 , A.SRTNG_SQNCE AS SXDC_SRTNG_SQNCE --성별코드순번 FROM SAC100 A /*공통코드 값*/ LEFT JOIN SAC110 B /*공통코드값 사용시스템*/ ON B.CMMNS_CD_ID = A.CMMNS_CD_ID AND B.CMMNS_CD_VALUE = A.CMMNS_CD_VALUE WHERE A.CMMNS_CD_ID = 'SXDC_SE_CD' AND (B.UNT_TASKWK_SE_CD = #{UNT_TASKWK_SE_CD} OR B.UNT_TASKWK_SE_CD IS NULL) ) T1 LEFT JOIN (SELECT C.SXDC_SE_CD --성별구분코드 , CASE B.TRMN_CS_SE_CD WHEN '020' THEN A.CASE_MNG_NO END AS SPRINT_CNSGN_EXPRY --감호위탁만료 , CASE B.TRMN_CS_SE_CD WHEN '021' THEN A.CASE_MNG_NO END AS REDUCE --감형 , CASE B.TRMN_CS_SE_CD WHEN '022' THEN A.CASE_MNG_NO END AS DSPS_CHG --6~10호처분변경 , CASE B.TRMN_CS_SE_CD WHEN '023' THEN A.CASE_MNG_NO END AS WTRMS_OUT --무단이탈 , CASE B.TRMN_CS_SE_CD WHEN '024' THEN A.CASE_MNG_NO END AS INST_CLSBIZ --기관폐업 , CASE B.TRMN_CS_SE_CD WHEN '025' THEN A.CASE_MNG_NO END AS SCHULW --학업(진학,전학) , CASE B.TRMN_CS_SE_CD WHEN '026' THEN A.CASE_MNG_NO END AS FCLTY_MALADJ --시설부적응 , CASE B.TRMN_CS_SE_CD WHEN '027' THEN A.CASE_MNG_NO END AS ETC --기타 , ROW_NUMBER() OVER(PARTITION BY B.CASE_MNG_NO, B.CASE_MNG_ODRNO ORDER BY B.CASE_TRMN_NO DESC) AS RN FROM SEB100 A /*사례기본*/ JOIN SEC100 B1 /*사례종결(승인)*/ ON B1.CASE_MNG_NO = A.CASE_MNG_NO AND B1.CASE_MNG_ODRNO = A.CASE_MNG_ODRNO AND B1.TRMN_SRNG_RESULT_SE_CD = '02' JOIN SEC100 B /*사례종결(신청)*/ ON B.CASE_MNG_NO = B1.CASE_MNG_NO AND B.CASE_MNG_ODRNO = B1.CASE_MNG_ODRNO AND B.TRMN_SRNG_RESULT_SE_CD = '01' JOIN SEA200 C /*대상자정보*/ ON C.TRPR_INFO_NO = A.TRPR_INFO_NO AND C.DEL_YN = 'N' JOIN SEB150 D /*사례담당자*/ ON D.CASE_MNG_NO = A.CASE_MNG_NO AND D.CASE_MNG_ODRNO = A.CASE_MNG_ODRNO AND D.PCHPRS_YN = 'Y' JOIN SAA000 E /*통합기관*/ ON E.INST_NO = D.PIC_INST_NO AND E.DEL_YN = 'N' WHERE A.CASE_TRMN_YMD BETWEEN #{SRT_DT} AND #{END_YMD} AND A.UNT_TASKWK_SE_CD = #{UNT_TASKWK_SE_CD}
AND E.INST_NO = #{INST_NO}
AND E.CTPV_CD = #{CTPV_CD}
AND E.SGG_CD = #{SGG_CD}
AND #{SRVC_BIZ_CL} IN (SELECT AD3.BIZ_CL_SE_CD FROM SEB120 AD1 JOIN SDA420 AD2 ON AD2.SRVC_EXCN_BIZ_NO = AD1.SRVC_EXCN_BIZ_NO JOIN SDA400 AD3 ON AD3.SRVC_BIZ_NO = AD2.SRVC_BIZ_NO WHERE AD1.CASE_MNG_NO = A.CASE_MNG_NO AND AD1.CASE_MNG_ODRNO = A.CASE_MNG_ODRNO AND AD1.DEL_YN = 'N')
#{instNo}
) T ON T.SXDC_SE_CD = T1.SXDC_SE_CD AND T.RN = 1 GROUP BY CUBE(T1.SXDC_SE_CD, T1.SXDC_SE_CD_NM, T1.SXDC_SRTNG_SQNCE) HAVING GROUPING(T1.SXDC_SE_CD) = GROUPING(T1.SXDC_SE_CD_NM) AND GROUPING(T1.SXDC_SE_CD_NM) = GROUPING(T1.SXDC_SRTNG_SQNCE) ORDER BY SXDC_SRTNG_SQNCE
